INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C1','kor',4,2,'u2',2,'이 단원에서 배울 두 가지 — 한글을 사랑하는 마음 지니기(글자가 필요한 까닭·한글의 특성·한글을 지킨 사람들) · 우리말 사용에 대하여 조사해 보고하는 글 쓰기',ARRAY['[4국04-05][4국03-02]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C2','kor',4,2,'u2',2,'한국어와 한글 — 날마다 입으로 하는 말은 우리말(한국어), 그 말을 눈에 보이게 적는 글자는 우리글(한글) — 말과 글자는 다름',ARRAY['[4국04-05][4국03-02]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C5','kor',4,2,'u2',2,'말과 문자 — 말(언어)은 소리로 생각을 주고받는 것, 문자는 말을 눈에 보이게 적는 약속된 기호 — 말을 대신하려고가 아니라 말을 붙잡아 두려고 생김',ARRAY['[4국04-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C6','kor',4,2,'u2',2,'문자가 꼭 필요한 때 — 말을 못 할 때만이 아니라 할 말을 오래 남기거나 멀리 정확하게 전해야 할 때 — 말은 전해지는 동안 바뀌고 잊힘',ARRAY['[4국04-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C7','kor',4,2,'u2',2,'글자 없던 때의 기록 — 매듭·금·그림으로 기록하면 보는 사람마다 뜻을 다르게 짐작하고, 까닭이나 마음처럼 눈에 안 보이는 것은 나타내기 어려움',ARRAY['[4국04-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C8','kor',4,2,'u2',2,'문자가 하는 일 — 잊지 않고 정확하게 기억하게 돕고(조리 순서) · 멀리 있는 사람에게 생각을 전하고(전자 우편) · 지난 일을 알 수 있게 함(옛 일기)',ARRAY['[4국04-05]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C9','kor',4,2,'u2',2,'시간과 거리를 넘어 쌓이는 지식 — 한 사람이 알아낸 것을 적어 두면 다음 사람이 이어받아 더 알아낼 수 있음 — 문자가 사람들의 지식과 생각을 쌓아 가게 함',ARRAY['[4국04-05]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C10','kor',4,2,'u2',2,'조사할 거리 떠올리기 — 말 때문에 불편했거나 궁금했던 때를 떠올려 우리말에 대해 조사할 거리를 찾음',ARRAY['[4국04-05][4국03-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C11','kor',4,2,'u2',3,'훈민정음을 만든 까닭 — 한자는 글자 수가 많아 익히기 어려워 자기 뜻을 적지 못하는 백성이 많았음 — 세종 대왕은 누구나 쉽게 익혀 쓰는 글자를 만들어 1446년에 널리 알림',ARRAY['[4국04-05][4국02-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C12','kor',4,2,'u2',3,'본떠 만든 기본 글자 — 자음자 ㅁ은 입, ㅅ은 이, ㅇ은 목구멍의 모양 · 모음자 ㆍ는 둥근 하늘, ㅡ는 평평한 땅, ㅣ는 곧게 선 사람을 본뜸',ARRAY['[4국04-05][4국02-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C13','kor',4,2,'u2',3,'획을 더해 만든 자음자 — ㅁ → ㅂ → ㅍ · ㅅ → ㅈ → ㅊ · ㄴ → ㄷ → ㅌ — 기본 글자에 획을 더할수록 소리가 더 세짐',ARRAY['[4국04-05][4국02-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C15','kor',4,2,'u2',3,'합쳐 만든 모음자 — ㅣ 오른쪽에 ㆍ를 붙이면 ㅏ, ㅡ 아래에 ㆍ를 붙이면 ㅜ — 기본 글자를 합쳐 만듦',ARRAY['[4국04-05][4국02-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C16','kor',4,2,'u2',3,'소리와 모양의 짜임 — 비슷한 소리를 내는 글자는 모양도 닮았고(ㅂ·ㅍ·ㅃ), 한 글자는 대체로 같은 소리를 냄 — 적은 수의 글자로 우리말을 두루 읽고 씀',ARRAY['[4국04-05][4국02-02]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C18','kor',4,2,'u2',3,'한글의 소중함과 다른 글자 — 한글의 좋은 점은 한글 자체의 짜임새에 있음 — 다른 글자도 저마다 자기 말을 적어 왔으니 깎아내리지 않고, 한글을 낮추지도 않음',ARRAY['[4국04-05][4국02-02]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C19','kor',4,2,'u2',3,'글에서 찾아 특성 설명하기 — 글에서 찾은 정보를 모아 한글의 특성을 정리하고, 예를 들어 설명함(글에 없는 말로 부풀리지 않음)',ARRAY['[4국04-05][4국02-02]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C20','kor',4,2,'u2',5,'우리말과 한글을 지키고 가꾸는 사람들 — 국어사전을 만드는 사람 · 다른 나라에서 한글을 가르치는 사람 · 외국어를 쉬운 우리말로 다듬는 사람 — 하는 일은 달라도 같은 일을 함',ARRAY['[4국04-05]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C22','kor',4,2,'u2',5,'글에 나온 낱말 — 원고(책으로 펴내려고 미리 쓴 글) · 광복(빼앗긴 나라를 되찾음) · 펴내다(책 따위를 만들어 세상에 내놓다)',ARRAY['[4국04-05]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C23','kor',4,2,'u2',5,'일어난 일의 차례 — 낱말과 뜻을 모아 원고를 쌓음 → 1942년 원고를 빼앗기고 감옥에 갇힘 → 1945년 가을 서울역 창고에서 되찾아 사전을 펴내기 시작함',ARRAY['[4국04-05]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C24','kor',4,2,'u2',5,'행동으로 마음 짐작하기 — 고생하면서도 멈추지 않은 행동에서, 우리말과 글을 잃지 않고 다음 사람들에게 물려주려는 마음을 짐작함',ARRAY['[4국04-05]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C26','kor',4,2,'u2',5,'두 글의 공통점 — 사전 원고를 지킨 사람들은 우리말을 기록으로 남기고, 가갸날을 정한 사람들은 한글의 소중함을 되새기게 함 — 방법은 달라도 자기가 할 수 있는 일로 한글을 아낌',ARRAY['[4국04-05]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C27','kor',4,2,'u2',5,'오늘의 내가 하는 한글 사랑 — 한글 사랑은 대단한 사람만의 일도, 무엇을 금지하는 일도 아님 — 받침까지 바르게 쓰기·모르는 낱말 사전 찾기처럼 내 생활에서 시작함',ARRAY['[4국04-05]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C28','kor',4,2,'u2',5,'한글을 아낀 사람에게 편지 쓰기 — 알게 된 일 → 그때 든 생각 → 앞으로 내가 할 한글 사랑 차례로 씀',ARRAY['[4국04-05]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C29','kor',4,2,'u2',7,'우리말을 바르게 써야 하는 까닭 — 뜻이 정확하게 통함 · 서로의 마음을 지킴 · 조상에게서 이어받아 다음 사람에게 물려줄 유산인 우리말을 아끼고 가꿈',ARRAY['[4국04-05]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C30','kor',4,2,'u2',7,'외국어를 지나치게 쓰는 문제 — 「키즈 룸 이용 룰」처럼 우리말로 충분히 쓸 수 있는데도 외국어를 지나치게 쓰는 것이 문제 — 우리말로 고쳐 씀',ARRAY['[4국04-05]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C31','kor',4,2,'u2',7,'우리말처럼 굳은 말 — 「버스·피아노」처럼 바꿔 쓸 알맞은 우리말이 없이 굳은 말은 써도 됨 — 외국에서 온 말이 다 나쁜 것은 아님',ARRAY['[4국04-05]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C32','kor',4,2,'u2',7,'줄임말은 듣는 사람과 상황 — 듣는 사람이 모르는 줄임말은 뜻이 잘못 전해짐(「생선」) — 줄임말은 듣는 사람과 상황을 살펴 쓰고, 모를 수 있으면 풀어 씀',ARRAY['[4국04-05]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C33','kor',4,2,'u2',7,'거친 말이 하는 일 — 거친 말은 상대의 마음을 다치게 하고 사이를 멀어지게 함 — 놀이 중이라도 쓰지 않음',ARRAY['[4국04-05]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C34','kor',4,2,'u2',7,'다듬은 말 — 스크린 도어 → 안전문 · 내비게이션 → 길도우미 · 홈페이지 → 누리집 — 국립국어원은 외국어를 쉬운 우리말로 다듬은 말을 누리집에 모아 둠',ARRAY['[4국04-05]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C35','kor',4,2,'u2',8,'보고 — 알아보거나 한 일의 과정과 결과를 있는 그대로 알리는 것',ARRAY['[4국03-02][4국06-03]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C36','kor',4,2,'u2',8,'보고하는 글에 들어가는 것 — 조사 대상 · 기간 · 동기 · 방법 · 조사한 내용 · 조사 소감 · 참고 자료와 그 출처',ARRAY['[4국03-02][4국06-03]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C37','kor',4,2,'u2',8,'조사 방법의 종류와 특징 — 설문 조사(여럿에게 같은 질문지) · 면담 조사(직접 만나 묻기) · 인터넷 조사(만든 이 확인·출처) · 책 조사 · 방문 조사',ARRAY['[4국03-02][4국06-03]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C38','kor',4,2,'u2',8,'알아내려는 내용에 맞는 방법 — 「몇 명」은 설문, 「까닭」은 면담, 「뜻」은 사전 — 방법의 개수가 많다고 좋은 보고서도, 한 가지만 써야 하는 것도 아님',ARRAY['[4국03-02][4국06-03]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C39','kor',4,2,'u2',8,'면담할 때 지킬 점 — 질문을 미리 준비하고, 끝까지 듣고, 들은 말을 그대로 적거나 허락을 받고 녹음함',ARRAY['[4국03-02][4국06-03]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C40','kor',4,2,'u2',8,'매체 자료 활용 — 조사 결과에 맞는 표·그림·사진·그래프를 함께 쓰면 읽는 사람이 한눈에 알아봄',ARRAY['[4국03-02][4국06-03]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C41','kor',4,2,'u2',8,'결과를 부풀리지 않기 — 수를 틀리게 적지 않아도 「대부분·거의 모두」 같은 낱말로 부풀리거나 한 명의 말을 「모두」로 넓히면 정확한 보고가 아님',ARRAY['[4국03-02][4국06-03]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C42','kor',4,2,'u2',8,'출처 밝히기 — 옮겨 온 자료는 누가 만든 어떤 자료인지(누리집 이름·찾은 낱말·찾아본 날) 출처를 밝힘 — 「인터넷」만으로는 부족함',ARRAY['[4국03-02][4국06-03]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C43','kor',4,2,'u2',8,'사실과 내 생각은 칸을 나누어 — 조사한 내용에는 알아낸 사실을 있는 그대로, 조사 소감에는 내 생각이나 다짐 — 보고하는 글에도 내 생각은 들어가되 섞지 않음',ARRAY['[4국03-02][4국06-03]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C44','kor',4,2,'u2',10,'조사 주제 정하기 — 관심 있으면서 내가 직접 자료를 모을 수 있는 주제(우리 반 친구들이 아침에 쓰는 인사말) — 너무 큰 주제는 직접 조사할 수 없음',ARRAY['[4국03-02][4국06-03]']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C45','kor',4,2,'u2',10,'설문 질문 만들기 — 한 번에 한 가지만 묻고, 답을 한쪽으로 몰지 않게 물음',ARRAY['[4국03-02][4국06-03]']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C46','kor',4,2,'u2',10,'조사 결과 간추리기 — 부풀리지도 줄이지도 거꾸로 옮기지도 않고 조사한 그대로 간추림(수가 없는 문장도 결과와 맞는지 따짐)',ARRAY['[4국03-02][4국06-03]']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C47','kor',4,2,'u2',10,'처음 · 가운데 · 끝 — 처음 — 제목·조사 대상·기간·동기·방법 · 가운데 — 조사한 내용(사실)과 매체 자료 · 끝 — 조사 소감(내 생각)·참고 자료와 출처',ARRAY['[4국03-02][4국06-03]']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C48','kor',4,2,'u2',10,'점검하고 고쳐 쓰기 — 좋은 보고하는 글은 긴 글이 아니라 믿을 수 있는 글 — 길이를 늘리려고 하지 않은 조사나 말을 지어 넣지 않고, 사실대로 고치고 출처를 분명히 함',ARRAY['[4국03-02][4국06-03]']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C49','kor',4,2,'u2',12,'한글 사랑 시 — 좋은 한글 사랑 시는 행의 수나 낱말의 어려움이 아니라 한글에 대한 내 마음이 또렷하게 담긴 시',ARRAY['[4국04-05][4국03-02]']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C50','kor',4,2,'u2',12,'우리 둘레의 말 조사 계획 — 조사 대상·기간·동기·방법을 구체적으로 정하고, 동기는 우리말 사용과 이어지게 함',ARRAY['[4국04-05][4국03-02]']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C51','kor',4,2,'u2',12,'살펴보는 것은 물건이 아니라 쓰인 말 — 이름을 우리말을 살린 것과 우리말로 쓸 수 있는데 외국어로만 지은 것으로 조사한 그대로 나눔 — 외국어 이름이라고 나쁜 물건이 아님',ARRAY['[4국04-05][4국03-02]']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C52','kor',4,2,'u2',12,'ㄼ 받침의 소리 — ㄼ 받침 뒤에 자음이 오면 대부분 [ㄹ]로 소리 남 — 떫다 [떨따] · 엷고 [열꼬]',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C54','kor',4,2,'u2',12,'소리와 다르게 적는 까닭 — 「밟다 · 밟아 · 밟고」처럼 뜻을 알아보기 쉽게 글자는 원래 모양대로 적고 소리만 바뀌어 냄 — 소리대로 「밥고」라고 적지 않음',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C55','kor',4,2,'u2',12,'더 알아 둘 다듬은 말 — 리플 → 댓글 · 네티즌 → 누리꾼 · 팝업창 → 알림창',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C56','kor',4,2,'u2',12,'겹받침 낱말 바르게 쓰기 — 넋 · 앉다 · 괜찮다 · 값지다 · 흙처럼 두 받침을 함께 바르게 씀',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X01','kor',4,'u2',ARRAY['K4-2-u2-C2']::text[],'입으로 하는 말(한국어)과 그 말을 적는 글자(한글)를 섞어 부른다','말과 글자를 나누어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X03','kor',4,'u2',ARRAY['K4-2-u2-C5','K4-2-u2-C6']::text[],'문자는 말을 할 수 없을 때만 쓰는, 말을 대신하는 것이라고 여긴다','오래 · 멀리 · 정확하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X04','kor',4,'u2',ARRAY['K4-2-u2-C7']::text[],'매듭·금·그림으로 한 기록도 누구나 같은 뜻으로 알아보고 복잡한 것도 쉽게 남긴다고 여긴다','보는 사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X05','kor',4,'u2',ARRAY['K4-2-u2-C8','K4-2-u2-C9']::text[],'문자가 한 역할(기억·멀리 전하기·지난 일 알기)을 엇갈리게 잇거나, 말만으로 충분한 일을 문자가 꼭 필요한 일로 고른다','잊지 않게 · 멀리 · 옛날') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X07','kor',4,'u2',ARRAY['K4-2-u2-C10','K4-2-u2-C44']::text[],'조사 주제를 내 생활·관심과 상관없이 아무거나 고르거나 남을 따라 정하고, 직접 조사할 수 없을 만큼 큰 주제를 고른다','내가 직접 모을 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X08','kor',4,'u2',ARRAY['K4-2-u2-C11']::text[],'훈민정음을 만든 까닭을 임금을 뽐내거나 다른 나라 글자를 없애려는 것으로 여긴다','백성 누구나 쉽게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X09','kor',4,'u2',ARRAY['K4-2-u2-C12']::text[],'기본 글자가 본뜬 것을 엇갈리게 안다','자음자는 몸 · 모음자는 하늘·땅·사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X10','kor',4,'u2',ARRAY['K4-2-u2-C13','K4-2-u2-C14']::text[],'모양이 닮았으면 획을 더한 글자라고 여기거나(ㄹ), 획이 늘면 소리가 약해진다고 여긴다','ㄷ에 획을 더하면 ㅌ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X11','kor',4,'u2',ARRAY['K4-2-u2-C15']::text[],'기본 모음자를 합쳐 만든 글자를 엇갈리게 안다','ㅣ 오른쪽 · ㅡ 아래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X12','kor',4,'u2',ARRAY['K4-2-u2-C16']::text[],'한글이 짜임새 있는 까닭을 모양이 둥글다·글자 수가 많다처럼 상관없는 것으로 든다','본뜸 · 더함 · 소리와 모양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X13','kor',4,'u2',ARRAY['K4-2-u2-C16','K4-2-u2-C17']::text[],'한글은 어떤 낱말에서도 언제나 적힌 대로만 소리 난다고 여긴다','국물 → [궁물]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X14','kor',4,'u2',ARRAY['K4-2-u2-C17']::text[],'소리가 바뀌는 말이 있으니 한글은 짜임새 없는 글자라고 여긴다','짜임은 그대로예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X15','kor',4,'u2',ARRAY['K4-2-u2-C17','K4-2-u2-C54']::text[],'소리가 바뀌는 말은 소리 나는 대로 고쳐 적어야 한다고 여긴다(궁물·밥고)','뜻을 알아보게 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X16','kor',4,'u2',ARRAY['K4-2-u2-C18']::text[],'한글이 가장 좋으니 다른 나라 글자는 형편없고 배울 필요가 없다고 여긴다','다른 글자도 자기 말을 적어 왔어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X17','kor',4,'u2',ARRAY['K4-2-u2-C18']::text[],'글자는 다 비슷하니 한글도 자랑하거나 아낄 까닭이 없다고 여긴다','한글 자체의 짜임새') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X18','kor',4,'u2',ARRAY['K4-2-u2-C21','K4-2-u2-C23','K4-2-u2-C25']::text[],'글에서 일어난 일의 내용이나 때, 차례를 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X19','kor',4,'u2',ARRAY['K4-2-u2-C22','K4-2-u2-C34','K4-2-u2-C55']::text[],'낱말의 뜻이나 외국어와 다듬은 말의 짝을 엇갈리게 안다','문장에 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X20','kor',4,'u2',ARRAY['K4-2-u2-C24']::text[],'인물의 행동에서 마음을 짐작할 때 행동과 상관없이 유명해지고 싶은 마음 등으로 짐작한다','끝까지 한 일이 무엇?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X21','kor',4,'u2',ARRAY['K4-2-u2-C20','K4-2-u2-C27']::text[],'한글 사랑은 사전을 만드는 것처럼 대단한 사람만 하는 큰일이라 나와는 상관없다고 여긴다','내 생활에서 시작해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X22','kor',4,'u2',ARRAY['K4-2-u2-C27']::text[],'한글 사랑은 외국어를 한마디도 쓰지 않거나 외국어를 쓰는 사람을 꾸짖는 것이라고 여긴다','금지하는 일이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X23','kor',4,'u2',ARRAY['K4-2-u2-C19']::text[],'한글의 특성을 설명할 때 글에 없는 말로 부풀린다(세상 모든 소리·쓰는 사람이 가장 많음)','글에서 찾은 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X24','kor',4,'u2',ARRAY['K4-2-u2-C30','K4-2-u2-C31']::text[],'외국어가 한 글자라도 있으면 틀린 글이라고 여기거나, 굳은 말(버스·피아노)까지 새 우리말로 바꿔야 한다고 여긴다','바꿔 쓸 우리말이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X25','kor',4,'u2',ARRAY['K4-2-u2-C30']::text[],'외국어는 멋지니 많이 쓸수록 좋다고 여기거나, 우리말이 있는데도 외국어를 지나치게 쓰는 것을 문제로 보지 않는다','우리말로 쓸 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X26','kor',4,'u2',ARRAY['K4-2-u2-C32']::text[],'내가 아는 줄임말은 듣는 사람이 누구든 써도 된다고 여긴다','누구에게 쓰나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X27','kor',4,'u2',ARRAY['K4-2-u2-C32']::text[],'줄임말은 친구끼리도 절대 쓰면 안 되는 말이라고 여긴다','듣는 사람과 상황') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X28','kor',4,'u2',ARRAY['K4-2-u2-C33']::text[],'놀이 중에 한 거친 말은 장난이라 상대가 괜찮다고 여긴다','고개 숙인 친구의 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X29','kor',4,'u2',ARRAY['K4-2-u2-C29']::text[],'우리말을 바르게 써야 하는 까닭을 글씨·점수처럼 상관없는 것으로 든다','뜻 · 마음 · 가꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X30','kor',4,'u2',ARRAY['K4-2-u2-C35','K4-2-u2-C36']::text[],'보고를 내 생각대로 꾸며 알리는 것으로 여기거나 보고하는 글에 무엇이 들어가는지 잘못 안다','과정과 결과를 있는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X31','kor',4,'u2',ARRAY['K4-2-u2-C38']::text[],'조사 방법을 많이 쓸수록 좋은 보고서라고 여긴다','개수보다 알맞음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X32','kor',4,'u2',ARRAY['K4-2-u2-C38']::text[],'보고서에는 조사 방법을 한 가지만 써야 한다고 여긴다','알맞으면 여럿도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X33','kor',4,'u2',ARRAY['K4-2-u2-C37','K4-2-u2-C38']::text[],'알아내려는 내용에 맞지 않는 조사 방법을 고르거나 방법의 특징을 엇갈리게 안다','몇 명 · 까닭 · 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X34','kor',4,'u2',ARRAY['K4-2-u2-C39']::text[],'면담할 때 끼어들거나, 들은 말을 마음대로 바꾸거나 덧붙여 적는다','들은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X35','kor',4,'u2',ARRAY['K4-2-u2-C41','K4-2-u2-C46']::text[],'수만 틀리지 않으면 정확하다고 여겨 「대부분·거의 모두」 같은 낱말로 결과를 부풀린다','낱말도 결과와 맞나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X37','kor',4,'u2',ARRAY['K4-2-u2-C42']::text[],'옮겨 온 자료를 출처 없이 내 말처럼 쓰거나 출처를 「인터넷」이라고만 쓴다','누가 만든 어떤 자료?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X38','kor',4,'u2',ARRAY['K4-2-u2-C43']::text[],'보고하는 글에는 내 생각을 한 줄도 쓰면 안 된다고 여긴다','조사 소감 칸이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X39','kor',4,'u2',ARRAY['K4-2-u2-C43']::text[],'내 생각이나 근거 없는 짐작을 조사한 사실과 섞어 「조사한 내용」에 쓴다','확인한 사실인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X40','kor',4,'u2',ARRAY['K4-2-u2-C46']::text[],'조사 결과를 거꾸로 옮기거나 엉뚱한 대상에 붙여 옮긴다','가장 많은 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X41','kor',4,'u2',ARRAY['K4-2-u2-C48']::text[],'글을 길게 하려고 하지 않은 조사나 듣지 않은 말을 지어 넣는다','길이보다 믿음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X42','kor',4,'u2',ARRAY['K4-2-u2-C45']::text[],'설문 질문에서 한 번에 두 가지를 묻거나 답을 한쪽으로 몰아준다','하나씩 · 몰지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X43','kor',4,'u2',ARRAY['K4-2-u2-C40']::text[],'매체 자료를 결과와 상관없는 꾸밈으로 여기거나 결과를 알아보기 쉽게 하는 쓰임을 모른다','한눈에 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X44','kor',4,'u2',ARRAY['K4-2-u2-C47']::text[],'처음·가운데·끝에 들어갈 내용을 엇갈리게 안다','과정 · 사실 · 생각과 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X45','kor',4,'u2',ARRAY['K4-2-u2-C49']::text[],'행이 많거나 어려운 낱말이 많을수록 좋은 시라고 여긴다','길이보다 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X46','kor',4,'u2',ARRAY['K4-2-u2-C51']::text[],'외국어 이름을 조사한 것을 물건이 나쁘다는 뜻으로 여기거나, 이름을 조사한 그대로 나누지 못한다','물건이 아니라 쓰인 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X48','kor',4,'u2',ARRAY['K4-2-u2-C52']::text[],'ㄼ 받침 낱말의 소리를 엇갈리게 낸다(대부분 [ㄹ]인 말을 [ㅂ]으로·뒤 소리를 그대로)','떫지 → [떨찌]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X49','kor',4,'u2',ARRAY['K4-2-u2-C56']::text[],'겹받침을 받침 하나로 쓰거나 다른 받침으로 쓴다(흑·안다·갑진)','두 받침을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X50','kor',4,'u2',ARRAY['K4-2-u2-C50']::text[],'조사 동기나 활동을 우리말 사용·한글 사랑과 상관없는 것으로 정한다','우리말과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X51','kor',4,'u2',ARRAY['K4-2-u2-C28']::text[],'한글을 아낀 사람에게 쓰는 편지를 알게 된 일과 다짐 없이 칭찬 한마디로 쓴다','알게 된 일 → 생각 → 다짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X52','kor',4,'u2',ARRAY['K4-2-u2-C26']::text[],'두 글의 공통점을 한 일의 겉모습이 똑같은 것으로만 찾거나 두 글을 관계없는 것으로 여긴다','방법은 달라도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X53','kor',4,'u2',ARRAY['K4-2-u2-C1']::text[],'이 단원에서 배울 내용을 외국어 외우기처럼 단원과 상관없는 것으로 여긴다','한글 사랑 · 보고하는 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X54','kor',4,'u2',ARRAY['K4-2-u2-C19']::text[],'글의 내용으로 질문을 만들 때 낱말의 뜻을 짐작하는 질문, 자신의 경험과 관련지은 질문, 더 궁금한 점을 묻는 질문을 서로 엇갈리게 가른다','낱말 뜻? 내 경험? 글 밖으로 더 궁금한 것?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X55','kor',4,'u2',ARRAY['K4-2-u2-C19']::text[],'문단의 중심 내용을 간추릴 때 그 문단 전체를 묶는 내용 대신 예로 든 낱말이나 자잘한 내용 하나를 중심 내용으로 고른다','이 문단의 문장들을 모두 묶는 말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X56','kor',4,'u2',ARRAY['K4-2-u2-C41','K4-2-u2-C46']::text[],'조사한 결과를 글에 옮길 때 마음대로 줄여 쓴다(까닭 세 가지 가운데 두 가지만 쓰기처럼) — 줄이는 것도 결과를 바꾸는 일임을 모른다','조사한 것이 몇 가지였지? 다 옮겼나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X57','kor',4,'u2',ARRAY['K4-2-u2-C42']::text[],'뉴스 기사를 참고했을 때 출처를 기사 제목만 쓰면 된다고 여긴다(기자 이름·기사 제목·발행한 곳·발행 일자를 모두 밝혀야 함을 모름)','누가 · 무슨 제목 · 어디서 · 언제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X58','kor',4,'u2',ARRAY['K4-2-u2-C49']::text[],'주제어로 몇 행시를 쓸 때 각 행의 첫 글자를 주제어의 글자와 차례대로 맞추지 않는다','한: … / 글: … 처럼 첫 글자를 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X59','kor',4,'u2',ARRAY['K4-2-u2-C47','K4-2-u2-C48']::text[],'보고하는 글에 조사 주제와 상관없는 내용이나 꼭 필요하지 않은 내용까지 넣는다(길게 쓸수록 좋다고 여김)','이 문장이 조사 주제와 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#1','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C7',1,'mc','auto','『국어』 84쪽 1번이에요. 반구대 암각화나 알타미라 동굴 벽화를 보면, 문자가 없었을 때 사람들은 생각을 어떻게 기록했나요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03']::text[],false,'{"seq":1,"concept":"K4-2-u2-C7","difficulty":1,"kind":"mc","stem":"『국어』 84쪽 1번이에요. 반구대 암각화나 알타미라 동굴 벽화를 보면, 문자가 없었을 때 사람들은 생각을 어떻게 기록했나요?","options":[{"t":"바위나 동굴 벽에 그림을 그리거나 새겼다","correct":true},{"t":"책에 글자로 자세히 적어 두었다","mis":"K4-2-u2-X05"},{"t":"휴대 전화로 글을 써서 보냈다","mis":"K4-2-u2-X05"},{"t":"말로만 전해서 아무것도 남기지 않았다","mis":"K4-2-u2-X03"}],"explanation":["암각화는 바위나 동굴의 벽면에 칠하거나 새기거나 쪼아 그린 그림이에요.","문자가 없던 때에는 그림으로 생각을 남겼어요.","책과 휴대 전화는 문자가 생긴 뒤의 일이에요."],"asset":{"type":"passage","lines":["[사진] 울주 대곡리 반구대 암각화","[사진] 아르헨티나 리오 핀투라스 암각화","[사진] 스페인 알타미라 동굴 벽화","암각화: 바위나 동굴의 벽면에 칠하거나 새기거나 쪼아 그린 그림."],"title":"문자가 없었을 때의 기록 — 『국어』 84쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#2','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C8',1,'mc','auto','『국어』 85쪽 그림 ㉯에서 아이가 알림장을 보고 있어요. 이때 문자가 한 역할은 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03']::text[],false,'{"seq":2,"concept":"K4-2-u2-C8","difficulty":1,"kind":"mc","stem":"『국어』 85쪽 그림 ㉯에서 아이가 알림장을 보고 있어요. 이때 문자가 한 역할은 무엇인가요?","options":[{"t":"내용을 정확하고 자세하게 기억할 수 있도록 돕는다","correct":true},{"t":"멀리 떨어진 사람에게 생각을 전한다","mis":"K4-2-u2-X05"},{"t":"과거에 어떤 일이 있었는지 알 수 있게 한다","mis":"K4-2-u2-X05"},{"t":"말을 할 수 없을 때만 말을 대신한다","mis":"K4-2-u2-X03"}],"explanation":["알림장에는 내일 준비할 것이 적혀 있어요.","적어 두면 잊지 않고 정확하게 기억할 수 있어요.","멀리 전하기는 ㉰, 지난 일 알기는 ㉮의 역할이에요."],"asset":{"type":"passage","lines":["㉮ [그림] 옛 책 — 「1423년 4월 5일의 기록:","이웃 나라에서 우리 조선으로 코끼리를 선물로 보냈다.」","㉯ [그림] 알림장을 보는 아이 — 「내일 운동화, 체육 모자, 운동장 수업 준비」","㉰ [그림] 멀리 있는 사람에게 휴대 전화로 글을 써서 보내는 아이","사람들은 생각을 기록하거나 전달하려고 문자를 사용해요."],"title":"그림 ㉮~㉰ — 『국어』 85쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#3','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C8',2,'match','auto','『국어』 85쪽 3번 (1)이에요. 그림 ㉮~㉰에서 문자가 한 역할을 찾아 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u2-C8","difficulty":2,"kind":"match","stem":"『국어』 85쪽 3번 (1)이에요. 그림 ㉮~㉰에서 문자가 한 역할을 찾아 이으세요.","pairs":[{"l":"㉮ 1423년 4월 5일의 기록","r":"과거에 어떤 일이 있었는지 알 수 있다."},{"l":"㉯ 알림장","r":"내용을 정확하고 자세하게 기억할 수 있도록 돕는다."},{"l":"㉰ 휴대 전화로 보낸 글","r":"멀리 떨어진 사람에게 생각을 전한다."}],"mis":"K4-2-u2-X05","explanation":["㉮ 옛 기록을 읽으면 600년 전 일을 알 수 있어요.","㉯ 알림장은 잊지 않게 정확히 적어 둔 것이에요.","㉰ 글을 보내면 멀리 있는 사람에게도 생각이 전해져요."],"asset":{"type":"passage","lines":["㉮ [그림] 옛 책 — 「1423년 4월 5일의 기록:","이웃 나라에서 우리 조선으로 코끼리를 선물로 보냈다.」","㉯ [그림] 알림장을 보는 아이 — 「내일 운동화, 체육 모자, 운동장 수업 준비」","㉰ [그림] 멀리 있는 사람에게 휴대 전화로 글을 써서 보내는 아이","사람들은 생각을 기록하거나 전달하려고 문자를 사용해요."],"title":"그림 ㉮~㉰ — 『국어』 85쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#4','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C6',1,'ox','auto','문자는 말을 할 수 없는 상황에서만 필요해요.',ARRAY['K4-2-u2-X03']::text[],false,'{"seq":4,"concept":"K4-2-u2-C6","difficulty":1,"kind":"ox","stem":"문자는 말을 할 수 없는 상황에서만 필요해요.","answer":"X","reason_options":[{"t":"그림보다 체계적인 기록이 필요할 때, 오래 남기거나 멀리 전할 때에도 문자가 필요해요.","correct":true},{"t":"말을 할 수 있으면 문자는 쓸 일이 없어요.","mis":"K4-2-u2-X03"}],"mis":"K4-2-u2-X03","explanation":["말은 소리라서 하고 나면 사라져요.","문자로 적으면 시간이 흘러도, 멀리 있어도 생각이 전해져요.","그래서 말을 할 수 있어도 문자가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#5','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C9',2,'sa','auto','「문자 이야기」에서 인쇄 기술이 발전하자 문자로 쓰인 무엇을 대량으로 빨리 만들 수 있게 되었나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u2-C9","difficulty":2,"kind":"sa","stem":"「문자 이야기」에서 인쇄 기술이 발전하자 문자로 쓰인 무엇을 대량으로 빨리 만들 수 있게 되었나요? 한 낱말로 쓰세요.","answer":["책"],"explanation":["인쇄 기술은 같은 글을 여러 장 찍어 내는 기술이에요.","문자로 쓰인 책을 많이, 빨리 만들 수 있게 되었어요.","그래서 누구든 책을 읽고 지식을 쌓을 수 있게 되었어요."],"mis":"K4-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#6','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C7',2,'mc','auto','생각 전하기 놀이에서 그림만 보고 속담을 알아맞히기 어려웠던 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X04','K4-2-u2-X03']::text[],false,'{"seq":6,"concept":"K4-2-u2-C7","difficulty":2,"kind":"mc","stem":"생각 전하기 놀이에서 그림만 보고 속담을 알아맞히기 어려웠던 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"그림은 보는 사람마다 뜻을 다르게 짐작할 수 있어서","correct":true},{"t":"그림은 누구나 같은 뜻으로 알아보기 때문에","mis":"K4-2-u2-X04"},{"t":"그림을 잘 그리기만 하면 모두 정확히 맞히기 때문에","mis":"K4-2-u2-X04"},{"t":"속담은 문자로도 적을 수 없는 말이어서","mis":"K4-2-u2-X03"}],"explanation":["같은 그림을 보고도 모둠마다 다른 속담을 떠올렸어요.","그림은 눈에 보이는 것만 나타내서 뜻이 갈리기 쉬워요.","그래서 생각을 정확하게 남기려면 문자가 필요해요."],"asset":{"type":"passage","lines":["① 모둠별로 친구들이 잘 아는 속담을 하나 정한다.","② 그 속담을 잘 설명하는 그림을 그린다. (글자는 쓰지 않는다.)","③ 그림을 다른 모둠에 보여 주고 어떤 속담인지 알아맞히게 한다.","④ 틀린 답이 나오면 그림과 견주며 어디서 오해가 생겼는지 말한다."],"title":"생각 전하기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#7','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C2',2,'mc','auto','『국어』 82쪽 1번에서 친구가 「1학년 국어 시간에 한글을 배운 것이 생각나.」라고 했어요. 여기서 ‘한글’은 무엇인가요?',ARRAY['K4-2-u2-X01','K4-2-u2-X08']::text[],false,'{"seq":7,"concept":"K4-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 82쪽 1번에서 친구가 「1학년 국어 시간에 한글을 배운 것이 생각나.」라고 했어요. 여기서 ‘한글’은 무엇인가요?","options":[{"t":"우리말을 눈에 보이게 적는 글자","correct":true},{"t":"우리가 날마다 입으로 하는 말","mis":"K4-2-u2-X01"},{"t":"영어를 적는 글자","mis":"K4-2-u2-X01"},{"t":"한자를 다르게 부르는 이름","mis":"K4-2-u2-X08"}],"explanation":["입으로 하는 우리말은 한국어예요.","그 말을 적는 우리글이 한글이에요.","로마자가 영어를 적는 문자이듯 한글은 한국어를 적는 문자예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"1학년 국어 시간에 한글을 배운 것이 생각나."},{"who":"친구 2","text":"영어를 배울 때 우리말과 다른 점이 많아서 흥미로웠어."},{"who":"친구 3","text":"글을 배워서 간판을 읽을 수 있게 되었을 때 기분이 좋았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#8','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C10',2,'mc','auto','『국어』 81쪽 생각 열기예요. 할아버지께서 알쏭달쏭한 표정을 지으신 까닭은 무엇일까요?',ARRAY['K4-2-u2-X26','K4-2-u2-X18']::text[],false,'{"seq":8,"concept":"K4-2-u2-C10","difficulty":2,"kind":"mc","stem":"『국어』 81쪽 생각 열기예요. 할아버지께서 알쏭달쏭한 표정을 지으신 까닭은 무엇일까요?","options":[{"t":"‘심쿵했다’는 말이 무슨 뜻인지 이해하지 못하셔서","correct":true},{"t":"‘심쿵’은 누구나 아는 말이라 장난으로 물으셔서","mis":"K4-2-u2-X26"},{"t":"꽃집 간판에 외국어가 있어서","mis":"K4-2-u2-X18"}],"explanation":["할아버지께서 「심쿵? 무슨 말이지?」라고 되물으셨어요.","줄임말을 모르는 사람과는 뜻이 잘 통하지 않아요.","이런 불편한 일이 우리말에 대해 조사할 거리가 돼요."],"asset":{"type":"passage","lines":["[그림] 「우리 꽃집」 간판 앞에서 꽃집 주인이 고민하고 있다.","꽃집 주인: “가게 이름에 외국어를 넣으면 더 멋져 보일까?”","[그림] 「달콤 cafe」 앞 의자에 여자아이와 할아버지가 앉아 있다.","여자아이: “그 영상을 보고 정말 심쿵했다니까요.”","할아버지: “심쿵? 무슨 말이지?”","우리말과 우리글을 올바르게 쓰려면 어떤 노력을 해야 할까요?"],"title":"생각 열기 — 『국어』 81쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#9','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C1',1,'mc','auto','『국어』 83쪽 「무엇을 배울까요」에서 이 단원에서 공부할 두 가지로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X53']::text[],false,'{"seq":9,"concept":"K4-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 83쪽 「무엇을 배울까요」에서 이 단원에서 공부할 두 가지로 알맞은 것은 무엇인가요?","options":[{"t":"한글을 사랑하는 마음 지니기, 우리말 사용에 대하여 보고하는 글 쓰기","correct":true},{"t":"영어 낱말 외우기, 외국어 간판 만들기","mis":"K4-2-u2-X53"},{"t":"동시 외우기, 동화 바꾸어 쓰기","mis":"K4-2-u2-X53"},{"t":"받아쓰기, 글씨 예쁘게 꾸미기","mis":"K4-2-u2-X53"}],"explanation":["소단원 1은 한글을 사랑하는 마음 지니기예요.","소단원 2는 우리말 사용에 대하여 보고하는 글 쓰기예요.","문자 → 한글의 특성 → 한글 사랑 → 바른 우리말 → 보고하는 글 차례로 배워요."],"asset":{"type":"passage","lines":["소단원 1 한글을 사랑하는 마음 지니기","① 문자가 필요한 까닭 알기 ② 한글의 특성 이해하기","③ 한글을 소중히 여기는 마음 지니기","소단원 2 우리말 사용에 대하여 보고하는 글 쓰기","① 우리말을 바르게 써야 하는 까닭 알기 ② 보고하는 글을 쓰는 방법 알기","③ 우리말 사용에 대하여 조사해 보고하는 글 쓰기"],"title":"무엇을 배울까요 — 『국어』 83쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_basic#10','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C6',3,'mc','auto','『국어활동』 22쪽이에요. 형의 마지막 말 「왜냐하면 ……」 뒤에 이어질 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X03','K4-2-u2-X04','K4-2-u2-X05']::text[],false,'{"seq":10,"concept":"K4-2-u2-C6","difficulty":3,"kind":"mc","stem":"『국어활동』 22쪽이에요. 형의 마지막 말 「왜냐하면 ……」 뒤에 이어질 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"시간이 흐르거나 장소가 바뀌어도 내용을 잘 남길 수 있기 때문이야","correct":true},{"t":"말을 할 수 없을 때 대신 쓰려고 만든 것이기 때문이야","mis":"K4-2-u2-X03"},{"t":"그림을 그리는 것보다 재미있기 때문이야","mis":"K4-2-u2-X04"},{"t":"알림장을 예쁘게 꾸밀 수 있기 때문이야","mis":"K4-2-u2-X05"}],"explanation":["동생은 알림장 쓰기가 귀찮다고 했어요.","하지만 문자가 없으면 내일 할 일도, 지난 일도 남길 수 없어요.","문자는 시간과 장소를 넘어 생각을 남기고 전해 줘요."],"asset":{"type":"speech","turns":[{"who":"동생","text":"형! 나 문자 없는 세상에서 살고 싶어!"},{"who":"형","text":"뭐라고? 그게 무슨 말이야?"},{"who":"동생","text":"날마다 알림장 쓰기도 귀찮고, 영어 시간에 알파벳 쓰는 것도 어렵단 말이야!"},{"who":"형","text":"그랬구나. 그래도 우리 생활에 문자는 꼭 필요해. 왜냐하면 ……"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#1','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C5',2,'mc','auto','『국어』 85쪽 「사람들은 생각을 기록하거나 전달하려고 문자를 사용해요.」를 읽고 말과 문자를 견주었어요. 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X03','K4-2-u2-X01','K4-2-u2-X04']::text[],false,'{"seq":1,"concept":"K4-2-u2-C5","difficulty":2,"kind":"mc","stem":"『국어』 85쪽 「사람들은 생각을 기록하거나 전달하려고 문자를 사용해요.」를 읽고 말과 문자를 견주었어요. 알맞은 것은 무엇인가요?","options":[{"t":"말은 소리라서 하고 나면 사라지지만, 문자는 눈에 보이게 남는다","correct":true},{"t":"문자는 말을 못 하는 사람만 쓰는 것이다","mis":"K4-2-u2-X03"},{"t":"한국어와 한글은 같은 것을 부르는 두 이름이다","mis":"K4-2-u2-X01"},{"t":"그림도 문자처럼 누구나 같은 뜻으로 읽는다","mis":"K4-2-u2-X04"}],"explanation":["말은 소리로 생각을 주고받는 것이에요.","문자는 말을 눈에 보이게 적는 약속된 기호예요.","그래서 문자로 적으면 생각을 오래 남기고 멀리 전할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#2','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C5',2,'mc','auto','글자에는 그림 글자, 뜻글자, 소리글자가 있어요. 소리글자인 한글이 그림 글자나 뜻글자보다 배우기 쉬운 까닭은 무엇인가요?',ARRAY['K4-2-u2-X12','K4-2-u2-X09','K4-2-u2-X08']::text[],false,'{"seq":2,"concept":"K4-2-u2-C5","difficulty":2,"kind":"mc","stem":"글자에는 그림 글자, 뜻글자, 소리글자가 있어요. 소리글자인 한글이 그림 글자나 뜻글자보다 배우기 쉬운 까닭은 무엇인가요?","options":[{"t":"몇 가지 기본 글자만 익히면 말소리를 적을 수 있어서","correct":true},{"t":"글자 수가 아주 많아 무엇이든 적을 수 있어서","mis":"K4-2-u2-X12"},{"t":"사물 모양을 그대로 그린 글자라서","mis":"K4-2-u2-X09"},{"t":"한자를 조금 바꾸어 만든 글자라서","mis":"K4-2-u2-X08"}],"explanation":["그림 글자와 뜻글자는 배워야 할 기본 글자 수가 너무 많아요.","소리글자는 말의 소리를 그대로 나타내요.","그래서 기본 글자 몇 개만 익히면 누구나 쉽게 배울 수 있어요."],"asset":{"type":"passage","lines":["그림 글자 — 사물을 단순한 그림으로 그려 생각을 나타낸 글자","뜻글자 — 그림 글자를 바탕으로 다른 뜻까지 나타낸 글자(한자)","소리글자 — 말의 소리를 그대로 나타낸 글자(한글, 영어)","그림 글자와 뜻글자는 배워야 할 기본 글자 수가 너무 많다.","소리글자는 몇 가지 기본 글자만 익히면 누구나 쉽게 배울 수 있다."],"title":"그림 글자, 뜻글자, 소리글자 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#3','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C8',3,'error','auto','친구들이 『국어』 85쪽 그림 ㉮~㉰에서 문자가 한 역할을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u2-X05']::text[],false,'{"seq":3,"concept":"K4-2-u2-C8","difficulty":3,"kind":"error","stem":"친구들이 『국어』 85쪽 그림 ㉮~㉰에서 문자가 한 역할을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서: ㉮ 1423년의 기록은 멀리 떨어진 사람에게 생각을 전한 거야.","correct":true,"mis_target":"K4-2-u2-X05"},{"t":"나래: ㉯ 알림장은 내용을 정확하고 자세하게 기억하도록 도와.","mis":"K4-2-u2-X05"},{"t":"은호: ㉰ 휴대 전화로 보낸 글은 멀리 있는 사람에게 생각을 전해.","mis":"K4-2-u2-X05"}],"explanation":["㉮는 600년쯤 전에 있었던 일을 적은 기록이에요.","오늘 우리가 그 기록을 읽고 과거에 어떤 일이 있었는지 알 수 있어요.","그래서 ㉮의 역할은 「과거에 어떤 일이 있었는지 알 수 있다」예요."],"asset":{"type":"passage","lines":["㉮ [그림] 옛 책 — 「1423년 4월 5일의 기록:","이웃 나라에서 우리 조선으로 코끼리를 선물로 보냈다.」","㉯ [그림] 알림장을 보는 아이 — 「내일 운동화, 체육 모자, 운동장 수업 준비」","㉰ [그림] 멀리 있는 사람에게 휴대 전화로 글을 써서 보내는 아이","사람들은 생각을 기록하거나 전달하려고 문자를 사용해요."],"title":"그림 ㉮~㉰ — 『국어』 85쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#4','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C6',3,'mc','auto','다음 가운데 문자가 꼭 필요한 상황은 어느 것인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X04']::text[],false,'{"seq":4,"concept":"K4-2-u2-C6","difficulty":3,"kind":"mc","stem":"다음 가운데 문자가 꼭 필요한 상황은 어느 것인가요?","options":[{"t":"체험 학습에서 본 것을 다음 주 발표 때까지 정확하게 남겨 두기","correct":true},{"t":"운동장 건너편 친구를 큰 소리로 부르기","mis":"K4-2-u2-X05"},{"t":"짝과 마주 보고 오늘 기분 이야기하기","mis":"K4-2-u2-X05"},{"t":"그림 한 장만 보여 주면 모두가 같은 뜻으로 알아볼 일","mis":"K4-2-u2-X04"}],"explanation":["일주일이 지나면 본 것을 잊기 쉬워요.","문자로 적어 두면 시간이 흘러도 정확하게 남아요.","마주 보고 하는 이야기는 말로도 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#5','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C9',3,'ox','auto','인쇄 기술이 발전하자 문자로 쓰인 책을 빨리 많이 만들 수 있어서, 누구든 책을 읽고 지식을 쌓을 수 있게 되었어요.',ARRAY['K4-2-u2-X05']::text[],false,'{"seq":5,"concept":"K4-2-u2-C9","difficulty":3,"kind":"ox","stem":"인쇄 기술이 발전하자 문자로 쓰인 책을 빨리 많이 만들 수 있어서, 누구든 책을 읽고 지식을 쌓을 수 있게 되었어요.","answer":"O","reason_options":[{"t":"문자로 적은 지식은 시간과 거리를 넘어 많은 사람에게 전해져 쌓여 가요.","correct":true},{"t":"책이 많아져도 지식은 처음 안 사람에게만 남아요.","mis":"K4-2-u2-X05"}],"mis":"K4-2-u2-X05","explanation":["「문자 이야기」 2번 (2)의 내용이에요.","책이 많아지자 여러 사람이 같은 지식을 나누어 가졌어요.","앞 사람이 적은 것을 이어받아 더 많은 것을 알아낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#6','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C10',3,'mc','auto','『국어』 83쪽 3번 생각 그물이에요. 우리말 사용에 대하여 조사하고 싶은 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X07']::text[],false,'{"seq":6,"concept":"K4-2-u2-C10","difficulty":3,"kind":"mc","stem":"『국어』 83쪽 3번 생각 그물이에요. 우리말 사용에 대하여 조사하고 싶은 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 반 친구들이 많이 쓰는 줄임말","correct":true},{"t":"우리 반 친구들이 좋아하는 운동 경기","mis":"K4-2-u2-X07"},{"t":"세계에서 가장 높은 산의 높이","mis":"K4-2-u2-X07"},{"t":"우주에 있는 별의 수","mis":"K4-2-u2-X07"}],"explanation":["이 단원의 조사 주제는 우리말과 우리글이에요.","줄임말은 우리가 날마다 쓰는 말과 이어져 있어요.","운동 경기나 산 높이는 우리말 사용과 상관없어요."],"asset":{"type":"passage","lines":["가운데: 우리말과 우리글","· 외국인이 한글을 배울 때 어려운 점","· 우리 반 친구들이 많이 쓰는 줄임말","· 옛날과 오늘날의 우리말 차이","· 우리글인 한글이 만들어진 과정","· 한글과 한자의 공통점과 차이점"],"title":"조사하고 싶은 내용 생각 그물 — 『국어』 83쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#7','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C10',3,'mc','auto','조사하고 싶은 내용이 떠오르지 않는 하랑이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X07']::text[],false,'{"seq":7,"concept":"K4-2-u2-C10","difficulty":3,"kind":"mc","stem":"조사하고 싶은 내용이 떠오르지 않는 하랑이에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"말이나 글 때문에 불편했거나 궁금했던 때를 떠올려 봐.","correct":true},{"t":"친구가 정한 주제를 그대로 따라 하면 돼.","mis":"K4-2-u2-X07"},{"t":"한 번에 조사할 수 없을 만큼 큰 주제를 골라야 멋져.","mis":"K4-2-u2-X07"}],"explanation":["조사할 거리는 내 국어 생활에서 찾아요.","할아버지께서 ‘심쿵’을 못 알아들으신 것처럼 불편했던 때가 좋은 거리예요.","남을 따라 하거나 너무 큰 주제는 조사하기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#8','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C6',4,'essay','teacher','『국어』 85쪽 3번 (2)예요. 문자가 없으면 불편한 점을 생각해 보고 문자가 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C6","difficulty":4,"kind":"essay","stem":"『국어』 85쪽 3번 (2)예요. 문자가 없으면 불편한 점을 생각해 보고 문자가 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 문자가 없으면 시간이 흐르거나 먼 거리에 있거나 사람이 기억하지 못해서 생각을 전달하기 어렵다. 알림장이 없으면 준비물을 잊고, 옛 기록이 없으면 지난 일을 알 수 없다. 사람들이 생각을 효과적으로 남기거나 전하려면 문자가 필요하다.","scoring_points":["문자가 없을 때 불편한 점(시간·거리·기억)을 썼는가","문자가 필요한 까닭(남기기·전하기)을 썼는가","생활 속 예를 들었는가"]},"explanation":["그림 ㉮~㉰에서 문자가 한 역할을 떠올려요.","그 역할이 없어지면 무엇이 불편한지 생각해요.","불편한 점을 뒤집으면 문자가 필요한 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#9','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C7',4,'mc','auto','생각 전하기 놀이 ④에서 틀린 답이 나온 까닭을 이야기했어요. 문자의 필요성과 이어서 가장 알맞게 정리한 것은 무엇인가요?',ARRAY['K4-2-u2-X04','K4-2-u2-X03']::text[],false,'{"seq":9,"concept":"K4-2-u2-C7","difficulty":4,"kind":"mc","stem":"생각 전하기 놀이 ④에서 틀린 답이 나온 까닭을 이야기했어요. 문자의 필요성과 이어서 가장 알맞게 정리한 것은 무엇인가요?","options":[{"t":"그림은 눈에 보이는 것은 나타내도 속뜻처럼 보이지 않는 것은 나타내기 어려워 문자가 필요하다","correct":true},{"t":"그림을 더 크게 그리면 누구나 같은 뜻으로 알아본다","mis":"K4-2-u2-X04"},{"t":"틀린 모둠은 그림을 못 그렸을 뿐 문자와는 상관없다","mis":"K4-2-u2-X04"},{"t":"속담은 원래 말로만 전하는 것이라 적을 필요가 없다","mis":"K4-2-u2-X03"}],"explanation":["속담에는 눈에 보이지 않는 속뜻이 담겨 있어요.","그림으로는 그 뜻을 정확하게 나타내기 어려워요.","그래서 사람들은 그림보다 체계적인 기록 수단인 문자를 만들었어요."],"asset":{"type":"passage","lines":["① 모둠별로 친구들이 잘 아는 속담을 하나 정한다.","② 그 속담을 잘 설명하는 그림을 그린다. (글자는 쓰지 않는다.)","③ 그림을 다른 모둠에 보여 주고 어떤 속담인지 알아맞히게 한다.","④ 틀린 답이 나오면 그림과 견주며 어디서 오해가 생겼는지 말한다."],"title":"생각 전하기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L02_challenge#10','kor',4,2,'u2','L02','tb_g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C1',4,'essay','teacher','『국어』 82쪽 2번 물음 가운데 하나를 골라 자신의 태도를 스스로 점검하고, 이 단원을 배우며 실천하고 싶은 것을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C1","difficulty":4,"kind":"essay","stem":"『국어』 82쪽 2번 물음 가운데 하나를 골라 자신의 태도를 스스로 점검하고, 이 단원을 배우며 실천하고 싶은 것을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「자신이 사용하는 말에 관심을 가지려고 노력하나요?」에 ●●(잘함)을 주었다. 친구와 말할 때 줄임말을 자주 쓰는데 그 말이 바른지 생각해 본 적이 별로 없기 때문이다. 이 단원을 배우며 내가 자주 쓰는 줄임말을 조사해 보고, 할머니처럼 모르실 수 있는 분께는 풀어서 말하겠다.","scoring_points":["물음 하나를 골라 스스로 평가했는가","그렇게 평가한 까닭을 썼는가","단원에서 실천하고 싶은 것을 썼는가"]},"explanation":["세 물음은 우리말에 대한 관심, 한글을 소중히 여기는 마음, 올바르게 쓰려는 노력이에요.","자신의 생활을 떠올려 솔직하게 점검해요.","단원을 마칠 때 『국어』 109쪽에서 다시 돌아봐요."],"asset":{"type":"passage","lines":["자신이 사용하는 말에 관심을 가지려고 노력하나요?  ○○○","한글을 소중하게 생각하는 마음을 지니고 있나요?  ○○○","우리말과 우리글을 올바르게 사용하려고 노력하나요?  ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"우리말과 우리글에 대한 자신의 태도 — 『국어』 82쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#1','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C11',1,'sa','auto','「한글이 과학적인 문자인 까닭」 첫 문단이에요. 옛날 우리 조상은 중국의 어떤 문자를 빌려 우리말을 썼나요?','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C11","difficulty":1,"kind":"sa","stem":"「한글이 과학적인 문자인 까닭」 첫 문단이에요. 옛날 우리 조상은 중국의 어떤 문자를 빌려 우리말을 썼나요?","answer":["한자"],"explanation":["첫 문장을 다시 읽어요.","「중국의 문자인 한자를 빌려 우리말을 썼습니다.」라고 했어요.","한자는 수가 많아 배우는 데 많은 시간과 노력이 필요했어요."],"asset":{"type":"passage","lines":["옛날 우리 조상은 중국의 문자인 한자를 빌려 우리말을 썼습니다.","뜻글자인 한자는 그 수가 많아 배우는 데 많은 시간과 노력이 필요했습니다.","(간추림) 대부분의 백성은 글자를 읽거나 쓸 수 없어 억울한 일을 당하기도 했다.","(간추림) 세종 대왕은 백성이 자신의 뜻을 글로 나타내지 못함을 안타까워했다.","(간추림) 세종 대왕은 적은 수의 문자로 누구나 우리말을 읽고 쓰는 훈민정음을 만들었다.","훈민정음은 백성을 가르치는 바른 소리라는 뜻으로,","(간추림) 오늘날 우리가 쓰는 한글의 바탕이 되었다."],"title":"「한글이 과학적인 문자인 까닭」 1·2문단 — 『국어』 86쪽"},"mis":"K4-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#2','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C11',1,'blank','auto','「훈민정음은 백성을 (     ) 바른 소리라는 뜻」이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X08']::text[],false,'{"seq":2,"concept":"K4-2-u2-C11","difficulty":1,"kind":"blank","stem":"「훈민정음은 백성을 (     ) 바른 소리라는 뜻」이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"가르치는","correct":true},{"t":"다스리는","mis":"K4-2-u2-X08"},{"t":"부르는","mis":"K4-2-u2-X08"},{"t":"즐겁게 하는","mis":"K4-2-u2-X08"}],"explanation":["훈민정음은 세종 대왕이 만든 글자의 이름이에요.","「백성을 가르치는 바른 소리」라는 뜻이에요.","훈민정음은 오늘날 우리가 쓰는 한글의 바탕이 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#3','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C12',1,'match','auto','『국어활동』 23쪽 3번 (1)이에요. 한글의 자음자 기본 글자와 본뜬 발음 기관의 모양을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u2-C12","difficulty":1,"kind":"match","stem":"『국어활동』 23쪽 3번 (1)이에요. 한글의 자음자 기본 글자와 본뜬 발음 기관의 모양을 이으세요.","pairs":[{"l":"ㄱ","r":"혀뿌리가 목구멍을 막는 모양"},{"l":"ㄴ","r":"혀가 윗잇몸에 닿는 모양"},{"l":"ㅁ","r":"입의 모양"},{"l":"ㅅ","r":"이의 모양"},{"l":"ㅇ","r":"목구멍의 모양"}],"mis":"K4-2-u2-X09","explanation":["자음자의 기본 글자는 ㄱ, ㄴ, ㅁ, ㅅ, ㅇ 다섯이에요.","소리를 낼 때 발음 기관의 모양과 움직임을 본떴어요.","헷갈리면 『국어』 86~87쪽 셋째 문단을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#4','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C12',1,'mc','auto','모음자의 기본 글자 ‘ㅣ’가 본뜬 것은 무엇인가요?',ARRAY['K4-2-u2-X09']::text[],false,'{"seq":4,"concept":"K4-2-u2-C12","difficulty":1,"kind":"mc","stem":"모음자의 기본 글자 ‘ㅣ’가 본뜬 것은 무엇인가요?","options":[{"t":"하늘과 땅을 연결하는 사람의 모양","correct":true},{"t":"둥근 하늘","mis":"K4-2-u2-X09"},{"t":"평평한 땅","mis":"K4-2-u2-X09"},{"t":"목구멍의 모양","mis":"K4-2-u2-X09"}],"explanation":["모음자 기본 글자는 ㆍ, ㅡ, ㅣ 셋이에요.","ㆍ는 하늘, ㅡ는 땅, ㅣ는 하늘과 땅을 연결하는 사람이에요.","우리 민족이 중요하게 생각한 세 가지를 본떴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#5','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C13',2,'mc','auto','넷째 문단에서 자음자는 소리가 강하게 날수록 어떻게 나타냈다고 했나요?',ARRAY['K4-2-u2-X10','K4-2-u2-X11','K4-2-u2-X12']::text[],false,'{"seq":5,"concept":"K4-2-u2-C13","difficulty":2,"kind":"mc","stem":"넷째 문단에서 자음자는 소리가 강하게 날수록 어떻게 나타냈다고 했나요?","options":[{"t":"기본 글자에 획을 더해 나타냈다","correct":true},{"t":"기본 글자에서 획을 빼서 나타냈다","mis":"K4-2-u2-X10"},{"t":"모음자를 합쳐서 나타냈다","mis":"K4-2-u2-X11"},{"t":"글자 모양을 둥글게 바꾸었다","mis":"K4-2-u2-X12"}],"explanation":["「소리가 강하게 날수록 획을 더해 나타냈습니다.」라고 했어요.","획이 늘수록 소리가 더 강해져요.","모음자는 획을 더하지 않고 ㆍ, ㅡ, ㅣ를 합쳐 만들었어요."],"asset":{"type":"passage","lines":["(간추림) 둘째, 기본 글자를 확장해 다른 글자를 만들었다.","(간추림) 자음자는 ㄱ, ㄴ, ㅁ, ㅅ, ㅇ에 획을 더해 만들었다.","소리가 강하게 날수록 획을 더해 나타냈습니다.","(간추림) 모음자는 ㆍ, ㅡ, ㅣ를 합쳐 만들었다.","(간추림) 기본 글자를 한 번씩 합치면 ㅗ, ㅏ, ㅜ, ㅓ가 되고,","(간추림) 여기에 ㆍ를 한 번 더 합치면 ㅛ, ㅑ, ㅠ, ㅕ가 된다."],"title":"「한글이 과학적인 문자인 까닭」 4문단 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#6','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C15',2,'blank','auto','모음자는 기본 글자를 합쳐 만들었어요. 「ㅣ의 오른쪽에 ㆍ를 합치면 (     )가 됩니다.」 빈칸에 알맞은 글자는 무엇인가요?',ARRAY['K4-2-u2-X11']::text[],false,'{"seq":6,"concept":"K4-2-u2-C15","difficulty":2,"kind":"blank","stem":"모음자는 기본 글자를 합쳐 만들었어요. 「ㅣ의 오른쪽에 ㆍ를 합치면 (     )가 됩니다.」 빈칸에 알맞은 글자는 무엇인가요?","options":[{"t":"ㅏ","correct":true},{"t":"ㅓ","mis":"K4-2-u2-X11"},{"t":"ㅗ","mis":"K4-2-u2-X11"},{"t":"ㅜ","mis":"K4-2-u2-X11"}],"explanation":["ㅣ 오른쪽에 ㆍ가 붙으면 ㅏ예요.","ㅣ 왼쪽에 붙으면 ㅓ, ㅡ 위에 붙으면 ㅗ, ㅡ 아래에 붙으면 ㅜ예요.","여기에 ㆍ를 한 번 더 합치면 ㅑ, ㅕ, ㅛ, ㅠ가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#7','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C16',2,'mc','auto','다섯째 문단에서 한글의 ‘ㅏ’와 영어 알파벳의 A를 견준 까닭은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X12','K4-2-u2-X14']::text[],false,'{"seq":7,"concept":"K4-2-u2-C16","difficulty":2,"kind":"mc","stem":"다섯째 문단에서 한글의 ‘ㅏ’와 영어 알파벳의 A를 견준 까닭은 무엇인가요?","options":[{"t":"한글은 한 글자가 어떤 낱말에 쓰여도 같은 소리를 낸다는 것을 보여 주려고","correct":true},{"t":"영어 글자는 형편없다는 것을 보여 주려고","mis":"K4-2-u2-X16"},{"t":"한글 글자의 모양이 더 둥글다는 것을 보여 주려고","mis":"K4-2-u2-X12"},{"t":"한글도 낱말마다 소리가 제멋대로 바뀐다는 것을 보여 주려고","mis":"K4-2-u2-X14"}],"explanation":["A는 여러 낱말에서 다양하게 소리가 나요.","한글의 ‘ㅏ’는 어떤 낱말에 쓰여도 같은 소리를 내요.","하나의 글자로 하나의 소리를 나타내는 규칙을 보여 주려는 거예요."],"asset":{"type":"passage","lines":["(간추림) 셋째, 소리와 글자가 규칙적으로 연결된다.","(간추림) 한글은 하나의 글자로 하나의 우리말 소리를 나타낸다.","(간추림) 영어 알파벳의 A는 여러 낱말에서 다양하게 소리가 나지만","한글의 ‘ㅏ’는 어떤 낱말에 쓰여도 같은 소리를 냅니다.","(간추림) 영어의 K와 G는 소리가 비슷한데 모양은 아주 다르다.","(간추림) 한글은 ㄱ, ㅋ, ㄲ처럼 비슷한 소리를 내는 글자가 모양도 비슷하다."],"title":"「한글이 과학적인 문자인 까닭」 5문단 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#8','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C19',2,'mc','auto','『국어』 89쪽 4번이에요. 빈칸 4에 들어갈 넷째 문단의 중심 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X55','K4-2-u2-X18']::text[],false,'{"seq":8,"concept":"K4-2-u2-C19","difficulty":2,"kind":"mc","stem":"『국어』 89쪽 4번이에요. 빈칸 4에 들어갈 넷째 문단의 중심 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"기본 글자를 확장해 다른 글자를 만들었다","correct":true},{"t":"ㆍ를 한 번 더 합치면 ㅛ, ㅑ, ㅠ, ㅕ가 된다","mis":"K4-2-u2-X55"},{"t":"한자는 배우기 어려워 글을 모르는 백성이 많았다","mis":"K4-2-u2-X18"}],"explanation":["넷째 문단은 「둘째, 기본 글자를 확장해 다른 글자를 만들었습니다.」로 시작해요.","획을 더한 자음자, 합친 모음자는 그 예예요.","예 하나가 아니라 문단 전체를 묶는 말이 중심 내용이에요."],"asset":{"type":"passage","lines":["1 한자는 배우기 어려워 글자를 읽거나 쓰지 못하는 백성이 많았다.","2 한글은 훈민정음을 바탕에 두었으며 과학적인 문자로 평가받는다.","3 발음 기관과 하늘, 땅, 사람의 모양을 바탕으로 기본 글자를 만들었다.","4 (                    )","5 소리와 글자가 규칙적으로 연결된다.","6 한글은 과학적인 문자이기 때문에 쉽게 배우고 편하게 쓸 수 있다."],"title":"문단의 중심 내용 간추리기 — 『국어』 89쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#9','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C19',2,'match','auto','『국어』 88쪽 3번이에요. 친구들이 만든 질문이 어떤 방법으로 만든 질문인지 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C19","difficulty":2,"kind":"match","stem":"『국어』 88쪽 3번이에요. 친구들이 만든 질문이 어떤 방법으로 만든 질문인지 이으세요.","pairs":[{"l":"‘과학성’은 무슨 뜻일까?","r":"낱말의 뜻을 짐작하는 질문"},{"l":"휴대 전화 자판에서 ㆍ를 본 적이 있는데, ㆍ는 어떤 글자일까?","r":"자신의 경험과 관련지어 만든 질문"},{"l":"‘ㅖ’처럼 복잡한 모음자도 기본 글자를 합친 것일까?","r":"글의 내용과 관련해 더 궁금한 점을 묻는 질문"}],"mis":"K4-2-u2-X54","explanation":["낱말 하나의 뜻을 묻는 것은 낱말 뜻을 짐작하는 질문이에요.","「본 적이 있는데」처럼 내가 겪은 일에서 나온 것은 경험과 관련지은 질문이에요.","글에 나온 내용에서 더 나아가 묻는 것은 더 궁금한 점을 묻는 질문이에요."],"asset":{"type":"passage","lines":["㉠ 낱말의 뜻을 짐작하는 질문 — ‘확장하다’는 무슨 뜻일까?","㉡ 자신의 경험과 관련지어 질문하기 —","처음 한글을 배울 때 ㄱ, ㅋ, ㄲ을 공부했는데 이런 글자가 또 있을까?","㉢ 글의 내용과 관련해 더 궁금한 점을 질문하기 —","왜 하늘, 땅, 사람을 중요하게 생각했을까?"],"title":"질문을 만드는 방법 — 『국어』 88쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_basic#10','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C18',3,'mc','auto','한글의 특성을 이야기한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X17','K4-2-u2-X23']::text[],false,'{"seq":10,"concept":"K4-2-u2-C18","difficulty":3,"kind":"mc","stem":"한글의 특성을 이야기한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"한글은 글자를 만든 방법이 알려져 있고 소리와 글자가 규칙적으로 이어져 배우기 쉬워.","correct":true},{"t":"한글이 최고니까 다른 나라 글자는 배울 필요가 없어.","mis":"K4-2-u2-X16"},{"t":"글자는 다 비슷하니 한글이라고 특별할 것은 없어.","mis":"K4-2-u2-X17"},{"t":"한글로는 세상의 모든 언어를 소리 나는 대로 다 쓸 수 있어.","mis":"K4-2-u2-X23"}],"explanation":["한글의 좋은 점은 다른 글자와 견주어서가 아니라 한글 자체의 짜임에 있어요.","다른 나라 글자도 저마다 자기 말을 적어 왔어요.","한글로 모든 언어를 다 적을 수 있는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#1','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C19',2,'ox','auto','한글은 과학적인 문자이니 지구상의 모든 언어를 발음하는 대로 다 쓸 수 있어요.',ARRAY['K4-2-u2-X23']::text[],false,'{"seq":1,"concept":"K4-2-u2-C19","difficulty":2,"kind":"ox","stem":"한글은 과학적인 문자이니 지구상의 모든 언어를 발음하는 대로 다 쓸 수 있어요.","answer":"X","reason_options":[{"t":"한글은 다른 언어를 적는 데 유리한 점은 있지만 모든 언어를 다 적을 수는 없어요.","correct":true},{"t":"과학적인 문자이니 어떤 언어의 소리든 똑같이 적을 수 있어요.","mis":"K4-2-u2-X23"}],"mis":"K4-2-u2-X23","explanation":["한글은 만든 원리를 바꾸고 넓혀 다른 언어를 적는 데 유리한 점이 있어요.","하지만 모든 언어의 소리를 다 적을 수 있는 것은 아니에요.","한글의 특성은 글에 나온 사실로 설명하고 부풀리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#2','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C12',2,'sa','auto','자음자 ‘ㄱ’은 혀뿌리가 무엇을 막는 모양을 본떴나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u2-C12","difficulty":2,"kind":"sa","stem":"자음자 ‘ㄱ’은 혀뿌리가 무엇을 막는 모양을 본떴나요? 한 낱말로 쓰세요.","answer":["목구멍"],"explanation":["ㄱ을 소리 내면 혀뿌리가 올라가요.","혀뿌리가 목구멍을 막는 모양을 본떴어요.","ㅇ은 목구멍 자체의 모양을 본떴어요."],"mis":"K4-2-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#3','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C13',3,'mc','auto','ㄴ에 획을 하나 더하면 ㄷ이 되고, 또 하나 더하면 어떤 글자가 되나요?',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":3,"concept":"K4-2-u2-C13","difficulty":3,"kind":"mc","stem":"ㄴ에 획을 하나 더하면 ㄷ이 되고, 또 하나 더하면 어떤 글자가 되나요?","options":[{"t":"ㅌ","correct":true},{"t":"ㄹ","mis":"K4-2-u2-X10"},{"t":"ㅁ","mis":"K4-2-u2-X10"},{"t":"ㅋ","mis":"K4-2-u2-X10"}],"explanation":["자음자는 기본 글자 ㄱ, ㄴ, ㅁ, ㅅ, ㅇ에 획을 더해 만들었어요.","ㄴ → ㄷ → ㅌ으로 획이 늘수록 소리가 더 강해져요.","ㄹ은 ㄷ과 모양이 닮았지만 ㄷ에 획을 더한 글자가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#4','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C16',3,'mc','auto','다섯째 문단에서 영어의 K·G와 한글의 ㄱ·ㅋ·ㄲ을 견준 까닭은 무엇인가요?',ARRAY['K4-2-u2-X10','K4-2-u2-X12']::text[],false,'{"seq":4,"concept":"K4-2-u2-C16","difficulty":3,"kind":"mc","stem":"다섯째 문단에서 영어의 K·G와 한글의 ㄱ·ㅋ·ㄲ을 견준 까닭은 무엇인가요?","options":[{"t":"한글은 비슷한 소리를 비슷한 모양으로 나타낸다는 것을 보여 주려고","correct":true},{"t":"한글은 획이 많을수록 소리가 약해진다는 것을 보여 주려고","mis":"K4-2-u2-X10"},{"t":"한글은 글자 수가 영어보다 훨씬 많다는 것을 보여 주려고","mis":"K4-2-u2-X12"}],"explanation":["K와 G는 소리가 비슷한데 모양은 아주 달라요.","ㄱ, ㅋ, ㄲ은 소리도 비슷하고 모양도 비슷해요.","소리와 글자가 규칙적으로 연결되는 한글의 특성이에요."],"asset":{"type":"passage","lines":["(간추림) 셋째, 소리와 글자가 규칙적으로 연결된다.","(간추림) 한글은 하나의 글자로 하나의 우리말 소리를 나타낸다.","(간추림) 영어 알파벳의 A는 여러 낱말에서 다양하게 소리가 나지만","한글의 ‘ㅏ’는 어떤 낱말에 쓰여도 같은 소리를 냅니다.","(간추림) 영어의 K와 G는 소리가 비슷한데 모양은 아주 다르다.","(간추림) 한글은 ㄱ, ㅋ, ㄲ처럼 비슷한 소리를 내는 글자가 모양도 비슷하다."],"title":"「한글이 과학적인 문자인 까닭」 5문단 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#5','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C19',3,'error','auto','친구들이 「한글이 과학적인 문자인 까닭」의 문단마다 중심 내용을 간추렸어요. 잘못 간추린 친구는 누구인가요?',ARRAY['K4-2-u2-X55']::text[],false,'{"seq":5,"concept":"K4-2-u2-C19","difficulty":3,"kind":"error","stem":"친구들이 「한글이 과학적인 문자인 까닭」의 문단마다 중심 내용을 간추렸어요. 잘못 간추린 친구는 누구인가요?","options":[{"t":"시우: 셋째 문단 — ‘ㅁ’은 입의 모양을 본떴다.","correct":true,"mis_target":"K4-2-u2-X55"},{"t":"다은: 다섯째 문단 — 소리와 글자가 규칙적으로 연결된다.","mis":"K4-2-u2-X55"},{"t":"유찬: 여섯째 문단 — 한글은 과학적인 문자라서 쉽게 배우고 편하게 쓸 수 있다.","mis":"K4-2-u2-X55"}],"explanation":["셋째 문단은 ㄱ, ㄴ, ㅁ, ㅅ, ㅇ과 ㆍ, ㅡ, ㅣ를 모두 다루어요.","‘ㅁ’은 그 가운데 하나의 예일 뿐이에요.","「발음 기관과 하늘, 땅, 사람의 모양을 바탕으로 기본 글자를 만들었다」가 중심 내용이에요."],"asset":{"type":"passage","lines":["(간추림) 첫째, 기본 글자를 만들려고 모양을 본뜬 대상이 정확하게 알려져 있다.","(간추림) 자음자 기본 글자 ㄱ, ㄴ, ㅁ, ㅅ, ㅇ은 발음 기관의 모양을 본떴다.","‘ㄱ’은 혀뿌리가 목구멍을 막는 모양, ‘ㄴ’은 혀가 윗잇몸에 닿는 모양,","(간추림) ㅁ은 입, ㅅ은 이, ㅇ은 목구멍의 모양을 본떴다.","(간추림) 모음자 기본 글자 ㆍ, ㅡ, ㅣ는 우리 민족이 중요하게 생각한 세 가지를 본떴다.","‘ㆍ’는 하늘, ‘ㅡ’는 땅, ‘ㅣ’는 하늘과 땅을 연결하는 사람의 모양을 나타낸 것입니다."],"title":"「한글이 과학적인 문자인 까닭」 3문단 — 『국어』 86~87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#6','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C19',3,'mc','auto','「한글을 처음 배울 때 ‘ㄷ’과 ‘ㅌ’의 모양이 비슷해서 기억하기 쉬웠는데, 이런 글자가 또 있을까?」는 어떤 방법으로 만든 질문인가요?',ARRAY['K4-2-u2-X54']::text[],false,'{"seq":6,"concept":"K4-2-u2-C19","difficulty":3,"kind":"mc","stem":"「한글을 처음 배울 때 ‘ㄷ’과 ‘ㅌ’의 모양이 비슷해서 기억하기 쉬웠는데, 이런 글자가 또 있을까?」는 어떤 방법으로 만든 질문인가요?","options":[{"t":"자신의 경험과 관련지어 만든 질문","correct":true},{"t":"낱말의 뜻을 짐작하는 질문","mis":"K4-2-u2-X54"},{"t":"글의 내용과 관련해 더 궁금한 점을 묻는 질문","mis":"K4-2-u2-X54"}],"explanation":["「처음 배울 때 … 기억하기 쉬웠는데」는 내가 겪은 일이에요.","내 경험에서 출발해 글과 이어 묻고 있어요.","답을 찾으며 읽으면 ‘ㄱ’과 ‘ㅋ’도 모양이 비슷하다는 것을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#7','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C11',3,'mc','auto','첫째 문단에서 세종 대왕이 훈민정음을 만든 까닭으로 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u2-X08']::text[],false,'{"seq":7,"concept":"K4-2-u2-C11","difficulty":3,"kind":"mc","stem":"첫째 문단에서 세종 대왕이 훈민정음을 만든 까닭으로 알 수 있는 것은 무엇인가요?","options":[{"t":"백성이 자신의 뜻을 글로 나타내지 못하는 상황을 안타까워해서","correct":true},{"t":"임금의 힘을 다른 나라에 뽐내려고","mis":"K4-2-u2-X08"},{"t":"한자를 아무도 쓰지 못하게 없애려고","mis":"K4-2-u2-X08"},{"t":"양반만 쓰는 새 글자를 따로 만들려고","mis":"K4-2-u2-X08"}],"explanation":["한자는 수가 많아 대부분의 백성이 글자를 읽거나 쓸 수 없었어요.","글을 몰라 억울한 일을 당하는 백성도 많았어요.","그래서 누구나 쉽게 익혀 쓰는 글자를 만들었어요."],"asset":{"type":"passage","lines":["옛날 우리 조상은 중국의 문자인 한자를 빌려 우리말을 썼습니다.","뜻글자인 한자는 그 수가 많아 배우는 데 많은 시간과 노력이 필요했습니다.","(간추림) 대부분의 백성은 글자를 읽거나 쓸 수 없어 억울한 일을 당하기도 했다.","(간추림) 세종 대왕은 백성이 자신의 뜻을 글로 나타내지 못함을 안타까워했다.","(간추림) 세종 대왕은 적은 수의 문자로 누구나 우리말을 읽고 쓰는 훈민정음을 만들었다.","훈민정음은 백성을 가르치는 바른 소리라는 뜻으로,","(간추림) 오늘날 우리가 쓰는 한글의 바탕이 되었다."],"title":"「한글이 과학적인 문자인 까닭」 1·2문단 — 『국어』 86쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#8','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C19',4,'essay','teacher','『국어』 89쪽 4번처럼 셋째·넷째·다섯째 문단의 중심 내용을 간추리고, 그것을 바탕으로 한글이 과학적인 문자인 까닭을 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C19","difficulty":4,"kind":"essay","stem":"『국어』 89쪽 4번처럼 셋째·넷째·다섯째 문단의 중심 내용을 간추리고, 그것을 바탕으로 한글이 과학적인 문자인 까닭을 설명하세요.","answer_guide":{"answer":"예: 셋째 — 발음 기관과 하늘, 땅, 사람의 모양을 바탕으로 기본 글자를 만들었다. 넷째 — 기본 글자를 확장해 다른 글자를 만들었다. 다섯째 — 소리와 글자가 규칙적으로 연결된다. 그러므로 한글은 글자를 만든 방법이 정확하게 알려져 있고 소리와 글자가 규칙적으로 연결되기 때문에 과학적인 문자이다.","scoring_points":["세 문단의 중심 내용을 바르게 간추렸는가","예가 아닌 문단 전체를 묶는 말로 썼는가","간추린 내용으로 과학적인 까닭을 설명했는가"]},"explanation":["문단마다 첫째, 둘째, 셋째로 시작하는 문장을 찾아요.","자잘한 예는 빼고 묶는 말만 남겨요.","세 가지를 이어 한 문장으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#9','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C19',4,'essay','teacher','『국어』 88쪽 질문을 만드는 세 방법 가운데 두 가지를 골라 「한글이 과학적인 문자인 까닭」에 대한 질문을 하나씩 만들고, 각 질문의 답도 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C19","difficulty":4,"kind":"essay","stem":"『국어』 88쪽 질문을 만드는 세 방법 가운데 두 가지를 골라 「한글이 과학적인 문자인 까닭」에 대한 질문을 하나씩 만들고, 각 질문의 답도 쓰세요.","answer_guide":{"answer":"예: 낱말의 뜻을 짐작하는 질문 — ‘확장하다’는 무슨 뜻일까? 답: 무언가를 늘리고 넓힌다는 뜻 같다. 더 궁금한 점을 묻는 질문 — 왜 하늘, 땅, 사람을 중요하게 생각했을까? 답: 우리 민족은 하늘, 땅, 사람이 세상을 이루는 중요한 것이라고 생각했던 것 같다.","scoring_points":["두 가지 방법을 골라 방법에 맞는 질문을 만들었는가","질문이 글의 내용과 이어지는가","글이나 짐작을 바탕으로 답을 썼는가"]},"explanation":["낱말 뜻, 내 경험, 더 궁금한 점 — 세 방법이 있어요.","방법에 맞게 질문이 시작되는지 살펴요.","짝과 서로 만든 질문을 묻고 답하면 더 좋아요."],"asset":{"type":"passage","lines":["㉠ 낱말의 뜻을 짐작하는 질문 — ‘확장하다’는 무슨 뜻일까?","㉡ 자신의 경험과 관련지어 질문하기 —","처음 한글을 배울 때 ㄱ, ㅋ, ㄲ을 공부했는데 이런 글자가 또 있을까?","㉢ 글의 내용과 관련해 더 궁금한 점을 질문하기 —","왜 하늘, 땅, 사람을 중요하게 생각했을까?"],"title":"질문을 만드는 방법 — 『국어』 88쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L03_challenge#10','kor',4,2,'u2','L03','tb_g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C15',4,'mc','auto','「‘ㅖ’처럼 모양이 더 복잡한 모음자는 어떻게 만들어질까?」라는 질문에 글의 내용을 바탕으로 짐작한 답으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X10','K4-2-u2-X12','K4-2-u2-X08']::text[],false,'{"seq":10,"concept":"K4-2-u2-C15","difficulty":4,"kind":"mc","stem":"「‘ㅖ’처럼 모양이 더 복잡한 모음자는 어떻게 만들어질까?」라는 질문에 글의 내용을 바탕으로 짐작한 답으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"ㅕ에 ㅣ를 다시 합쳐 쓴 것이라고 짐작할 수 있다","correct":true},{"t":"ㅖ는 획을 더해 소리를 강하게 만든 자음자이다","mis":"K4-2-u2-X10"},{"t":"ㅖ는 기본 글자와 상관없이 아무렇게나 만든 글자이다","mis":"K4-2-u2-X12"},{"t":"ㅖ는 영어 글자를 빌려 만든 글자이다","mis":"K4-2-u2-X08"}],"explanation":["모음자는 기본 글자 ㆍ, ㅡ, ㅣ를 합쳐 만들었어요.","ㅕ는 ㅓ에 ㆍ를 한 번 더 합친 글자예요.","그러니 ㅖ도 ㅕ에 ㅣ를 합친 것이라고 짐작할 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 둘째, 기본 글자를 확장해 다른 글자를 만들었다.","(간추림) 자음자는 ㄱ, ㄴ, ㅁ, ㅅ, ㅇ에 획을 더해 만들었다.","소리가 강하게 날수록 획을 더해 나타냈습니다.","(간추림) 모음자는 ㆍ, ㅡ, ㅣ를 합쳐 만들었다.","(간추림) 기본 글자를 한 번씩 합치면 ㅗ, ㅏ, ㅜ, ㅓ가 되고,","(간추림) 여기에 ㆍ를 한 번 더 합치면 ㅛ, ㅑ, ㅠ, ㅕ가 된다."],"title":"「한글이 과학적인 문자인 까닭」 4문단 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#1','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C20',2,'mc','auto','세종 대왕, 주시경, 공병우가 한 일을 살펴보았어요. 세 사람의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X18','K4-2-u2-X52']::text[],false,'{"seq":1,"concept":"K4-2-u2-C20","difficulty":2,"kind":"mc","stem":"세종 대왕, 주시경, 공병우가 한 일을 살펴보았어요. 세 사람의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"방법은 달라도 오늘날 우리가 한글을 쓰는 데 이바지했다","correct":true},{"t":"모두 외국에서 온 사람이다","mis":"K4-2-u2-X18"},{"t":"모두 같은 때에 살았다","mis":"K4-2-u2-X18"},{"t":"모두 국어사전 원고를 썼다","mis":"K4-2-u2-X52"}],"explanation":["세종 대왕은 훈민정음을 만들었어요.","주시경은 우리말과 한글을 연구했고, 공병우는 한글 타자기를 개발했어요.","만들기·연구·정보화로 방법은 달라도 모두 한글에 이바지했어요."],"asset":{"type":"passage","lines":["세종 대왕(1397~1450) — 우리나라 고유의 문자인 훈민정음을 만듦.","주시경(1876~1914) — 우리말과 한글을 연구하고","제자들과 함께 최초의 국어사전 원고를 씀.","공병우(1906~1995) — 한글을 빠르고 정확하게 입력하려고 한글 타자기를 개발함."],"title":"한글과 관련된 인물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#2','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C23',1,'sa','auto','헐버트가 조선에 와서 교사로 일한 학교의 이름은 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"K4-2-u2-C23","difficulty":1,"kind":"sa","stem":"헐버트가 조선에 와서 교사로 일한 학교의 이름은 무엇인가요?","answer":["육영공원"],"explanation":["나라에서 새롭게 서양식 교육을 하려고 지은 학교예요.","헐버트는 「육영공원」에서 학생들을 가르쳤어요.","육영공원은 조선 후기에 세운 최초의 현대식 학교예요."],"asset":{"type":"passage","lines":["(간추림) 1886년, 미국인 호머 헐버트가 조선의 학생들을 가르치려고 왔다.","(간추림) 나라에서 세운 서양식 학교 ‘육영공원’의 교사가 되었다.","(간추림) 헐버트는 선생님을 구해 조선의 말과 글을 밤낮으로 익혔다.","(간추림) 두 달여 만에 조선어로 말하고, 다섯 달 만에 영어와 함께 가르쳤다.","“헐버트 씨, 우리 글자를 배운 지 이제 겨우 나흘째인데 벌써 글자를 다 익혔군요!”","“이렇게 배우기 쉬운 글자는 처음입니다.","글자 하나에 소리 하나가 연결되고 글자들을 합치면 새로운 글자가 되니까 배우기가 쉬워요.”"],"title":"「한글을 사랑한 외국인, 헐버트」 앞부분 — 『국어』 90~91쪽"},"mis":"K4-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#3','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C23',1,'mc','auto','헐버트를 가르치던 선생님이 깜짝 놀란 까닭은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":3,"concept":"K4-2-u2-C23","difficulty":1,"kind":"mc","stem":"헐버트를 가르치던 선생님이 깜짝 놀란 까닭은 무엇인가요?","options":[{"t":"글자를 배운 지 나흘째인데 벌써 글자를 다 익혀서","correct":true},{"t":"조선어를 한 마디도 하지 못해서","mis":"K4-2-u2-X18"},{"t":"한자를 먼저 모두 외워 와서","mis":"K4-2-u2-X18"},{"t":"영어로만 말하겠다고 해서","mis":"K4-2-u2-X18"}],"explanation":["선생님은 「배운 지 이제 겨우 나흘째인데」라고 했어요.","헐버트는 한글을 매우 빠르게 익혔어요.","그만큼 한글이 배우기 쉬운 글자라는 뜻이에요."],"asset":{"type":"passage","lines":["(간추림) 1886년, 미국인 호머 헐버트가 조선의 학생들을 가르치려고 왔다.","(간추림) 나라에서 세운 서양식 학교 ‘육영공원’의 교사가 되었다.","(간추림) 헐버트는 선생님을 구해 조선의 말과 글을 밤낮으로 익혔다.","(간추림) 두 달여 만에 조선어로 말하고, 다섯 달 만에 영어와 함께 가르쳤다.","“헐버트 씨, 우리 글자를 배운 지 이제 겨우 나흘째인데 벌써 글자를 다 익혔군요!”","“이렇게 배우기 쉬운 글자는 처음입니다.","글자 하나에 소리 하나가 연결되고 글자들을 합치면 새로운 글자가 되니까 배우기가 쉬워요.”"],"title":"「한글을 사랑한 외국인, 헐버트」 앞부분 — 『국어』 90~91쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#4','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C23',1,'mc','auto','『국어』 93쪽 내용 알기 (1)이에요. 헐버트가 쉽고 빠르게 한글을 익힐 수 있었던 까닭은 무엇인가요?',ARRAY['K4-2-u2-X12','K4-2-u2-X18']::text[],false,'{"seq":4,"concept":"K4-2-u2-C23","difficulty":1,"kind":"mc","stem":"『국어』 93쪽 내용 알기 (1)이에요. 헐버트가 쉽고 빠르게 한글을 익힐 수 있었던 까닭은 무엇인가요?","options":[{"t":"글자 하나에 소리 하나가 연결되고 글자들을 합치면 새로운 글자가 되어서","correct":true},{"t":"한글은 글자 수가 아주 많아서","mis":"K4-2-u2-X12"},{"t":"미국에서 이미 한글을 배워 와서","mis":"K4-2-u2-X18"},{"t":"밤낮으로 한자부터 공부해서","mis":"K4-2-u2-X18"}],"explanation":["헐버트가 직접 까닭을 말했어요.","「글자 하나에 소리 하나가 연결되고 글자들을 합치면 새로운 글자가 되니까」라고 했어요.","3~4차시에 배운 한글의 특성과 이어져요."],"asset":{"type":"passage","lines":["(간추림) 1886년, 미국인 호머 헐버트가 조선의 학생들을 가르치려고 왔다.","(간추림) 나라에서 세운 서양식 학교 ‘육영공원’의 교사가 되었다.","(간추림) 헐버트는 선생님을 구해 조선의 말과 글을 밤낮으로 익혔다.","(간추림) 두 달여 만에 조선어로 말하고, 다섯 달 만에 영어와 함께 가르쳤다.","“헐버트 씨, 우리 글자를 배운 지 이제 겨우 나흘째인데 벌써 글자를 다 익혔군요!”","“이렇게 배우기 쉬운 글자는 처음입니다.","글자 하나에 소리 하나가 연결되고 글자들을 합치면 새로운 글자가 되니까 배우기가 쉬워요.”"],"title":"「한글을 사랑한 외국인, 헐버트」 앞부분 — 『국어』 90~91쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#5','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C22',1,'blank','auto','『국어』 94쪽 낱말 알기예요. 「본래부터 특별히 가지고 있는 것」이라는 뜻의 낱말을 넣으세요. 「언문은 이 나라 (     )의 글자로 누구든 가리지 않고 읽을 수 있지요.」',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":5,"concept":"K4-2-u2-C22","difficulty":1,"kind":"blank","stem":"『국어』 94쪽 낱말 알기예요. 「본래부터 특별히 가지고 있는 것」이라는 뜻의 낱말을 넣으세요. 「언문은 이 나라 (     )의 글자로 누구든 가리지 않고 읽을 수 있지요.」","options":[{"t":"고유","correct":true},{"t":"공식","mis":"K4-2-u2-X19"},{"t":"제도","mis":"K4-2-u2-X19"}],"explanation":["보기는 고유, 공식, 제도예요.","「본래부터 특별히 가지고 있는 것」은 고유예요.","언문(한글)은 우리나라가 본래 가진 글자라는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#6','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C22',2,'blank','auto','「국가나 사회에서 인정한 공적인 방식」이라는 뜻의 낱말을 넣으세요. 「나라의 (     ) 문서가 대부분 한자로 쓰여 있었습니다.」',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":6,"concept":"K4-2-u2-C22","difficulty":2,"kind":"blank","stem":"「국가나 사회에서 인정한 공적인 방식」이라는 뜻의 낱말을 넣으세요. 「나라의 (     ) 문서가 대부분 한자로 쓰여 있었습니다.」","options":[{"t":"공식","correct":true},{"t":"고유","mis":"K4-2-u2-X19"},{"t":"제도","mis":"K4-2-u2-X19"}],"explanation":["나라에서 쓰는 문서는 나라가 인정한 방식의 문서예요.","「국가나 사회에서 인정한 공적인 방식」은 공식이에요.","그때는 공식 문서와 책이 대부분 한자로 쓰였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#7','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C23',2,'mc','auto','『국어』 93쪽 내용 알기 (2)예요. 사람들이 『사민필지』를 왜 언문으로 썼는지 묻자 헐버트는 어떻게 답했나요?',ARRAY['K4-2-u2-X18','K4-2-u2-X20']::text[],false,'{"seq":7,"concept":"K4-2-u2-C23","difficulty":2,"kind":"mc","stem":"『국어』 93쪽 내용 알기 (2)예요. 사람들이 『사민필지』를 왜 언문으로 썼는지 묻자 헐버트는 어떻게 답했나요?","options":[{"t":"언문으로 쓰면 선비와 백성, 남자와 여자 누구든 가리지 않고 많은 사람이 읽을 수 있다고 했다","correct":true},{"t":"언문이 한문보다 글씨를 빨리 쓸 수 있다고 했다","mis":"K4-2-u2-X18"},{"t":"양반들만 읽게 하려고 언문으로 썼다고 했다","mis":"K4-2-u2-X18"},{"t":"한문을 몰라서 언문밖에 쓸 줄 모른다고 했다","mis":"K4-2-u2-X20"}],"explanation":["「한문으로 쓰면 한문을 모르는 많은 사람이 이 책을 읽을 수가 없습니다.」라고 했어요.","언문은 신분이나 남녀를 가리지 않고 누구나 읽을 수 있어요.","헐버트는 누구나 세계를 알아야 한다고 생각했어요."],"asset":{"type":"passage","lines":["(간추림) 그때는 한글보다 한자를 주로 써서 공식 문서와 책은 대부분 한자였다.","(간추림) 헐버트는 사람들이 한글의 소중함을 잘 모른다는 생각에 답답했다.","(간추림) 그래서 세계의 지리와 문화를 소개하는 『사민필지』를 한글로 썼다.","“다른 나라에 대해 알 수 있는 정말 유익한 책이오.","그런데 이렇게 좋은 책을 왜 한문이 아닌 언문으로 썼소?”","“한문으로 쓰면 한문을 모르는 많은 사람이 이 책을 읽을 수가 없습니다.","(간추림) 언문은 이 나라 고유의 글자로 신분과 남녀를 가리지 않고 누구나 읽지요.”","※ 언문: 예전에 ‘한글’을 이르던 말."],"title":"「한글을 사랑한 외국인, 헐버트」 가운데 — 『국어』 91~92쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#8','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C24',2,'mc','auto','『국어』 93쪽 내용 알기 (3)이에요. 헐버트를 ‘한글을 사랑한 벗’이라고 표현한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X20']::text[],false,'{"seq":8,"concept":"K4-2-u2-C24","difficulty":2,"kind":"mc","stem":"『국어』 93쪽 내용 알기 (3)이에요. 헐버트를 ‘한글을 사랑한 벗’이라고 표현한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"한글을 알리고 가꾸려는 노력을 멈추지 않았기 때문","correct":true},{"t":"한국어를 가장 빨리 배운 외국인이기 때문","mis":"K4-2-u2-X20"},{"t":"자기 이름을 알리려고 신문에 글을 썼기 때문","mis":"K4-2-u2-X20"},{"t":"조선 사람들과 친구로 지냈기 때문","mis":"K4-2-u2-X20"}],"explanation":["헐버트는 『사민필지』를 한글로 썼어요.","가르치는 일을 그만둔 뒤에도 한글을 세계에 알리는 글을 계속 썼어요.","이런 행동에서 한글을 소중히 여긴 마음을 알 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 헐버트는 신분이나 남녀를 가리지 않고 누구나 세계를 알아야 한다고 생각했다.","(간추림) 『사민필지』는 전국의 학교에서 세계 지리를 배우는 교재로 쓰였다.","(간추림) 미국 신문에 한글을 소개해 한글의 과학성을 처음으로 세계에 알렸다.","(간추림) 한글과 영어 자모를 비교하는 글을 쓰고 영문자 신문 만들기에도 참여했다.","푸른 눈의 헐버트는 외국인이면서도 누구보다 한글을 사랑한 벗이었습니다."],"title":"「한글을 사랑한 외국인, 헐버트」 뒷부분 — 『국어』 92~93쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#9','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C23',2,'blank','auto','『국어』 94쪽 글과 연결하기예요. 헐버트가 한 일을 차례대로 간추렸어요. 빈칸 ②에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":9,"concept":"K4-2-u2-C23","difficulty":2,"kind":"blank","stem":"『국어』 94쪽 글과 연결하기예요. 헐버트가 한 일을 차례대로 간추렸어요. 빈칸 ②에 알맞은 것은 무엇인가요?","options":[{"t":"조선의 말과 글을 밤낮으로 배움.","correct":true},{"t":"『사민필지』를 한글로 씀.","mis":"K4-2-u2-X18"},{"t":"미국 신문에 한글을 소개함.","mis":"K4-2-u2-X18"},{"t":"육영공원을 세움.","mis":"K4-2-u2-X18"}],"explanation":["① 육영공원 교사가 되려고 조선에 왔어요.","② 그다음 선생님을 구해 조선의 말과 글을 밤낮으로 익혔어요.","『사민필지』와 신문 기사는 그 뒤의 일이에요."],"asset":{"type":"passage","lines":["① 육영공원의 교사가 되기 위해 조선으로 옴.","② (                    )","③ 한글을 빠르게 익혔으나 한자를 주로 쓰는 현실에 안타까움을 느낌.","④ 누구나 세계를 알아야 한다고 생각해 『사민필지』를 한글로 씀.","⑤ 한글과 영어 자모를 비교하고 한글의 과학성을 세계에 알리는 글을 씀."],"title":"「한글을 사랑한 외국인, 헐버트」 간추리기 — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_basic#10','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C27',3,'mc','auto','헐버트와 주시경의 이야기를 읽고 친구들이 말했어요. 한글 사랑을 바르게 이해한 친구의 말은 무엇인가요?',ARRAY['K4-2-u2-X21','K4-2-u2-X22']::text[],false,'{"seq":10,"concept":"K4-2-u2-C27","difficulty":3,"kind":"mc","stem":"헐버트와 주시경의 이야기를 읽고 친구들이 말했어요. 한글 사랑을 바르게 이해한 친구의 말은 무엇인가요?","options":[{"t":"나도 모르는 낱말은 사전을 찾아보고 한글을 바르게 쓰는 것부터 해 볼래.","correct":true},{"t":"한글 사랑은 헐버트처럼 대단한 사람만 할 수 있는 일이야.","mis":"K4-2-u2-X21"},{"t":"외국어를 쓰는 친구를 보면 크게 꾸짖어야 해.","mis":"K4-2-u2-X22"}],"explanation":["한글을 사랑하고 지켜 나가는 일은 지금의 우리에게도 주어진 몫이에요.","내 생활에서 작은 것부터 시작할 수 있어요.","남을 꾸짖거나 무엇을 금지하는 것이 한글 사랑은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#1','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C22',2,'blank','auto','「사회에서 지켜야 하는 도덕이나 법의 체계」라는 뜻의 낱말을 넣으세요. 「『사민필지』는 각 나라의 (     ), 문화 등을 설명한 책입니다.」',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":1,"concept":"K4-2-u2-C22","difficulty":2,"kind":"blank","stem":"「사회에서 지켜야 하는 도덕이나 법의 체계」라는 뜻의 낱말을 넣으세요. 「『사민필지』는 각 나라의 (     ), 문화 등을 설명한 책입니다.」","options":[{"t":"제도","correct":true},{"t":"고유","mis":"K4-2-u2-X19"},{"t":"공식","mis":"K4-2-u2-X19"}],"explanation":["사회에서 지켜야 하는 법과 규칙의 짜임을 말해요.","「도덕이나 법의 체계」는 제도예요.","『사민필지』에는 각 나라의 땅 모양, 특징, 제도, 문화가 담겨 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#2','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C20',2,'mc','auto','한글을 꽃피운 사람 가운데 박두성이 1926년에 만든 ‘훈맹정음’은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":2,"concept":"K4-2-u2-C20","difficulty":2,"kind":"mc","stem":"한글을 꽃피운 사람 가운데 박두성이 1926년에 만든 ‘훈맹정음’은 무엇인가요?","options":[{"t":"시각 장애인이 읽기 쉬운 한글 점자","correct":true},{"t":"한글을 빠르게 치는 세벌식 타자기","mis":"K4-2-u2-X18"},{"t":"명조체 같은 한글 글꼴","mis":"K4-2-u2-X18"},{"t":"최초의 국어사전 원고","mis":"K4-2-u2-X18"}],"explanation":["박두성은 시각 장애인 학생들이 일본어 점자책으로 공부하는 것을 안타까워했어요.","그래서 한글로 된 점자 ‘훈맹정음’을 만들었어요.","세종 대왕이 백성을 위해 훈민정음을 만든 것과 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#3','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C23',3,'mc','auto','헐버트가 한 일을 시간의 흐름에 따라 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":3,"concept":"K4-2-u2-C23","difficulty":3,"kind":"mc","stem":"헐버트가 한 일을 시간의 흐름에 따라 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"육영공원 교사로 옴 → 조선의 말과 글을 배움 → 『사민필지』를 한글로 씀 → 한글을 세계에 알리는 글을 씀","correct":true},{"t":"『사민필지』를 한글로 씀 → 육영공원 교사로 옴 → 조선의 말과 글을 배움 → 한글을 세계에 알리는 글을 씀","mis":"K4-2-u2-X18"},{"t":"조선의 말과 글을 배움 → 한글을 세계에 알리는 글을 씀 → 육영공원 교사로 옴 → 『사민필지』를 한글로 씀","mis":"K4-2-u2-X18"}],"explanation":["먼저 1886년에 육영공원 교사가 되려고 조선에 왔어요.","말과 글을 익힌 뒤 한글로 『사민필지』를 썼어요.","그 뒤에도 한글을 세계에 알리는 글을 계속 썼어요."],"asset":{"type":"passage","lines":["① 육영공원의 교사가 되기 위해 조선으로 옴.","② (                    )","③ 한글을 빠르게 익혔으나 한자를 주로 쓰는 현실에 안타까움을 느낌.","④ 누구나 세계를 알아야 한다고 생각해 『사민필지』를 한글로 씀.","⑤ 한글과 영어 자모를 비교하고 한글의 과학성을 세계에 알리는 글을 씀."],"title":"「한글을 사랑한 외국인, 헐버트」 간추리기 — 『국어』 94쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#4','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C24',3,'mc','auto','헐버트는 한자는 양반들만 아는 글자라 널리 퍼질 수 없다며, 언문이 제대로 빛을 보지 못하는 것을 안타까워했어요. 이 생각에서 짐작할 수 있는 헐버트의 마음은 무엇인가요?',ARRAY['K4-2-u2-X20']::text[],false,'{"seq":4,"concept":"K4-2-u2-C24","difficulty":3,"kind":"mc","stem":"헐버트는 한자는 양반들만 아는 글자라 널리 퍼질 수 없다며, 언문이 제대로 빛을 보지 못하는 것을 안타까워했어요. 이 생각에서 짐작할 수 있는 헐버트의 마음은 무엇인가요?","options":[{"t":"누구나 쉽게 읽고 쓰는 한글이 제대로 쓰이지 못하는 것이 안타까운 마음","correct":true},{"t":"한자를 배우기가 귀찮아 피하고 싶은 마음","mis":"K4-2-u2-X20"},{"t":"자기 이름을 세상에 널리 알리고 싶은 마음","mis":"K4-2-u2-X20"},{"t":"양반이 되어 한자를 쓰고 싶은 마음","mis":"K4-2-u2-X20"}],"explanation":["헐버트는 사람들이 한글의 소중함을 잘 모른다는 생각에 답답했어요.","언문을 처음부터 썼다면 누구나 글을 읽고 쓸 수 있었을 거라고 생각했어요.","이 마음이 『사민필지』를 한글로 쓰는 행동으로 이어졌어요."],"asset":{"type":"passage","lines":["(간추림) 그때는 한글보다 한자를 주로 써서 공식 문서와 책은 대부분 한자였다.","(간추림) 헐버트는 사람들이 한글의 소중함을 잘 모른다는 생각에 답답했다.","(간추림) 그래서 세계의 지리와 문화를 소개하는 『사민필지』를 한글로 썼다.","“다른 나라에 대해 알 수 있는 정말 유익한 책이오.","그런데 이렇게 좋은 책을 왜 한문이 아닌 언문으로 썼소?”","“한문으로 쓰면 한문을 모르는 많은 사람이 이 책을 읽을 수가 없습니다.","(간추림) 언문은 이 나라 고유의 글자로 신분과 남녀를 가리지 않고 누구나 읽지요.”","※ 언문: 예전에 ‘한글’을 이르던 말."],"title":"「한글을 사랑한 외국인, 헐버트」 가운데 — 『국어』 91~92쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#5','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C26',3,'mc','auto','『국어』 95쪽 다른 글과 연결하기예요. 헐버트와 주시경의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X52']::text[],false,'{"seq":5,"concept":"K4-2-u2-C26","difficulty":3,"kind":"mc","stem":"『국어』 95쪽 다른 글과 연결하기예요. 헐버트와 주시경의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"방법은 달랐지만 한글을 아끼고 지키려고 자신이 할 수 있는 일을 했다","correct":true},{"t":"두 사람 모두 외국에서 온 사람이다","mis":"K4-2-u2-X52"},{"t":"두 사람 모두 한글 타자기를 만들었다","mis":"K4-2-u2-X52"},{"t":"두 사람의 이야기는 서로 관계가 없다","mis":"K4-2-u2-X52"}],"explanation":["헐버트는 한글로 책을 쓰고 한글을 세계에 알렸어요.","주시경은 우리말과 한글을 연구하고 제자들과 국어사전 원고를 썼어요.","한 일의 겉모습은 달라도 한글을 아끼는 마음은 같아요."],"asset":{"type":"passage","lines":["세종 대왕(1397~1450) — 우리나라 고유의 문자인 훈민정음을 만듦.","주시경(1876~1914) — 우리말과 한글을 연구하고","제자들과 함께 최초의 국어사전 원고를 씀.","공병우(1906~1995) — 한글을 빠르고 정확하게 입력하려고 한글 타자기를 개발함."],"title":"한글과 관련된 인물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#6','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C27',3,'ox','auto','헐버트와 주시경이 살던 때와 달리 지금은 한글을 지키는 일이 다 끝났으니 우리가 할 일은 없어요.',ARRAY['K4-2-u2-X21']::text[],false,'{"seq":6,"concept":"K4-2-u2-C27","difficulty":3,"kind":"ox","stem":"헐버트와 주시경이 살던 때와 달리 지금은 한글을 지키는 일이 다 끝났으니 우리가 할 일은 없어요.","answer":"X","reason_options":[{"t":"한글을 사랑하고 지켜 나가는 것은 지금의 우리에게도 주어진 몫이에요.","correct":true},{"t":"한글 사랑은 옛날 사람들만 하던 일이에요.","mis":"K4-2-u2-X21"}],"mis":"K4-2-u2-X21","explanation":["여러 인물이 한글 사랑을 실천해 왔어요.","지금의 우리도 한글을 바르게 쓰고 아끼며 이어 갈 수 있어요.","받침까지 바르게 쓰기, 모르는 낱말 사전 찾기도 한글 사랑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#7','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C28',3,'mc','auto','『국어』 95쪽 편지 예시에서 「앞으로 저도 선생님처럼 한글에 대해 더 자세히 알려고 노력할 거예요.」 부분이 하는 일은 무엇인가요?',ARRAY['K4-2-u2-X18','K4-2-u2-X51']::text[],false,'{"seq":7,"concept":"K4-2-u2-C28","difficulty":3,"kind":"mc","stem":"『국어』 95쪽 편지 예시에서 「앞으로 저도 선생님처럼 한글에 대해 더 자세히 알려고 노력할 거예요.」 부분이 하는 일은 무엇인가요?","options":[{"t":"앞으로 자신이 실천할 한글 사랑을 다짐한다","correct":true},{"t":"헐버트가 한 일을 시간의 흐름에 따라 간추린다","mis":"K4-2-u2-X18"},{"t":"헐버트를 칭찬하는 말을 되풀이한다","mis":"K4-2-u2-X51"},{"t":"편지를 받는 사람이 누구인지 밝힌다","mis":"K4-2-u2-X51"}],"explanation":["편지는 알게 된 일과 그때 든 생각을 먼저 써요.","이 부분은 앞으로 내가 할 일을 다짐하는 부분이에요.","칭찬 한마디로 끝내지 않고 내 다짐까지 써야 해요."],"asset":{"type":"passage","lines":["헐버트 선생님께","안녕하세요? 저는 ○○초등학교 4학년 연○○입니다.","한글 사랑을 실천한 선생님의 이야기를 보고 깜짝 놀랐어요.","우리글을 이렇게 아끼고 사랑한 외국인이 있었다는 것을 처음 알았기 때문이에요.","앞으로 저도 선생님처럼 한글에 대해 더 자세히 알려고 노력할 거예요.","그래서 한글이 과학적인 문자라는 사실을 다른 사람들에게 알리고 싶어요.","연○○ 올림"],"title":"한글 사랑을 실천한 인물에게 쓴 편지 (예시) — 『국어』 95쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#8','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C28',4,'essay','teacher','한글 사랑을 실천한 인물(헐버트, 주시경, 세종 대왕, 공병우 등) 가운데 한 명에게 편지를 쓰세요. 그 인물이 한 일, 그 일을 알고 든 생각, 앞으로 자신이 실천할 일이 드러나게 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C28","difficulty":4,"kind":"essay","stem":"한글 사랑을 실천한 인물(헐버트, 주시경, 세종 대왕, 공병우 등) 가운데 한 명에게 편지를 쓰세요. 그 인물이 한 일, 그 일을 알고 든 생각, 앞으로 자신이 실천할 일이 드러나게 쓰세요.","answer_guide":{"answer":"예: 주시경 선생님께. 안녕하세요? 저는 4학년 ○○○입니다. 선생님께서 우리말과 한글을 연구하고 제자들과 국어사전 원고를 쓰셨다는 것을 알았어요. 우리말을 지키려고 평생 애쓰신 모습이 정말 대단하다고 생각했어요. 저도 모르는 낱말은 국어사전에서 찾아보고, 친구들에게 쓰는 글에서 받침을 바르게 쓰겠습니다. ○○○ 올림","scoring_points":["인물이 한 일을 바르게 썼는가","그 일을 알고 든 생각이나 느낌을 썼는가","자신이 실천할 한글 사랑을 썼는가"]},"explanation":["편지의 첫인사와 끝인사를 갖추어요.","알게 된 일 → 든 생각 → 나의 다짐 차례로 써요.","쓴 편지는 나만의 한글책에 모아 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#9','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C26',4,'essay','teacher','헐버트와 주시경이 한글 사랑을 실천한 까닭을 짐작해 쓰고, 두 사람의 이야기를 바탕으로 자신이 한글 사랑을 실천할 수 있는 방법을 한 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C26","difficulty":4,"kind":"essay","stem":"헐버트와 주시경이 한글 사랑을 실천한 까닭을 짐작해 쓰고, 두 사람의 이야기를 바탕으로 자신이 한글 사랑을 실천할 수 있는 방법을 한 가지 쓰세요.","answer_guide":{"answer":"예: 두 사람은 한글이 누구나 쉽게 배우고 쓸 수 있는 소중한 글자인데 사람들이 그 소중함을 잘 모르는 것을 안타까워했을 것이다. 그래서 헐버트는 한글로 책을 쓰고 세계에 알렸고, 주시경은 우리말을 연구했다. 나는 한글의 특성을 알리는 만화를 그려 동생에게 보여 주겠다.","scoring_points":["두 사람이 실천한 까닭을 글의 내용을 바탕으로 짐작했는가","두 사람이 한 일을 바르게 썼는가","자신이 실천할 방법을 구체적으로 썼는가"]},"explanation":["인물의 행동에서 마음을 짐작해요.","방법은 달라도 같은 마음이었음을 찾아요.","내가 지금 할 수 있는 일로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L05_challenge#10','kor',4,2,'u2','L05','tb_g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C20',4,'mc','auto','한글과 관련된 인물들이 한 일을 갈래로 묶었어요. 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u2-X18','K4-2-u2-X52']::text[],false,'{"seq":10,"concept":"K4-2-u2-C20","difficulty":4,"kind":"mc","stem":"한글과 관련된 인물들이 한 일을 갈래로 묶었어요. 바르게 묶은 것은 무엇인가요?","options":[{"t":"세종 대왕 — 만들기 · 주시경 — 연구하고 지키기 · 공병우 — 기계로 쉽게 쓰게 하기 · 헐버트 — 세상에 알리기","correct":true},{"t":"세종 대왕 — 연구하고 지키기 · 주시경 — 만들기 · 공병우 — 세상에 알리기 · 헐버트 — 기계로 쉽게 쓰게 하기","mis":"K4-2-u2-X18"},{"t":"세종 대왕 — 만들기 · 주시경 — 기계로 쉽게 쓰게 하기 · 공병우 — 세상에 알리기 · 헐버트 — 연구하고 지키기","mis":"K4-2-u2-X18"},{"t":"네 사람은 모두 같은 일을 했으니 갈래를 나눌 수 없다","mis":"K4-2-u2-X52"}],"explanation":["세종 대왕은 훈민정음을 만들었고, 주시경은 우리말을 연구하고 사전 원고를 썼어요.","공병우는 한글 타자기를, 헐버트는 한글을 세계에 알리는 글을 썼어요.","한글 창제, 보존·연구, 정보화, 알리기로 방법은 달라요."],"asset":{"type":"passage","lines":["세종 대왕(1397~1450) — 우리나라 고유의 문자인 훈민정음을 만듦.","주시경(1876~1914) — 우리말과 한글을 연구하고","제자들과 함께 최초의 국어사전 원고를 씀.","공병우(1906~1995) — 한글을 빠르고 정확하게 입력하려고 한글 타자기를 개발함."],"title":"한글과 관련된 인물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#1','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C30',1,'mc','auto','『국어』 97쪽 1번 (1)이에요. 자료 ㉮에서 우리말 사용과 관련한 문제점은 무엇인가요?',ARRAY['K4-2-u2-X29','K4-2-u2-X24']::text[],false,'{"seq":1,"concept":"K4-2-u2-C30","difficulty":1,"kind":"mc","stem":"『국어』 97쪽 1번 (1)이에요. 자료 ㉮에서 우리말 사용과 관련한 문제점은 무엇인가요?","options":[{"t":"우리말로 쓸 수 있음에도 외국어를 사용했다","correct":true},{"t":"간판 글씨가 너무 작다","mis":"K4-2-u2-X29"},{"t":"외국에서 온 말은 한 글자도 쓰면 안 되는데 썼다","mis":"K4-2-u2-X24"},{"t":"가게 이름이 너무 짧다","mis":"K4-2-u2-X29"}],"explanation":["「Happy」, 「Hello」는 우리말로 충분히 쓸 수 있는 말이에요.","외국어를 쓰는 것 자체보다 바꿀 수 있는데도 지나치게 쓰는 것이 문제예요.","광고지나 안내문에서도 이런 경우를 쉽게 찾을 수 있어요."],"asset":{"type":"passage","lines":["㉮ [그림] 가게 간판 두 개","「Happy 버거」 · 「Hello 마트」"],"title":"자료 ㉮ — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#2','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C32',1,'mc','auto','『국어』 97쪽 1번 (2)예요. 자료 ㉯에 쓰인 말의 뜻을 잘 모르는 사람과 대화할 때 그 말을 쓰면 어떤 문제가 생길까요?',ARRAY['K4-2-u2-X26']::text[],false,'{"seq":2,"concept":"K4-2-u2-C32","difficulty":1,"kind":"mc","stem":"『국어』 97쪽 1번 (2)예요. 자료 ㉯에 쓰인 말의 뜻을 잘 모르는 사람과 대화할 때 그 말을 쓰면 어떤 문제가 생길까요?","options":[{"t":"말뜻을 이해하지 못해 원활하게 대화하기 어렵다","correct":true},{"t":"누구나 아는 말이라 아무 문제가 없다","mis":"K4-2-u2-X26"},{"t":"짧은 말이라 듣는 사람이 더 쉽게 알아듣는다","mis":"K4-2-u2-X26"}],"explanation":["‘심쿵’, ‘열공’은 줄임말이에요.","뜻을 모르는 사람은 무슨 말인지 알 수 없어요.","줄임말을 지나치게 쓰면 의사소통에 방해가 돼요."],"asset":{"type":"passage","lines":["㉯ [그림] 강아지 영상 화면 — # 귀여운 강아지 모음  # 심쿵 주의","㉯ [그림] 공부하는 아이 사진 — # 시험  # 열공"],"title":"자료 ㉯ — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#3','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C33',1,'mc','auto','『국어』 97쪽 1번 (3)이에요. 자료 ㉰에 쓰인 말을 들으면 기분이 어떨까요?',ARRAY['K4-2-u2-X28']::text[],false,'{"seq":3,"concept":"K4-2-u2-C33","difficulty":1,"kind":"mc","stem":"『국어』 97쪽 1번 (3)이에요. 자료 ㉰에 쓰인 말을 들으면 기분이 어떨까요?","options":[{"t":"불쾌한 기분이 들고 화가 날 것이다","correct":true},{"t":"장난으로 한 말이니 아무렇지 않을 것이다","mis":"K4-2-u2-X28"},{"t":"친해진 것 같아 기쁠 것이다","mis":"K4-2-u2-X28"}],"explanation":["「짜증 나게.」, 「재수 없어.」는 상대를 탓하는 거친 말이에요.","이런 말을 들으면 기분이 상하고 화가 나요.","거친 말은 상대의 마음을 다치게 하고 사이를 멀어지게 해요."],"asset":{"type":"speech","turns":[{"who":"아이 1","text":"아야!"},{"who":"아이 2","text":"야, 왜 부딪쳐? 짜증 나게."},{"who":"아이 3","text":"네가 잘못한 거잖아. 재수 없어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#4','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C34',1,'sa','auto','국립국어원 누리집의 ‘다듬은 말’에서 ‘포스트잇’을 쉬운 우리말로 바꾼 말은 무엇인가요?','{}'::text[],false,'{"seq":4,"concept":"K4-2-u2-C34","difficulty":1,"kind":"sa","stem":"국립국어원 누리집의 ‘다듬은 말’에서 ‘포스트잇’을 쉬운 우리말로 바꾼 말은 무엇인가요?","answer":["붙임쪽지"],"explanation":["포스트잇은 붙였다 뗐다 하는 작은 종이예요.","쉬운 우리말로 ‘붙임쪽지’라고 다듬었어요.","드론은 무인기, 쇼핑백은 장바구니로 다듬었어요."],"mis":"K4-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#5','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C34',2,'match','auto','‘다듬은 말’이에요. 외국어 표현과 다듬은 우리말을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u2-C34","difficulty":2,"kind":"match","stem":"‘다듬은 말’이에요. 외국어 표현과 다듬은 우리말을 알맞게 이으세요.","pairs":[{"l":"드론","r":"무인기"},{"l":"쇼핑백","r":"장바구니"},{"l":"홈 쇼핑","r":"안방 구매"}],"mis":"K4-2-u2-X19","explanation":["다듬은 말은 외국어 표현을 고유어나 쉬운 우리말로 바꾼 말이에요.","사람이 타지 않고 나는 기계는 무인기, 물건을 담는 가방은 장바구니예요.","집에서 텔레비전을 보며 사는 것은 안방 구매예요."],"asset":{"type":"passage","lines":["드론 → 무인기","쇼핑백 → 장바구니","포스트잇 → 붙임쪽지","홈 쇼핑 → 안방 구매"],"title":"국립국어원 누리집의 ‘다듬은 말’ (예)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#6','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C29',2,'mc','auto','『국어』 97쪽 2번이에요. 우리말을 바르게 써야 하는 까닭으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u2-X29']::text[],false,'{"seq":6,"concept":"K4-2-u2-C29","difficulty":2,"kind":"mc","stem":"『국어』 97쪽 2번이에요. 우리말을 바르게 써야 하는 까닭으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"글씨를 예쁘게 써야 시험 점수를 잘 받기 때문이다","correct":true},{"t":"바르게 쓰지 않으면 정확한 의사소통을 방해하기 때문이다","mis":"K4-2-u2-X29"},{"t":"우리말은 우리 민족의 소중한 문화유산이기 때문이다","mis":"K4-2-u2-X29"},{"t":"상대와도 좋은 관계를 맺을 수 있기 때문이다","mis":"K4-2-u2-X29"}],"explanation":["친구들은 나라 사랑, 정확한 의사소통, 문화유산, 좋은 관계를 까닭으로 들었어요.","글씨 모양이나 점수는 우리말을 바르게 쓰는 까닭과 상관없어요.","우리말은 우리 민족의 얼이 담긴 문화유산이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리말을 바르게 써야 우리나라를 사랑하는 마음도 기를 수 있기 때문이야."},{"who":"친구 2","text":"우리말을 바르게 쓰지 않으면 정확한 의사소통을 방해하기 때문이야."},{"who":"친구 3","text":"우리말은 우리 민족의 소중한 문화유산이기 때문이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#7','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C30',2,'ox','auto','간판에 외국에서 온 말이 한 글자라도 들어가면 모두 우리말을 잘못 쓴 것이에요.',ARRAY['K4-2-u2-X24']::text[],false,'{"seq":7,"concept":"K4-2-u2-C30","difficulty":2,"kind":"ox","stem":"간판에 외국에서 온 말이 한 글자라도 들어가면 모두 우리말을 잘못 쓴 것이에요.","answer":"X","reason_options":[{"t":"바꿔 쓸 우리말이 있는데도 외국어를 지나치게 쓰는 것이 문제예요.","correct":true},{"t":"버스처럼 굳은 말도 모두 새 우리말로 바꿔야 해요.","mis":"K4-2-u2-X24"}],"mis":"K4-2-u2-X24","explanation":["외국어를 쓰는 것 자체가 문제라기보다 남용이 문제예요.","우리말로 대신할 수 있을 때는 우리말을 먼저 써요.","알맞은 우리말이 없는 말까지 억지로 바꾸지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#8','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C32',2,'mc','auto','줄임말을 쓸 때 가장 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u2-X27','K4-2-u2-X26']::text[],false,'{"seq":8,"concept":"K4-2-u2-C32","difficulty":2,"kind":"mc","stem":"줄임말을 쓸 때 가장 알맞은 태도는 무엇인가요?","options":[{"t":"듣는 사람이 뜻을 아는지, 어떤 상황인지 살펴 쓰고 모를 것 같으면 풀어 쓴다","correct":true},{"t":"줄임말은 어떤 경우에도 절대 쓰면 안 된다","mis":"K4-2-u2-X27"},{"t":"내가 아는 줄임말은 누구에게나 써도 된다","mis":"K4-2-u2-X26"}],"explanation":["줄임말을 모르는 사람과는 뜻이 통하지 않아요.","듣는 사람과 상황을 살피는 것이 먼저예요.","뜻을 모를 것 같으면 풀어서 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#9','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C29',2,'mc','auto','「우리말은 우리 민족의 소중한 문화유산이기 때문이야.」라는 까닭과 가장 잘 이어지는 실천은 무엇인가요?',ARRAY['K4-2-u2-X25','K4-2-u2-X29']::text[],false,'{"seq":9,"concept":"K4-2-u2-C29","difficulty":2,"kind":"mc","stem":"「우리말은 우리 민족의 소중한 문화유산이기 때문이야.」라는 까닭과 가장 잘 이어지는 실천은 무엇인가요?","options":[{"t":"조상에게서 이어받은 우리말을 아끼고 가꾸어 다음 사람에게 물려준다","correct":true},{"t":"외국어를 많이 섞어 쓸수록 우리말이 멋져진다","mis":"K4-2-u2-X25"},{"t":"옛날 말만 골라 써야 문화유산을 지킨다","mis":"K4-2-u2-X29"}],"explanation":["문화유산은 조상에게서 이어받아 다음 세대에 물려줄 소중한 것이에요.","우리말에는 우리 민족의 얼이 담겨 있어요.","아끼고 바르게 쓰는 것이 우리말을 가꾸는 일이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리말을 바르게 써야 우리나라를 사랑하는 마음도 기를 수 있기 때문이야."},{"who":"친구 2","text":"우리말을 바르게 쓰지 않으면 정확한 의사소통을 방해하기 때문이야."},{"who":"친구 3","text":"우리말은 우리 민족의 소중한 문화유산이기 때문이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_basic#10','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C33',3,'error','auto','자료 ㉰처럼 놀다가 부딪쳤을 때 할 말을 친구들이 바꾸어 보았어요. 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u2-X28']::text[],false,'{"seq":10,"concept":"K4-2-u2-C33","difficulty":3,"kind":"error","stem":"자료 ㉰처럼 놀다가 부딪쳤을 때 할 말을 친구들이 바꾸어 보았어요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"「장난으로 한 말이니까 괜찮아.」 하고 거친 말을 그대로 둔다.","correct":true,"mis_target":"K4-2-u2-X28"},{"t":"「미안해, 내가 앞을 잘 못 봤어. 괜찮니?」","mis":"K4-2-u2-X28"},{"t":"「나도 조심할게. 다친 데는 없어?」","mis":"K4-2-u2-X28"}],"explanation":["거친 말은 장난이라도 상대의 기분을 상하게 해요.","부딪쳤을 때는 사과하고 상대를 걱정하는 말을 해요.","바른 말을 쓰면 상대와 좋은 관계를 맺을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"아이 1","text":"아야!"},{"who":"아이 2","text":"야, 왜 부딪쳐? 짜증 나게."},{"who":"아이 3","text":"네가 잘못한 거잖아. 재수 없어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#1','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C34',2,'mc','auto','외국어 표현을 쉬운 우리말로 바꾼 ‘다듬은 말’을 찾아볼 수 있는 곳으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":1,"concept":"K4-2-u2-C34","difficulty":2,"kind":"mc","stem":"외국어 표현을 쉬운 우리말로 바꾼 ‘다듬은 말’을 찾아볼 수 있는 곳으로 알맞은 것은 무엇인가요?","options":[{"t":"국립국어원 누리집","correct":true},{"t":"가게 앞에 붙은 광고지","mis":"K4-2-u2-X19"},{"t":"외국어로 된 안내문","mis":"K4-2-u2-X19"}],"explanation":["국립국어원은 우리말과 우리글을 연구하는 기관이에요.","누리집의 ‘다듬은 말’에서 다양한 사례를 찾을 수 있어요.","드론 → 무인기, 홈 쇼핑 → 안방 구매처럼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#2','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C30',2,'mc','auto','자료 ㉮의 「Happy 버거」와 「Hello 마트」에 함께 나타나는 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X25','K4-2-u2-X24']::text[],false,'{"seq":2,"concept":"K4-2-u2-C30","difficulty":2,"kind":"mc","stem":"자료 ㉮의 「Happy 버거」와 「Hello 마트」에 함께 나타나는 점으로 알맞은 것은 무엇인가요?","options":[{"t":"우리말로 쓸 수 있는 말을 외국어로 써서 섞었다","correct":true},{"t":"모두 순우리말로만 지은 이름이다","mis":"K4-2-u2-X25"},{"t":"바꿔 쓸 우리말이 없는 말만 골랐다","mis":"K4-2-u2-X24"}],"explanation":["「Happy」는 ‘행복한’, 「Hello」는 ‘안녕’처럼 우리말로 쓸 수 있어요.","외국어와 한글을 섞어 쓴 이름이에요.","이런 이름은 뜻을 모르는 사람에게 불편할 수 있어요."],"asset":{"type":"passage","lines":["㉮ [그림] 가게 간판 두 개","「Happy 버거」 · 「Hello 마트」"],"title":"자료 ㉮ — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#3','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C31',3,'mc','auto','다음 가운데 바꿔 쓸 알맞은 우리말이 없어서 그대로 써도 되는 말은 무엇인가요?',ARRAY['K4-2-u2-X25']::text[],false,'{"seq":3,"concept":"K4-2-u2-C31","difficulty":3,"kind":"mc","stem":"다음 가운데 바꿔 쓸 알맞은 우리말이 없어서 그대로 써도 되는 말은 무엇인가요?","options":[{"t":"버스","correct":true},{"t":"쇼핑백","mis":"K4-2-u2-X25"},{"t":"포스트잇","mis":"K4-2-u2-X25"},{"t":"드론","mis":"K4-2-u2-X25"}],"explanation":["쇼핑백은 장바구니, 포스트잇은 붙임쪽지, 드론은 무인기로 쓸 수 있어요.","버스는 알맞은 우리말이 없이 우리말처럼 굳은 말이에요.","알맞은 우리말이 없을 때 억지로 새말을 만들지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#4','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C32',3,'mc','auto','할아버지께 자료 ㉯의 강아지 영상을 보여 드리려고 해요. 「# 심쿵 주의」를 바꾸어 쓴 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X26']::text[],false,'{"seq":4,"concept":"K4-2-u2-C32","difficulty":3,"kind":"mc","stem":"할아버지께 자료 ㉯의 강아지 영상을 보여 드리려고 해요. 「# 심쿵 주의」를 바꾸어 쓴 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"# 보면 가슴이 쿵쿵 뛸 만큼 귀여워요","correct":true},{"t":"# 심쿵 주의 (그대로 둔다)","mis":"K4-2-u2-X26"},{"t":"# ㅅㅋ 주의","mis":"K4-2-u2-X26"}],"explanation":["할아버지께서는 ‘심쿵’이라는 말을 모르셨어요.","듣는 사람이 아는 말로 풀어 쓰면 뜻이 잘 전해져요.","더 줄이면 뜻을 알기가 더 어려워요."],"asset":{"type":"passage","lines":["㉯ [그림] 강아지 영상 화면 — # 귀여운 강아지 모음  # 심쿵 주의","㉯ [그림] 공부하는 아이 사진 — # 시험  # 열공"],"title":"자료 ㉯ — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#5','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C29',3,'mc','auto','자료 ㉯의 줄임말이 일으키는 문제와 가장 가까운 까닭은 무엇인가요?',ARRAY['K4-2-u2-X29']::text[],false,'{"seq":5,"concept":"K4-2-u2-C29","difficulty":3,"kind":"mc","stem":"자료 ㉯의 줄임말이 일으키는 문제와 가장 가까운 까닭은 무엇인가요?","options":[{"t":"우리말을 바르게 쓰지 않으면 정확한 의사소통을 방해한다","correct":true},{"t":"거친 말은 상대의 기분을 상하게 한다","mis":"K4-2-u2-X29"},{"t":"외국어 간판은 외국 가게처럼 보인다","mis":"K4-2-u2-X29"}],"explanation":["줄임말은 뜻을 아는 사람끼리만 통해요.","뜻을 모르는 사람과는 원활하게 대화하기 어려워요.","그래서 줄임말 문제는 정확한 의사소통과 이어져요."],"asset":{"type":"passage","lines":["㉯ [그림] 강아지 영상 화면 — # 귀여운 강아지 모음  # 심쿵 주의","㉯ [그림] 공부하는 아이 사진 — # 시험  # 열공"],"title":"자료 ㉯ — 『국어』 96쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#6','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C33',3,'ox','auto','놀다가 부딪쳤을 때 친구끼리 주고받은 거친 말은 장난이니까 괜찮아요.',ARRAY['K4-2-u2-X28']::text[],false,'{"seq":6,"concept":"K4-2-u2-C33","difficulty":3,"kind":"ox","stem":"놀다가 부딪쳤을 때 친구끼리 주고받은 거친 말은 장난이니까 괜찮아요.","answer":"X","reason_options":[{"t":"거친 말은 장난이라도 상대의 기분을 상하게 하고 사이를 멀어지게 해요.","correct":true},{"t":"친구끼리는 어떤 말을 해도 다 장난으로 받아들여요.","mis":"K4-2-u2-X28"}],"mis":"K4-2-u2-X28","explanation":["자료 ㉰의 친구들은 서로 화가 나 있어요.","듣는 사람의 기분을 생각해야 해요.","상대의 기분을 상하게 하는 비속어는 쓰지 않아요."],"asset":{"type":"speech","turns":[{"who":"아이 1","text":"아야!"},{"who":"아이 2","text":"야, 왜 부딪쳐? 짜증 나게."},{"who":"아이 3","text":"네가 잘못한 거잖아. 재수 없어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#7','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C29',3,'match','auto','『국어』 96~97쪽 자료 ㉮~㉰와 우리말 사용의 문제점을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u2-C29","difficulty":3,"kind":"match","stem":"『국어』 96~97쪽 자료 ㉮~㉰와 우리말 사용의 문제점을 알맞게 이으세요.","pairs":[{"l":"㉮ 「Happy 버거」 · 「Hello 마트」","r":"우리말로 쓸 수 있는데 외국어를 지나치게 씀"},{"l":"㉯ # 심쿵 주의 · # 열공","r":"뜻을 모르는 사람과 대화하기 어려운 줄임말을 씀"},{"l":"㉰ 「짜증 나게.」","r":"상대를 불쾌하게 하는 비속어를 씀"}],"mis":"K4-2-u2-X29","explanation":["㉮는 외국어 남용이에요.","㉯는 줄임말의 지나친 사용이에요.","㉰는 비속어 사용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#8','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C29',4,'essay','teacher','『국어』 97쪽 2번이에요. 자료 ㉮~㉰ 가운데 하나를 골라, 그 자료와 이어서 우리말을 바르게 써야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C29","difficulty":4,"kind":"essay","stem":"『국어』 97쪽 2번이에요. 자료 ㉮~㉰ 가운데 하나를 골라, 그 자료와 이어서 우리말을 바르게 써야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 자료 ㉯처럼 ‘심쿵’, ‘열공’ 같은 줄임말을 지나치게 쓰면 할아버지처럼 뜻을 모르는 사람과는 대화가 잘 통하지 않는다. 우리말을 바르게 써야 정확하게 의사소통할 수 있으므로 우리말을 바르게 써야 한다.","scoring_points":["자료 하나를 골라 그 자료의 문제점을 썼는가","우리말을 바르게 써야 하는 까닭을 썼는가","문제점과 까닭이 서로 이어지는가"]},"explanation":["㉮ 외국어 남용, ㉯ 줄임말, ㉰ 비속어 가운데 골라요.","그 문제가 누구에게 어떤 불편을 주는지 생각해요.","의사소통, 문화유산, 나라 사랑, 좋은 관계 가운데 알맞은 까닭과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#9','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C30',4,'essay','teacher','학교 주변이나 집 주변의 간판, 현수막, 광고지에서 우리말로 바꿀 수 있는데도 외국어를 쓴 예를 하나 들고, 우리말로 바꾸어 쓴 뒤 그렇게 바꾼 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C30","difficulty":4,"kind":"essay","stem":"학교 주변이나 집 주변의 간판, 현수막, 광고지에서 우리말로 바꿀 수 있는데도 외국어를 쓴 예를 하나 들고, 우리말로 바꾸어 쓴 뒤 그렇게 바꾼 까닭을 쓰세요.","answer_guide":{"answer":"예: 학교 앞 분식집에 「SALE 이벤트」라는 현수막이 있었다. 「할인 행사」로 바꾸어 쓰겠다. 우리말로 충분히 쓸 수 있는데 외국어로 쓰면 뜻을 모르는 사람에게 불편하고, 누구나 알아보기 쉬운 우리말을 써야 정확하게 뜻이 전해지기 때문이다.","scoring_points":["우리말로 바꿀 수 있는 외국어를 썼는가","알맞은 우리말로 바꾸어 썼는가","바꾼 까닭을 우리말을 바르게 써야 하는 까닭과 이어 썼는가"]},"explanation":["일상생활의 읽기 자료에서 찾아요.","바꿔 쓸 우리말이 있는 말만 골라요.","알맞은 우리말이 없는 굳은 말은 억지로 바꾸지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L07_challenge#10','kor',4,2,'u2','L07','tb_g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C32',4,'mc','auto','『국어』 81쪽 생각 열기에서 여자아이가 할아버지와 잘 이야기하려면 어떻게 하는 것이 가장 알맞을까요?',ARRAY['K4-2-u2-X26','K4-2-u2-X27']::text[],false,'{"seq":10,"concept":"K4-2-u2-C32","difficulty":4,"kind":"mc","stem":"『국어』 81쪽 생각 열기에서 여자아이가 할아버지와 잘 이야기하려면 어떻게 하는 것이 가장 알맞을까요?","options":[{"t":"할아버지께서 아시는 말로 「가슴이 쿵 할 만큼 좋았다」처럼 풀어 말한다","correct":true},{"t":"할아버지께서도 요즘 말을 배우셔야 하니 계속 줄임말로 말한다","mis":"K4-2-u2-X26"},{"t":"줄임말은 나쁜 말이니 앞으로 친구에게도 절대 쓰지 않는다","mis":"K4-2-u2-X27"}],"explanation":["할아버지께서는 ‘심쿵’이 무슨 뜻인지 모르셨어요.","듣는 사람이 아는 말로 풀어 말하면 대화가 잘 통해요.","친구와 뜻이 통하는 자리라면 줄임말을 무조건 금지할 필요는 없어요."],"asset":{"type":"passage","lines":["[그림] 「우리 꽃집」 간판 앞에서 꽃집 주인이 고민하고 있다.","꽃집 주인: “가게 이름에 외국어를 넣으면 더 멋져 보일까?”","[그림] 「달콤 cafe」 앞 의자에 여자아이와 할아버지가 앉아 있다.","여자아이: “그 영상을 보고 정말 심쿵했다니까요.”","할아버지: “심쿵? 무슨 말이지?”","우리말과 우리글을 올바르게 쓰려면 어떤 노력을 해야 할까요?"],"title":"생각 열기 — 『국어』 81쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#1','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C35',1,'mc','auto','‘보고’와 관련 있는 장면을 떠올렸어요. 이 장면들에서 알 수 있는 ‘보고’의 뜻은 무엇인가요?',ARRAY['K4-2-u2-X30','K4-2-u2-X37','K4-2-u2-X35']::text[],false,'{"seq":1,"concept":"K4-2-u2-C35","difficulty":1,"kind":"mc","stem":"‘보고’와 관련 있는 장면을 떠올렸어요. 이 장면들에서 알 수 있는 ‘보고’의 뜻은 무엇인가요?","options":[{"t":"알아보거나 한 일의 과정과 결과를 있는 그대로 알리는 것","correct":true},{"t":"내 생각대로 꾸며서 재미있게 알리는 것","mis":"K4-2-u2-X30"},{"t":"남의 글을 그대로 옮겨 쓰는 것","mis":"K4-2-u2-X37"},{"t":"좋은 결과만 골라 자랑하는 것","mis":"K4-2-u2-X35"}],"explanation":["경찰은 수사한 결과를, 체험 학습을 다녀온 학생은 한 일을 보고해요.","보고는 한 일의 과정과 결과를 알리는 것이에요.","꾸미거나 부풀리지 않고 있는 그대로 알려야 해요."],"asset":{"type":"passage","lines":["· 경찰이 수사한 결과를 보고하는 것","· 체험 학습을 다녀온 뒤 그 결과를 ‘보고서’로 내는 것","· 회사에서 생긴 일을 사장에게 알리며 “보고합니다.”라고 말하는 장면"],"title":"‘보고’와 관련 있는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#2','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C36',1,'sa','auto','『국어』 99쪽 2번 (1)이에요. 지후는 우리 반 친구들의 무엇 사용에 대하여 조사했나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u2-C36","difficulty":1,"kind":"sa","stem":"『국어』 99쪽 2번 (1)이에요. 지후는 우리 반 친구들의 무엇 사용에 대하여 조사했나요? 한 낱말로 쓰세요.","answer":["줄임말"],"explanation":["제목을 보면 무엇을 조사했는지 알 수 있어요.","제목은 「우리 반 친구들의 줄임말 사용」이에요.","지후는 줄임말 사용에 대하여 보고하는 글을 썼어요."],"asset":{"type":"passage","lines":["제목 — 우리 반 친구들의 줄임말 사용","조사 대상 — 4학년 ○반 학생 20명","조사 기간 — 20○○년 ○○월 ○○일~○○월 ○○일","조사 동기 — 초등학생이 줄임말을 지나치게 사용한다는 기사를 보고","우리 반 친구들의 줄임말 사용에 대하여 조사해 보고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 인터넷 조사"],"title":"지후가 쓴 보고하는 글 ① — 『국어』 98쪽"},"mis":"K4-2-u2-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#3','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C37',1,'mc','auto','『국어』 99쪽 3번이에요. 지후가 「친구들이 줄임말을 사용하는 까닭」을 알아보려고 할 때 알맞은 조사 방법은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":3,"concept":"K4-2-u2-C37","difficulty":1,"kind":"mc","stem":"『국어』 99쪽 3번이에요. 지후가 「친구들이 줄임말을 사용하는 까닭」을 알아보려고 할 때 알맞은 조사 방법은 무엇인가요?","options":[{"t":"면담 조사","correct":true},{"t":"설문 조사","mis":"K4-2-u2-X33"},{"t":"인터넷 조사","mis":"K4-2-u2-X33"}],"explanation":["까닭은 친구를 직접 만나 물어보아야 자세히 알 수 있어요.","그래서 면담 조사가 알맞아요.","줄임말을 쓰는 상황은 설문 조사, 특징과 문제점은 인터넷 조사로 알아보았어요."],"asset":{"type":"passage","lines":["조사 대상 — 4학년 ○반 학생 20명","조사할 내용 ㉠ 친구들이 줄임말을 사용하는 상황 — 매체 자료: 그래프","조사할 내용 ㉡ 친구들이 줄임말을 사용하는 까닭","조사할 내용 ㉢ 줄임말을 사용할 때의 특징과 문제점","보기(조사 방법): 설문 조사 · 면담 조사 · 인터넷 조사"],"title":"지후의 조사 계획 — 『국어』 99쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#4','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C36',1,'mc','auto','지후가 쓴 보고하는 글에 들어 있지 않은 것은 무엇인가요?',ARRAY['K4-2-u2-X30']::text[],false,'{"seq":4,"concept":"K4-2-u2-C36","difficulty":1,"kind":"mc","stem":"지후가 쓴 보고하는 글에 들어 있지 않은 것은 무엇인가요?","options":[{"t":"조사한 친구들의 이름과 전화번호","correct":true},{"t":"조사 대상","mis":"K4-2-u2-X30"},{"t":"조사 기간","mis":"K4-2-u2-X30"},{"t":"참고 자료와 그 출처","mis":"K4-2-u2-X30"}],"explanation":["지후의 글에는 제목, 조사 대상, 기간, 동기, 방법이 있어요.","조사한 내용, 조사 소감, 참고 자료와 그 출처도 있어요.","친구들의 이름과 전화번호는 보고하는 글에 쓰지 않아요."],"asset":{"type":"passage","lines":["제목 — 우리 반 친구들의 줄임말 사용","조사 대상 — 4학년 ○반 학생 20명","조사 기간 — 20○○년 ○○월 ○○일~○○월 ○○일","조사 동기 — 초등학생이 줄임말을 지나치게 사용한다는 기사를 보고","우리 반 친구들의 줄임말 사용에 대하여 조사해 보고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 인터넷 조사"],"title":"지후가 쓴 보고하는 글 ① — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#5','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C43',2,'mc','auto','『국어』 99쪽 2번 (3)이에요. 지후는 조사하고 나서 어떤 생각을 했나요?',ARRAY['K4-2-u2-X22','K4-2-u2-X30']::text[],false,'{"seq":5,"concept":"K4-2-u2-C43","difficulty":2,"kind":"mc","stem":"『국어』 99쪽 2번 (3)이에요. 지후는 조사하고 나서 어떤 생각을 했나요?","options":[{"t":"줄임말을 너무 많이 쓰면 맞춤법과 어휘 실력이 낮아질 수 있으니 바른 언어생활을 하도록 노력해야겠다","correct":true},{"t":"줄임말을 쓰는 친구를 모두 혼내 주어야겠다","mis":"K4-2-u2-X22"},{"t":"줄임말은 짧아서 편하니 더 많이 써야겠다","mis":"K4-2-u2-X30"}],"explanation":["지후의 생각은 「조사 소감」 칸에 있어요.","많은 친구가 줄임말을 써서 놀랐다고 했어요.","그리고 바른 언어생활을 하도록 노력해야겠다고 했어요."],"asset":{"type":"passage","lines":["인터넷 뉴스 기사에서 조사해 보니 줄임말은 학년이 올라갈수록,","하루에 한 시간 이상 컴퓨터나 휴대 전화를 쓸수록 더 많이 사용했다.","또 줄임말을 자주 쓰면 맞춤법과 어휘 실력이 낮아질 수 있다는 점도 알았다.","조사 소감 — 많은 친구가 줄임말을 사용하고 있어서 놀라웠다.","바른 언어생활을 하도록 노력해야겠다고 생각했다.","참고 자료와 그 출처 — ○○○ 기자, 「줄임말로 대화하는 초등학생」,","『○○일보』, 20○○. ○○. ○○."],"title":"지후가 쓴 보고하는 글 ③ — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#6','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C37',2,'mc','auto','『국어』 99쪽 2번 (2)예요. 지후가 인터넷 조사로 새롭게 안 내용은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":6,"concept":"K4-2-u2-C37","difficulty":2,"kind":"mc","stem":"『국어』 99쪽 2번 (2)예요. 지후가 인터넷 조사로 새롭게 안 내용은 무엇인가요?","options":[{"t":"줄임말은 학년이 올라갈수록, 컴퓨터나 휴대 전화를 오래 쓸수록 더 많이 사용한다","correct":true},{"t":"열여덟 명이 줄임말을 자주 사용했다","mis":"K4-2-u2-X33"},{"t":"짧아서 쓰기 편하고 습관이 되어 줄임말을 쓴다","mis":"K4-2-u2-X33"}],"explanation":["인터넷 뉴스 기사에서 조사한 내용을 찾아요.","학년, 컴퓨터·휴대 전화 사용 시간과 줄임말의 관계를 알았어요.","열여덟 명은 설문 조사, 쓰는 까닭은 면담 조사 결과예요."],"asset":{"type":"passage","lines":["인터넷 뉴스 기사에서 조사해 보니 줄임말은 학년이 올라갈수록,","하루에 한 시간 이상 컴퓨터나 휴대 전화를 쓸수록 더 많이 사용했다.","또 줄임말을 자주 쓰면 맞춤법과 어휘 실력이 낮아질 수 있다는 점도 알았다.","조사 소감 — 많은 친구가 줄임말을 사용하고 있어서 놀라웠다.","바른 언어생활을 하도록 노력해야겠다고 생각했다.","참고 자료와 그 출처 — ○○○ 기자, 「줄임말로 대화하는 초등학생」,","『○○일보』, 20○○. ○○. ○○."],"title":"지후가 쓴 보고하는 글 ③ — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#7','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C40',2,'mc','auto','지후가 줄임말을 사용하는 상황을 그래프로 나타낸 까닭은 무엇인가요?',ARRAY['K4-2-u2-X43','K4-2-u2-X41']::text[],false,'{"seq":7,"concept":"K4-2-u2-C40","difficulty":2,"kind":"mc","stem":"지후가 줄임말을 사용하는 상황을 그래프로 나타낸 까닭은 무엇인가요?","options":[{"t":"조사 결과를 한눈에 알아보기 쉽게 하려고","correct":true},{"t":"글을 알록달록 예쁘게 꾸미려고","mis":"K4-2-u2-X43"},{"t":"글이 더 길어 보이게 하려고","mis":"K4-2-u2-X41"}],"explanation":["메신저 8명, 인터넷 5명, 일상 대화 3명, 게임 2명을 막대로 나타냈어요.","그래프를 보면 어느 상황이 가장 많은지 한눈에 알 수 있어요.","표, 그림, 사진, 그래프는 조사 결과를 효과적으로 전해요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#8','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C39',2,'mc','auto','면담 조사를 할 때 지켜야 할 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X34']::text[],false,'{"seq":8,"concept":"K4-2-u2-C39","difficulty":2,"kind":"mc","stem":"면담 조사를 할 때 지켜야 할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"면담 대상자가 말하는 도중에 끼어들지 않는다","correct":true},{"t":"들은 말을 내 생각대로 바꾸어 적는다","mis":"K4-2-u2-X34"},{"t":"질문지는 준비하지 않고 그때그때 떠올려 묻는다","mis":"K4-2-u2-X34"}],"explanation":["면담 대상자의 말을 끝까지 들어요.","질문지를 미리 준비해요.","녹음하거나 기록해서 내용이 과장·왜곡되지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#9','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C37',2,'match','auto','『국어』 100쪽 3번 (2)예요. 조사 방법과 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C37","difficulty":2,"kind":"match","stem":"『국어』 100쪽 3번 (2)예요. 조사 방법과 그 특징을 알맞게 이으세요.","pairs":[{"l":"설문 조사","r":"하나의 질문에 하나의 답만 나오도록 질문을 구성한다."},{"l":"면담 조사","r":"면담한 내용을 녹음하거나 기록해 과장·왜곡되지 않게 한다."},{"l":"인터넷 조사","r":"출처가 분명한 자료인지 확인한다."},{"l":"방문 조사","r":"주제와 관련 있는 곳에 가야 해서 시간이 길어질 수 있다."}],"mis":"K4-2-u2-X33","explanation":["설문은 여러 사람에게 같은 질문지로 물어요.","면담은 직접 만나서 묻고, 인터넷은 출처를 확인해요.","방문은 관련 있는 곳에 직접 찾아가요."],"asset":{"type":"passage","lines":["설문 조사 — 질문의 내용을 분명하게, 설문 목적을 분명히,","하나의 질문에 하나의 답만 나오도록 질문을 구성한다.","면담 조사 — 말하는 도중에 끼어들지 않고, 질문지를 준비하고,","면담한 내용을 녹음하거나 기록해 과장·왜곡되지 않게 한다.","인터넷 조사 — 출처가 분명한 자료인지, 틀린 점이 없는지 살피고 출처를 밝힌다.","방문 조사 — 주제와 관련 있는 곳에 가며, 사진과 그림을 활용하면 좋다.","방문 조사는 조사 시간이 길어질 수 있다는 단점이 있다."],"title":"여러 가지 조사 방법의 특징 — 『국어』 100쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_basic#10','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C41',3,'error','auto','지후가 보고하는 글을 쓰기 전에 메모를 했어요. 다음 가운데 잘못된 메모는 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X43','K4-2-u2-X30']::text[],false,'{"seq":10,"concept":"K4-2-u2-C41","difficulty":3,"kind":"error","stem":"지후가 보고하는 글을 쓰기 전에 메모를 했어요. 다음 가운데 잘못된 메모는 무엇인가요?","options":[{"t":"줄임말을 자주 쓴다는 친구는 열여덟 명이지만, 심각성을 알리려면 스무 명이라고 써야겠어.","correct":true,"mis_target":"K4-2-u2-X35"},{"t":"줄임말을 쓰는 상황은 그래프로 나타내 한눈에 보기 쉽게 해야지.","mis":"K4-2-u2-X43"},{"t":"조사 대상이 4학년 ○반 학생 20명이라는 것을 밝혀 써야지.","mis":"K4-2-u2-X30"}],"explanation":["설문 조사 결과는 열여덟 명이었어요.","문제를 알리려고 수를 바꾸면 결과를 왜곡하는 거예요.","조사 결과는 조사한 그대로 열여덟 명이라고 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#1','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C38',2,'mc','auto','지후의 조사 계획에서 「줄임말을 사용할 때의 특징과 문제점」을 알아보는 데 알맞은 조사 방법은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":1,"concept":"K4-2-u2-C38","difficulty":2,"kind":"mc","stem":"지후의 조사 계획에서 「줄임말을 사용할 때의 특징과 문제점」을 알아보는 데 알맞은 조사 방법은 무엇인가요?","options":[{"t":"인터넷 조사","correct":true},{"t":"설문 조사","mis":"K4-2-u2-X33"},{"t":"면담 조사","mis":"K4-2-u2-X33"}],"explanation":["특징과 문제점은 여러 자료를 찾아보아야 알 수 있어요.","지후는 인터넷 뉴스 기사에서 찾았어요.","인터넷 조사를 할 때에는 출처가 분명한 자료인지 확인해요."],"asset":{"type":"passage","lines":["조사 대상 — 4학년 ○반 학생 20명","조사할 내용 ㉠ 친구들이 줄임말을 사용하는 상황 — 매체 자료: 그래프","조사할 내용 ㉡ 친구들이 줄임말을 사용하는 까닭","조사할 내용 ㉢ 줄임말을 사용할 때의 특징과 문제점","보기(조사 방법): 설문 조사 · 면담 조사 · 인터넷 조사"],"title":"지후의 조사 계획 — 『국어』 99쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#2','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C38',2,'ox','auto','조사 방법을 많이 쓸수록 무조건 좋은 보고하는 글이 돼요.',ARRAY['K4-2-u2-X31']::text[],false,'{"seq":2,"concept":"K4-2-u2-C38","difficulty":2,"kind":"ox","stem":"조사 방법을 많이 쓸수록 무조건 좋은 보고하는 글이 돼요.","answer":"X","reason_options":[{"t":"조사할 내용에 알맞은 조사 방법을 고르는 것이 중요해요.","correct":true},{"t":"방법을 많이 쓸수록 믿을 수 있는 글이에요.","mis":"K4-2-u2-X31"}],"mis":"K4-2-u2-X31","explanation":["지후는 조사할 내용마다 알맞은 방법을 골랐어요.","상황은 설문, 까닭은 면담, 특징과 문제점은 인터넷으로 알아보았어요.","방법의 개수보다 알맞음이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#3','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C41',3,'mc','auto','『국어』 101쪽 지후의 메모 ㉢을 고칠 때 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X56','K4-2-u2-X41','K4-2-u2-X39']::text[],false,'{"seq":3,"concept":"K4-2-u2-C41","difficulty":3,"kind":"mc","stem":"『국어』 101쪽 지후의 메모 ㉢을 고칠 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"조사 결과를 마음대로 줄이면 안 되니 까닭 세 가지를 모두 써야 한다","correct":true},{"t":"글이 길어지지 않게 까닭은 한 가지만 쓰면 된다","mis":"K4-2-u2-X56"},{"t":"까닭을 하나 더 지어내 네 가지로 써야 한다","mis":"K4-2-u2-X41"},{"t":"까닭은 내 생각이니 조사 소감에만 쓴다","mis":"K4-2-u2-X39"}],"explanation":["면담 결과 친구들이 말한 까닭은 세 가지였어요.","줄여서 쓰는 것도 조사 결과를 바꾸는 일이에요.","짧아서, 습관이 되어서, 친구들이 많이 써서 — 세 가지 모두 써야 해요."],"asset":{"type":"passage","lines":["㉠ 줄임말을 자주 사용한다고 답한 친구는 열여덟 명이었지만","문제의 심각성을 알리려면 스무 명이라고 써야겠어.","㉡ 줄임말을 쓰는 상황에 대한 결과를 그래프로 나타내 한눈에 보기 쉽게 해야지.","㉢ 면담 결과, 친구들이 줄임말을 쓰는 까닭은 세 가지였지만","글을 쓸 때에는 두 가지만 써야겠다.","㉣ 뉴스 기사의 출처를 글에 쓸 때에는 간단하게 기사의 제목만 쓰면 되겠지?"],"title":"지후의 메모 — 『국어』 101쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#4','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C42',3,'mc','auto','지후의 메모 ㉣처럼 뉴스 기사를 참고했을 때 출처를 바르게 쓰는 방법은 무엇인가요?',ARRAY['K4-2-u2-X57','K4-2-u2-X37']::text[],false,'{"seq":4,"concept":"K4-2-u2-C42","difficulty":3,"kind":"mc","stem":"지후의 메모 ㉣처럼 뉴스 기사를 참고했을 때 출처를 바르게 쓰는 방법은 무엇인가요?","options":[{"t":"기자 이름, 기사 제목, 발행한 곳, 발행 일자를 분명하게 쓴다","correct":true},{"t":"기사 제목만 간단하게 쓰면 된다","mis":"K4-2-u2-X57"},{"t":"「인터넷」이라고만 쓰면 된다","mis":"K4-2-u2-X37"},{"t":"기사는 출처를 쓰지 않아도 된다","mis":"K4-2-u2-X37"}],"explanation":["출처는 그 자료를 누가, 어디에서, 언제 냈는지 알려 줘요.","지후의 글처럼 「○○○ 기자, 「제목」, 『○○일보』, 날짜」로 써요.","제목만 쓰면 읽는 사람이 자료를 다시 찾기 어려워요."],"asset":{"type":"passage","lines":["㉠ 줄임말을 자주 사용한다고 답한 친구는 열여덟 명이었지만","문제의 심각성을 알리려면 스무 명이라고 써야겠어.","㉡ 줄임말을 쓰는 상황에 대한 결과를 그래프로 나타내 한눈에 보기 쉽게 해야지.","㉢ 면담 결과, 친구들이 줄임말을 쓰는 까닭은 세 가지였지만","글을 쓸 때에는 두 가지만 써야겠다.","㉣ 뉴스 기사의 출처를 글에 쓸 때에는 간단하게 기사의 제목만 쓰면 되겠지?"],"title":"지후의 메모 — 『국어』 101쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#5','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C43',3,'mc','auto','지후가 쓴 보고하는 글에서 조사한 사실이 아니라 지후의 생각이 담긴 문장은 무엇인가요?',ARRAY['K4-2-u2-X39']::text[],false,'{"seq":5,"concept":"K4-2-u2-C43","difficulty":3,"kind":"mc","stem":"지후가 쓴 보고하는 글에서 조사한 사실이 아니라 지후의 생각이 담긴 문장은 무엇인가요?","options":[{"t":"바른 언어생활을 하도록 노력해야겠다고 생각했다.","correct":true},{"t":"설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","mis":"K4-2-u2-X39"},{"t":"메신저와 인터넷에서 많이 사용했다.","mis":"K4-2-u2-X39"}],"explanation":["조사한 내용에는 알아낸 사실을 있는 그대로 써요.","조사 소감에는 조사하고 나서 든 생각을 써요.","「노력해야겠다」는 지후의 다짐이라 조사 소감에 들어가요."],"asset":{"type":"passage","lines":["인터넷 뉴스 기사에서 조사해 보니 줄임말은 학년이 올라갈수록,","하루에 한 시간 이상 컴퓨터나 휴대 전화를 쓸수록 더 많이 사용했다.","또 줄임말을 자주 쓰면 맞춤법과 어휘 실력이 낮아질 수 있다는 점도 알았다.","조사 소감 — 많은 친구가 줄임말을 사용하고 있어서 놀라웠다.","바른 언어생활을 하도록 노력해야겠다고 생각했다.","참고 자료와 그 출처 — ○○○ 기자, 「줄임말로 대화하는 초등학생」,","『○○일보』, 20○○. ○○. ○○."],"title":"지후가 쓴 보고하는 글 ③ — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#6','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C36',3,'mc','auto','보고하는 글을 쓸 때 일반적으로 거치는 과정을 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K4-2-u2-X30']::text[],false,'{"seq":6,"concept":"K4-2-u2-C36","difficulty":3,"kind":"mc","stem":"보고하는 글을 쓸 때 일반적으로 거치는 과정을 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"주제 정하기 → 계획 세우기 → 자료 조사하기 → 보고하는 글 쓰기","correct":true},{"t":"보고하는 글 쓰기 → 주제 정하기 → 자료 조사하기 → 계획 세우기","mis":"K4-2-u2-X30"},{"t":"자료 조사하기 → 보고하는 글 쓰기 → 계획 세우기 → 주제 정하기","mis":"K4-2-u2-X30"}],"explanation":["먼저 무엇을 조사할지 주제를 정해요.","조사 대상, 기간, 방법을 계획하고 자료를 조사해요.","조사한 내용을 바탕으로 마지막에 보고하는 글을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#7','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C38',3,'mc','auto','‘긍정 언어’에 대한 보고하는 글을 쓰려고 조사 계획을 세워요. 조사할 내용과 조사 방법을 알맞게 짝 지은 것은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":7,"concept":"K4-2-u2-C38","difficulty":3,"kind":"mc","stem":"‘긍정 언어’에 대한 보고하는 글을 쓰려고 조사 계획을 세워요. 조사할 내용과 조사 방법을 알맞게 짝 지은 것은 무엇인가요?","options":[{"t":"우리 반 친구들이 듣고 싶은 긍정의 말 — 설문 조사","correct":true},{"t":"우리 반 친구들의 수 — 인터넷 조사","mis":"K4-2-u2-X33"},{"t":"긍정 언어의 날을 연 학교 선생님의 생각 — 우리 반 친구들에게 설문 조사","mis":"K4-2-u2-X33"}],"explanation":["여러 친구의 생각을 세어 보려면 같은 질문지로 묻는 설문 조사가 알맞아요.","다른 학교 선생님의 생각은 우리 반에 물어서는 알 수 없어요.","조사할 내용에 맞는 방법을 골라야 해요."],"asset":{"type":"passage","lines":["○○초등학교에서 ‘긍정 언어의 날’을 도입해 주목받고 있다.","언어폭력의 심각성을 알리고 긍정적인 언어로 순화하여 말하는 데 초점을 둔다.","[표] 부정의 말 → 긍정의 말","말이 너무 많구나 → 표현을 다양하게 하는구나","쫀쫀하다 → 세심하다","왜 이렇게 겁이 많은 거야? → 조심성이 있구나.","출처: ○○○ 기자(20○○. ○○. ○○), 「긍정 언어의 날, 우리 함께 좋은 말 써요」, ○○일보."],"title":"‘긍정 언어’ 기사 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#8','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C41',4,'essay','teacher','『국어』 101쪽 4번이에요. 지후의 메모 ㉠, ㉢, ㉣에서 잘못된 점을 찾아 각각 바르게 고쳐 쓰고, 고쳐야 하는 까닭도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C41","difficulty":4,"kind":"essay","stem":"『국어』 101쪽 4번이에요. 지후의 메모 ㉠, ㉢, ㉣에서 잘못된 점을 찾아 각각 바르게 고쳐 쓰고, 고쳐야 하는 까닭도 쓰세요.","answer_guide":{"answer":"예: ㉠ 「열여덟 명이 줄임말을 자주 사용했다」라고 써야 한다. 설문 조사 결과를 왜곡하면 안 되기 때문이다. ㉢ 까닭 세 가지(짧아서 쓰기 편함, 습관이 됨, 다른 친구들이 많이 씀)를 모두 써야 한다. 조사 결과를 마음대로 줄이면 안 되기 때문이다. ㉣ 기자 이름, 기사 제목, 발행한 곳, 발행 일자를 분명하게 써야 한다. 그래야 읽는 사람이 자료를 확인할 수 있기 때문이다.","scoring_points":["㉠을 조사한 수대로 고쳤는가","㉢을 까닭 세 가지 모두 쓰도록 고쳤는가","㉣을 출처 네 가지가 드러나게 고치고 까닭을 썼는가"]},"explanation":["메모를 1번 글과 견주며 읽어요.","부풀리기, 줄이기, 출처 빠뜨리기를 찾아요.","고칠 때는 조사한 그대로, 출처는 분명하게 써요."],"asset":{"type":"passage","lines":["㉠ 줄임말을 자주 사용한다고 답한 친구는 열여덟 명이었지만","문제의 심각성을 알리려면 스무 명이라고 써야겠어.","㉡ 줄임말을 쓰는 상황에 대한 결과를 그래프로 나타내 한눈에 보기 쉽게 해야지.","㉢ 면담 결과, 친구들이 줄임말을 쓰는 까닭은 세 가지였지만","글을 쓸 때에는 두 가지만 써야겠다.","㉣ 뉴스 기사의 출처를 글에 쓸 때에는 간단하게 기사의 제목만 쓰면 되겠지?"],"title":"지후의 메모 — 『국어』 101쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#9','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C38',4,'essay','teacher','‘긍정 언어’ 기사를 읽고 보고하는 글을 쓰기 위한 조사 계획을 세우세요. 조사 주제, 조사할 내용 두 가지, 각 내용에 알맞은 조사 방법, 활용할 매체 자료를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C38","difficulty":4,"kind":"essay","stem":"‘긍정 언어’ 기사를 읽고 보고하는 글을 쓰기 위한 조사 계획을 세우세요. 조사 주제, 조사할 내용 두 가지, 각 내용에 알맞은 조사 방법, 활용할 매체 자료를 쓰세요.","answer_guide":{"answer":"예: 조사 주제 — 우리 반 친구들의 긍정 언어 사용. 조사할 내용 ① 친구들이 자주 듣는 부정의 말과 긍정의 말 — 설문 조사 — 막대그래프. ② 긍정의 말을 들었을 때 기분이 어떤지 — 면담 조사 — 면담 내용을 정리한 표.","scoring_points":["우리말 사용과 이어지는 조사 주제를 썼는가","조사할 내용마다 알맞은 조사 방법을 골랐는가","결과를 한눈에 보여 줄 매체 자료를 정했는가"]},"explanation":["기사에 나온 부정의 말과 긍정의 말을 떠올려요.","몇 명인지는 설문, 까닭과 느낌은 면담이 알맞아요.","표, 그래프, 사진 가운데 결과에 맞는 것을 골라요."],"asset":{"type":"passage","lines":["○○초등학교에서 ‘긍정 언어의 날’을 도입해 주목받고 있다.","언어폭력의 심각성을 알리고 긍정적인 언어로 순화하여 말하는 데 초점을 둔다.","[표] 부정의 말 → 긍정의 말","말이 너무 많구나 → 표현을 다양하게 하는구나","쫀쫀하다 → 세심하다","왜 이렇게 겁이 많은 거야? → 조심성이 있구나.","출처: ○○○ 기자(20○○. ○○. ○○), 「긍정 언어의 날, 우리 함께 좋은 말 써요」, ○○일보."],"title":"‘긍정 언어’ 기사 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L08_challenge#10','kor',4,2,'u2','L08','tb_g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C43',4,'mc','auto','보고하는 글에 조사한 사실과 자신의 생각을 어떻게 쓰는 것이 가장 알맞은가요?',ARRAY['K4-2-u2-X38','K4-2-u2-X39']::text[],false,'{"seq":10,"concept":"K4-2-u2-C43","difficulty":4,"kind":"mc","stem":"보고하는 글에 조사한 사실과 자신의 생각을 어떻게 쓰는 것이 가장 알맞은가요?","options":[{"t":"조사한 사실과 함께 결과에 대한 의견도 쓰되, 사실과 의견을 분명히 구별해 쓴다","correct":true},{"t":"보고하는 글에는 내 생각을 한 줄도 쓰면 안 된다","mis":"K4-2-u2-X38"},{"t":"사실과 생각을 섞어 조사한 내용 칸에 함께 쓴다","mis":"K4-2-u2-X39"}],"explanation":["사실만 늘어놓으면 왜 조사했는지가 잘 드러나지 않아요.","그래서 조사 소감에 결과에 대한 생각을 분명히 써요.","조사한 내용과 조사 소감은 칸을 나누어 사실과 의견을 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#1','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C44',1,'mc','auto','『국어』 102쪽이에요. 우리말 사용과 관련한 조사 주제로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u2-X07']::text[],false,'{"seq":1,"concept":"K4-2-u2-C44","difficulty":1,"kind":"mc","stem":"『국어』 102쪽이에요. 우리말 사용과 관련한 조사 주제로 알맞지 않은 것은 무엇인가요?","options":[{"t":"우리 동네 놀이터에 있는 그네의 수","correct":true},{"t":"지나친 외국어 사용","mis":"K4-2-u2-X07"},{"t":"비속어 사용","mis":"K4-2-u2-X07"},{"t":"줄임말 사용","mis":"K4-2-u2-X07"}],"explanation":["『국어』에는 지나친 외국어 사용, 비속어 사용, 줄임말 사용이 주제 예로 나와요.","이 주제들은 모두 우리말 사용과 이어져 있어요.","그네의 수는 우리말 사용과 상관없어요."],"asset":{"type":"passage","lines":["[그림] 부먹(부어 먹기) · 찍먹(찍어 먹기)","주제 예 — 지나친 외국어 사용 · 비속어 사용 · 줄임말 사용","“우리말 사용과 관련한 다양한 주제를 생각해 봐요.”","“주제를 정할 때에는 자신이 관심 있는 내용을 생각해 봐요.”","보기(조사 방법) — 설문 조사 · 면담 조사 · 인터넷 조사 · 방문 조사"],"title":"조사 주제와 조사 방법 정하기 — 『국어』 102쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#2','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C44',1,'mc','auto','보고하는 글의 조사 주제를 정할 때 가장 알맞은 주제는 무엇인가요?',ARRAY['K4-2-u2-X07']::text[],false,'{"seq":2,"concept":"K4-2-u2-C44","difficulty":1,"kind":"mc","stem":"보고하는 글의 조사 주제를 정할 때 가장 알맞은 주제는 무엇인가요?","options":[{"t":"내가 관심 있고 직접 자료를 모을 수 있는 주제","correct":true},{"t":"친구가 고른 주제를 그대로 따라 한 주제","mis":"K4-2-u2-X07"},{"t":"전 세계 사람들의 말버릇처럼 아주 큰 주제","mis":"K4-2-u2-X07"}],"explanation":["스스로 관심 있거나 평소에 궁금했던 내용을 골라요.","조사 대상의 자료를 실제로 모을 수 있어야 해요.","너무 큰 주제는 직접 조사하기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#3','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C47',1,'mc','auto','『국어』 104쪽 보고하는 글 틀에서 「조사 소감」에 쓸 내용은 무엇인가요?',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":3,"concept":"K4-2-u2-C47","difficulty":1,"kind":"mc","stem":"『국어』 104쪽 보고하는 글 틀에서 「조사 소감」에 쓸 내용은 무엇인가요?","options":[{"t":"조사하고 나서 든 생각이나 다짐","correct":true},{"t":"조사한 사람의 수와 조사한 기간","mis":"K4-2-u2-X44"},{"t":"참고한 기사의 제목과 날짜","mis":"K4-2-u2-X44"}],"explanation":["조사 대상과 기간은 글의 처음에 써요.","기사의 제목과 날짜는 참고 자료와 그 출처에 써요.","조사 소감에는 조사를 마치고 든 생각을 써요."],"asset":{"type":"passage","lines":["제목","조사 대상 · 조사 기간 · 조사 동기 · 조사 방법","조사한 내용","조사 소감","참고 자료와 그 출처"],"title":"보고하는 글 쓰기 틀 — 『국어』 104쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#4','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C47',1,'sa','auto','『국어』 104쪽 보고하는 글 틀의 마지막 칸은 「참고 자료와 그 (     )」예요. 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u2-C47","difficulty":1,"kind":"sa","stem":"『국어』 104쪽 보고하는 글 틀의 마지막 칸은 「참고 자료와 그 (     )」예요. 빈칸에 알맞은 낱말을 쓰세요.","answer":["출처"],"explanation":["참고한 자료가 어디에서 나왔는지 밝히는 칸이에요.","그 칸의 이름은 「참고 자료와 그 출처」예요.","출처를 밝혀야 읽는 사람이 자료를 확인할 수 있어요."],"mis":"K4-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#5','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C46',2,'mc','auto','지후의 설문 조사 결과 「20명 가운데 열여덟 명이 줄임말을 자주 사용했다.」를 보고하는 글에 옮겼어요. 바르게 옮긴 것은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X56','K4-2-u2-X40']::text[],false,'{"seq":5,"concept":"K4-2-u2-C46","difficulty":2,"kind":"mc","stem":"지후의 설문 조사 결과 「20명 가운데 열여덟 명이 줄임말을 자주 사용했다.」를 보고하는 글에 옮겼어요. 바르게 옮긴 것은 무엇인가요?","options":[{"t":"20명 가운데 열여덟 명이 줄임말을 자주 사용했다.","correct":true},{"t":"우리 반 친구 모두가 줄임말을 자주 사용했다.","mis":"K4-2-u2-X35"},{"t":"줄임말을 자주 쓰는 친구는 몇 명뿐이었다.","mis":"K4-2-u2-X56"},{"t":"줄임말을 자주 쓰지 않는 친구가 열여덟 명이었다.","mis":"K4-2-u2-X40"}],"explanation":["조사한 내용은 과장하거나 줄이지 않아요.","열여덟 명을 「모두」라고 하면 부풀린 것이고, 「몇 명뿐」이라고 하면 줄인 것이에요.","자주 쓰는 친구를 쓰지 않는 친구로 바꾸어도 안 돼요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#6','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C45',2,'mc','auto','설문 조사 질문으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X42']::text[],false,'{"seq":6,"concept":"K4-2-u2-C45","difficulty":2,"kind":"mc","stem":"설문 조사 질문으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「하루에 줄임말을 몇 번쯤 쓰나요?」","correct":true},{"t":"「줄임말과 비속어를 자주 쓰고 좋아하나요?」","mis":"K4-2-u2-X42"},{"t":"「줄임말은 나쁜 말이니 쓰지 않는 게 좋겠지요?」","mis":"K4-2-u2-X42"}],"explanation":["설문 질문은 하나의 질문에 하나의 답만 나오게 만들어요.","두 가지를 한꺼번에 물으면 무엇에 답했는지 알 수 없어요.","답을 한쪽으로 몰아가는 질문도 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#7','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C38',2,'mc','auto','「우리 반 친구들 가운데 몇 명이 줄임말을 쓰는지」 알아보려고 해요. 알맞은 조사 방법은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":7,"concept":"K4-2-u2-C38","difficulty":2,"kind":"mc","stem":"「우리 반 친구들 가운데 몇 명이 줄임말을 쓰는지」 알아보려고 해요. 알맞은 조사 방법은 무엇인가요?","options":[{"t":"설문 조사","correct":true},{"t":"면담 조사","mis":"K4-2-u2-X33"},{"t":"방문 조사","mis":"K4-2-u2-X33"}],"explanation":["몇 명인지는 여러 사람에게 같은 질문을 해서 세어 보아야 해요.","설문 조사가 알맞아요.","정한 조사 방법이 적절한지 친구들과도 이야기해 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#8','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C48',2,'mc','auto','『국어』 105쪽 점검하기예요. 친구의 보고하는 글을 읽고 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X41','K4-2-u2-X37']::text[],false,'{"seq":8,"concept":"K4-2-u2-C48","difficulty":2,"kind":"mc","stem":"『국어』 105쪽 점검하기예요. 친구의 보고하는 글을 읽고 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"내용을 어떤 방법으로 조사했는지 정확하게 밝혀 주면 좋겠어.","correct":true},{"t":"조사하지 않은 내용도 지어 넣어서 길게 쓰면 좋겠어.","mis":"K4-2-u2-X41"},{"t":"참고한 자료의 출처는 빼도 괜찮아.","mis":"K4-2-u2-X37"}],"explanation":["친구들은 사실에 근거해, 형식과 주제를 고려해, 출처를 밝혀 쓰라고 했어요.","조사한 방법을 정확히 밝히면 믿을 수 있는 글이 돼요.","지어 넣거나 출처를 빼면 쓰기 윤리를 지키지 않은 거예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"조사한 내용을 과장하지 않고 사실에 근거해 써야 해."},{"who":"친구 2","text":"보고하는 글의 형식과 주제를 고려해 써야 해."},{"who":"친구 3","text":"참고한 자료가 있으면 출처를 밝혀 줘야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#9','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C48',2,'ox','auto','보고하는 글은 길수록 좋으니 조사 주제와 상관없는 내용도 많이 넣어요.',ARRAY['K4-2-u2-X59']::text[],false,'{"seq":9,"concept":"K4-2-u2-C48","difficulty":2,"kind":"ox","stem":"보고하는 글은 길수록 좋으니 조사 주제와 상관없는 내용도 많이 넣어요.","answer":"X","reason_options":[{"t":"보고하는 글의 특성을 고려해 필요하지 않은 내용은 빼요.","correct":true},{"t":"내용이 많을수록 믿을 수 있는 글이에요.","mis":"K4-2-u2-X59"}],"mis":"K4-2-u2-X59","explanation":["좋은 보고하는 글은 긴 글이 아니라 믿을 수 있는 글이에요.","주제와 상관없는 내용은 읽는 사람을 헷갈리게 해요.","고쳐 쓸 때 필요하지 않은 내용은 삭제해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_basic#10','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C47',3,'error','auto','보고하는 글의 처음·가운데·끝에 들어갈 내용을 정리했어요. 잘못 넣은 것은 무엇인가요?',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":10,"concept":"K4-2-u2-C47","difficulty":3,"kind":"error","stem":"보고하는 글의 처음·가운데·끝에 들어갈 내용을 정리했어요. 잘못 넣은 것은 무엇인가요?","options":[{"t":"끝 — 설문 조사 결과를 나타낸 그래프","correct":true,"mis_target":"K4-2-u2-X44"},{"t":"처음 — 제목, 조사 대상, 조사 기간, 조사 동기, 조사 방법","mis":"K4-2-u2-X44"},{"t":"끝 — 조사 소감, 참고 자료와 그 출처","mis":"K4-2-u2-X44"}],"explanation":["처음에는 조사의 과정을 알려 주는 내용을 써요.","가운데에는 조사한 내용과 그래프 같은 매체 자료를 써요.","끝에는 조사 소감과 참고 자료와 그 출처를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#1','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C42',2,'mc','auto','보고하는 글을 쓰려고 자료를 모아요. 모아야 할 자료로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X37','K4-2-u2-X59']::text[],false,'{"seq":1,"concept":"K4-2-u2-C42","difficulty":2,"kind":"mc","stem":"보고하는 글을 쓰려고 자료를 모아요. 모아야 할 자료로 알맞은 것은 무엇인가요?","options":[{"t":"조사 주제와 관련 있고 출처가 분명한 자료","correct":true},{"t":"출처는 몰라도 내용이 재미있는 자료","mis":"K4-2-u2-X37"},{"t":"주제와 상관없어도 그림이 많은 자료","mis":"K4-2-u2-X59"}],"explanation":["자료는 조사 주제와 관련 있는 것으로 모아요.","틀린 점은 없는지, 출처가 분명한지 살펴요.","그래야 신뢰할 수 있는 정확한 자료가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#2','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C47',2,'mc','auto','『국어』 104쪽 보고하는 글 틀의 「조사한 내용」 칸에 쓸 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":2,"concept":"K4-2-u2-C47","difficulty":2,"kind":"mc","stem":"『국어』 104쪽 보고하는 글 틀의 「조사한 내용」 칸에 쓸 것으로 알맞은 것은 무엇인가요?","options":[{"t":"조사 방법별로 알아낸 사실과 매체 자료","correct":true},{"t":"조사를 마치고 느낀 점","mis":"K4-2-u2-X44"},{"t":"조사를 하게 된 까닭","mis":"K4-2-u2-X44"}],"explanation":["지후의 글에서도 조사한 내용에 설문·면담·인터넷 결과를 차례로 썼어요.","그래프 같은 매체 자료도 함께 넣었어요.","느낀 점은 조사 소감, 까닭은 조사 동기에 써요."],"asset":{"type":"passage","lines":["제목","조사 대상 · 조사 기간 · 조사 동기 · 조사 방법","조사한 내용","조사 소감","참고 자료와 그 출처"],"title":"보고하는 글 쓰기 틀 — 『국어』 104쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#3','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C46',3,'mc','auto','『국어』 98쪽 지후가 친구들을 면담한 결과를 바르게 간추린 것은 무엇인가요?',ARRAY['K4-2-u2-X56','K4-2-u2-X40','K4-2-u2-X41']::text[],false,'{"seq":3,"concept":"K4-2-u2-C46","difficulty":3,"kind":"mc","stem":"『국어』 98쪽 지후가 친구들을 면담한 결과를 바르게 간추린 것은 무엇인가요?","options":[{"t":"친구들은 짧아서 쓰기 편하고, 습관이 되었고, 다른 친구들이 많이 사용해서 줄임말을 쓴다고 했다.","correct":true},{"t":"친구들은 짧아서 쓰기 편하다는 까닭 하나만 말했다.","mis":"K4-2-u2-X56"},{"t":"친구들은 맞춤법 실력을 키우려고 줄임말을 쓴다고 했다.","mis":"K4-2-u2-X40"},{"t":"친구들은 멋있어 보이려고 줄임말을 쓴다고도 했다.","mis":"K4-2-u2-X41"}],"explanation":["면담 결과 친구들이 말한 까닭은 세 가지예요.","하나만 쓰면 줄인 것이고, 듣지 않은 까닭을 넣으면 지어낸 것이에요.","맞춤법 이야기는 인터넷 조사로 안 문제점이에요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#4','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C48',3,'mc','auto','지후는 「조사한 내용」의 문장을 「설문 조사 결과,」, 「친구들을 면담한 결과,」, 「인터넷 뉴스 기사에서 조사해 보니」로 시작했어요. 이렇게 쓴 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X41','K4-2-u2-X31']::text[],false,'{"seq":4,"concept":"K4-2-u2-C48","difficulty":3,"kind":"mc","stem":"지후는 「조사한 내용」의 문장을 「설문 조사 결과,」, 「친구들을 면담한 결과,」, 「인터넷 뉴스 기사에서 조사해 보니」로 시작했어요. 이렇게 쓴 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 방법으로 조사해 알아낸 내용인지 정확하게 밝히려고","correct":true},{"t":"글이 더 길어 보이게 하려고","mis":"K4-2-u2-X41"},{"t":"조사 방법을 많이 쓸수록 좋은 글이라서","mis":"K4-2-u2-X31"}],"explanation":["『국어』 105쪽 친구 의견처럼 내용을 어떤 방법으로 조사했는지 밝혀야 해요.","그러면 읽는 사람이 조사 과정을 알 수 있어 믿을 수 있는 글이 돼요.","방법의 개수나 글의 길이가 중요한 것이 아니에요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#5','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C48',3,'mc','auto','『국어』 105쪽 「스스로 확인하기」에 있는 물음이 아닌 것은 무엇인가요?',ARRAY['K4-2-u2-X41']::text[],false,'{"seq":5,"concept":"K4-2-u2-C48","difficulty":3,"kind":"mc","stem":"『국어』 105쪽 「스스로 확인하기」에 있는 물음이 아닌 것은 무엇인가요?","options":[{"t":"글을 다른 친구보다 길게 썼나요?","correct":true},{"t":"보고하는 글의 주제에 맞게 썼나요?","mis":"K4-2-u2-X41"},{"t":"조사한 내용을 사실에 근거해 썼나요?","mis":"K4-2-u2-X41"},{"t":"참고 자료와 그 출처를 밝혔나요?","mis":"K4-2-u2-X41"}],"explanation":["스스로 확인하기에는 주제, 사실, 매체 자료, 출처 — 네 물음이 있어요.","글의 길이를 친구와 견주는 물음은 없어요.","좋은 보고하는 글은 믿을 수 있는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#6','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C42',3,'ox','auto','인터넷에서 찾은 다른 사람의 보고서가 좋아 보이면 이름만 바꾸어 내도 돼요.',ARRAY['K4-2-u2-X37']::text[],false,'{"seq":6,"concept":"K4-2-u2-C42","difficulty":3,"kind":"ox","stem":"인터넷에서 찾은 다른 사람의 보고서가 좋아 보이면 이름만 바꾸어 내도 돼요.","answer":"X","reason_options":[{"t":"다른 사람의 글은 힘들게 만든 결과물이라 그대로 가져다 쓰면 훔치는 것과 같아요.","correct":true},{"t":"좋은 글은 누구 것이든 자기 이름으로 내도 돼요.","mis":"K4-2-u2-X37"}],"mis":"K4-2-u2-X37","explanation":["『국어활동』 25쪽 만화의 친구들도 「안 돼.」라고 말렸어요.","꼭 필요한 자료라면 참고하고 반드시 출처를 밝혀요.","출처 없이 가져다 쓰면 표절이 돼요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어? 인터넷에 초등학생이 쓰는 외국어에 대한 보고서가 있어! 이름만 바꿔서 내자."},{"who":"친구 2","text":"안 돼. ……"},{"who":"친구 3","text":"맞아. 꼭 필요한 자료면 참고하고, 반드시 자료의 출처를 밝혀야 해."},{"who":"친구 1","text":"하하, 미안해. 편하게 하려는 생각에 나도 모르게 그만……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#7','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C48',3,'match','auto','친구들이 보고하는 글을 바꾸어 읽고 의견을 말했어요. 의견과 고쳐 쓸 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u2-C48","difficulty":3,"kind":"match","stem":"친구들이 보고하는 글을 바꾸어 읽고 의견을 말했어요. 의견과 고쳐 쓸 점을 알맞게 이으세요.","pairs":[{"l":"「설문 결과는 열여덟 명인데 ‘스무 명’이라고 썼어.」","r":"조사한 수를 그대로 밝혀 쓴다."},{"l":"「인터넷 자료를 어디서 가져왔는지 없어.」","r":"참고 자료와 그 출처를 밝힌다."},{"l":"「결과를 글로만 길게 늘어놓아 한눈에 안 보여.」","r":"표나 그래프 같은 매체 자료를 활용한다."}],"mis":"K4-2-u2-X35","explanation":["부풀린 낱말은 조사한 수로 고쳐요.","옮겨 온 자료에는 출처를 밝혀요.","결과는 표나 그래프로 나타내면 한눈에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#8','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C47',4,'essay','teacher','『국어활동』 24쪽 친구들처럼 「초등학생이 많이 쓰는 외국어」를 조사해 공모전에 보고하는 글을 내려고 해요. 보고하는 글의 처음에 쓸 제목, 조사 대상, 조사 동기, 조사 방법을 계획해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C47","difficulty":4,"kind":"essay","stem":"『국어활동』 24쪽 친구들처럼 「초등학생이 많이 쓰는 외국어」를 조사해 공모전에 보고하는 글을 내려고 해요. 보고하는 글의 처음에 쓸 제목, 조사 대상, 조사 동기, 조사 방법을 계획해 쓰세요.","answer_guide":{"answer":"예: 제목 — 우리 반 친구들이 많이 쓰는 외국어. 조사 대상 — 4학년 ○반 학생. 조사 동기 — ‘우리말 사용에 대한 보고하는 글 쓰기’ 공모전을 보고, 친구들이 우리말로 바꿀 수 있는 외국어를 얼마나 쓰는지 알고 싶었다. 조사 방법 — 우리 반 친구들에게 자주 쓰는 외국어를 묻는 설문 조사, 지나친 외국어 사용의 부정적인 면을 찾는 인터넷 조사.","scoring_points":["조사 주제가 드러나는 제목과 조사 대상을 썼는가","조사 동기가 우리말 사용과 이어지는가","알아낼 내용에 맞는 조사 방법을 골랐는가"]},"explanation":["『국어활동』 24쪽 친구들은 인터넷 조사와 설문 조사를 하자고 했어요.","처음에는 조사의 과정을 알려 주는 내용을 써요.","몇 명이 쓰는지는 설문, 문제점은 인터넷 조사가 알맞아요."],"asset":{"type":"speech","turns":[{"who":"세나","text":"얘들아, 이것 봐. ‘우리말 사용에 대한 보고하는 글 쓰기’ 공모전을 한대."},{"who":"도윤","text":"‘보고하는 글’이 뭐야?"},{"who":"세나","text":"어떤 주제에 대해 관찰, 조사, 실험한 과정과 결과를 체계적으로 정리한 글이야."},{"who":"하린","text":"초등학생이 많이 쓰는 외국어를 조사해 보면 어때?"},{"who":"도윤","text":"좋은 생각이야. 인터넷 조사도 해 보고 직접 설문 조사도 해 보자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#9','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C48',4,'essay','teacher','『국어활동』 25쪽 만화처럼 인터넷에서 찾은 보고서를 이름만 바꾸어 내려는 친구에게, 왜 안 되는지와 그 자료를 바르게 쓰는 방법을 『국어』 105쪽 점검 물음(주제·사실·매체 자료·출처)과 이어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C48","difficulty":4,"kind":"essay","stem":"『국어활동』 25쪽 만화처럼 인터넷에서 찾은 보고서를 이름만 바꾸어 내려는 친구에게, 왜 안 되는지와 그 자료를 바르게 쓰는 방법을 『국어』 105쪽 점검 물음(주제·사실·매체 자료·출처)과 이어 쓰세요.","answer_guide":{"answer":"예: 다른 사람의 보고서는 그 사람이 힘들게 조사하고 쓴 결과물이라 이름만 바꾸어 내면 물건을 훔치는 것과 같아. 우리가 직접 조사한 내용을 사실에 근거해 쓰고, 그 보고서에서 꼭 필요한 부분만 참고한다면 참고 자료와 그 출처를 밝혀야 해. 그래야 「참고 자료와 그 출처를 밝혔나요?」에도 ●●●을 줄 수 있어.","scoring_points":["이름만 바꾸어 내면 안 되는 까닭을 썼는가","직접 조사해 사실에 근거해 쓰고 필요한 자료만 참고한다고 썼는가","출처를 밝히는 방법을 점검 물음과 이어 썼는가"]},"explanation":["『국어활동』 25쪽 친구도 「안 돼.」라고 말렸어요.","다른 사람의 글을 그대로 쓰면 표절이에요.","참고했다면 반드시 출처를 밝혀요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어? 인터넷에 초등학생이 쓰는 외국어에 대한 보고서가 있어! 이름만 바꿔서 내자."},{"who":"친구 2","text":"안 돼. ……"},{"who":"친구 3","text":"맞아. 꼭 필요한 자료면 참고하고, 반드시 자료의 출처를 밝혀야 해."},{"who":"친구 1","text":"하하, 미안해. 편하게 하려는 생각에 나도 모르게 그만……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L10_challenge#10','kor',4,2,'u2','L10','tb_g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C40',4,'mc','auto','지후의 조사 계획에서 「친구들이 줄임말을 사용하는 상황」에만 그래프를 활용할 매체 자료로 정했어요. 그 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X43','K4-2-u2-X35']::text[],false,'{"seq":10,"concept":"K4-2-u2-C40","difficulty":4,"kind":"mc","stem":"지후의 조사 계획에서 「친구들이 줄임말을 사용하는 상황」에만 그래프를 활용할 매체 자료로 정했어요. 그 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"상황마다 몇 명인지 수를 견주어 한눈에 보여 줄 수 있어서","correct":true},{"t":"그래프는 글을 예쁘게 꾸미는 것이라서","mis":"K4-2-u2-X43"},{"t":"막대를 더 길게 그리면 결과를 크게 보이게 할 수 있어서","mis":"K4-2-u2-X35"},{"t":"조사한 내용에는 모두 그래프를 넣어야 해서","mis":"K4-2-u2-X43"}],"explanation":["설문 조사로 상황마다 몇 명이 줄임말을 쓰는지 세었어요.","수를 견주는 내용은 그래프로 보면 한눈에 알 수 있어요.","까닭이나 문제점은 그래프보다 글로 쓰는 것이 알맞아요."],"asset":{"type":"passage","lines":["조사 대상 — 4학년 ○반 학생 20명","조사할 내용 ㉠ 친구들이 줄임말을 사용하는 상황 — 매체 자료: 그래프","조사할 내용 ㉡ 친구들이 줄임말을 사용하는 까닭","조사할 내용 ㉢ 줄임말을 사용할 때의 특징과 문제점","보기(조사 방법): 설문 조사 · 면담 조사 · 인터넷 조사"],"title":"지후의 조사 계획 — 『국어』 99쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#1','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C49',1,'mc','auto','『국어』 106쪽 「한: 한없이 아름다운 우리말 / 글: 글자로 빛나는 조상의 지혜」는 어떤 방법으로 쓴 시인가요?',ARRAY['K4-2-u2-X45','K4-2-u2-X58']::text[],false,'{"seq":1,"concept":"K4-2-u2-C49","difficulty":1,"kind":"mc","stem":"『국어』 106쪽 「한: 한없이 아름다운 우리말 / 글: 글자로 빛나는 조상의 지혜」는 어떤 방법으로 쓴 시인가요?","options":[{"t":"주제어의 첫 글자로 행을 시작하는 2행시","correct":true},{"t":"행을 많이 늘려 쓴 긴 시","mis":"K4-2-u2-X45"},{"t":"주제어와 상관없는 글자로 행을 시작한 시","mis":"K4-2-u2-X58"}],"explanation":["주제어는 「한글」이에요.","첫 행은 「한」, 둘째 행은 「글」로 시작했어요.","주제어의 첫 글자로 시작하는 2행시, 3행시를 쓸 수 있어요."],"asset":{"type":"passage","lines":["주제 — 한글 · 훈민정음 · 우리글 · 한글날 · 세종 대왕 · 주시경 · 헐버트","한: 한없이 아름다운 우리말","글: 글자로 빛나는 조상의 지혜","「주시경」 — 우리글을 사랑한 주시경! / 한글 꽃을 가꾼 분 /","우리 글자 예쁘게 피었어요."],"title":"한글 사랑 시 쓰기 — 『국어』 106쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#2','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C52',1,'sa','auto','「선생님께서 여덟 가지 색깔을 사용하라고 하셨지?」에서 ‘여덟’은 어떻게 발음하나요? 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u2-C52","difficulty":1,"kind":"sa","stem":"「선생님께서 여덟 가지 색깔을 사용하라고 하셨지?」에서 ‘여덟’은 어떻게 발음하나요? 소리 나는 대로 쓰세요.","answer":["여덜","[여덜]"],"explanation":["‘여덟’은 ㄼ 받침이에요.","여기서 ㄼ은 [ㄹ]로 소리 나요.","그래서 [여덥]이 아니라 [여덜]로 발음해요."],"mis":"K4-2-u2-X48"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#3','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C55',1,'mc','auto','『국어』 110쪽이에요. 「이 옷의 컬러가 내 마음에 쏙 들어.」에서 ‘컬러’를 순우리말로 바꾼 말은 무엇인가요?',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":3,"concept":"K4-2-u2-C55","difficulty":1,"kind":"mc","stem":"『국어』 110쪽이에요. 「이 옷의 컬러가 내 마음에 쏙 들어.」에서 ‘컬러’를 순우리말로 바꾼 말은 무엇인가요?","options":[{"t":"색깔","correct":true},{"t":"모양","mis":"K4-2-u2-X19"},{"t":"무늬","mis":"K4-2-u2-X19"}],"explanation":["‘컬러’는 외국어예요.","빛깔이나 색을 뜻하니 ‘색깔’로 바꿀 수 있어요.","우리말로 쓸 수 있는 말은 우리말로 써요."],"asset":{"type":"passage","lines":["이 옷의 컬러가 내 마음에 쏙 들어.  (색깔 / 모양)","줄넘기를 잘하기 위한 팁을 말해 줄게.  (본보기 / 도움말)"],"title":"밑줄 그은 낱말을 순우리말로 — 『국어』 110쪽","hi":["컬러","팁"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#4','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C56',1,'mc','auto','『국어』 111쪽 글씨 쓰기 낱말이에요. 겹받침을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u2-X15','K4-2-u2-X49']::text[],false,'{"seq":4,"concept":"K4-2-u2-C56","difficulty":1,"kind":"mc","stem":"『국어』 111쪽 글씨 쓰기 낱말이에요. 겹받침을 바르게 쓴 것은 무엇인가요?","options":[{"t":"앉은키","correct":true},{"t":"안즌키","mis":"K4-2-u2-X15"},{"t":"않은키","mis":"K4-2-u2-X49"}],"explanation":["앉아 있을 때의 키라서 ‘앉다’의 ㄵ 받침을 그대로 써요.","소리 나는 대로 ‘안즌키’라고 적지 않아요.","ㄶ 받침인 ‘않’과 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#5','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C52',2,'mc','auto','「찰흙을 좀 더 얇게 펴는 게 좋아.」에서 ‘얇게’의 바른 발음은 무엇인가요?',ARRAY['K4-2-u2-X48','K4-2-u2-X13']::text[],false,'{"seq":5,"concept":"K4-2-u2-C52","difficulty":2,"kind":"mc","stem":"「찰흙을 좀 더 얇게 펴는 게 좋아.」에서 ‘얇게’의 바른 발음은 무엇인가요?","options":[{"t":"[얄께]","correct":true},{"t":"[얍께]","mis":"K4-2-u2-X48"},{"t":"[얇게]","mis":"K4-2-u2-X13"}],"explanation":["‘얇게’의 ㄼ은 [ㄹ]로 소리 나요.","뒤의 ㄱ은 된소리 [ㄲ]으로 나요.","그래서 [얄께]로 발음해요."],"asset":{"type":"passage","lines":["㉮ “컵을 만들려면 찰흙을 좀 더 얇게 펴는 게 좋아.” — [얍께]?","㉮ “선생님께서 여덟 가지 색깔을 사용하라고 하셨지?” — [여덥]?","㉯ “누나, 그거 내 새 가방인데 가방끈이 짧고 가벼워서 아주 편하더라.” — [짭꼬]?","㉯ “공간이 넓지 않으니까 가방을 책상 옆에 잘 두자.” — [넙찌]?"],"title":"파란색 낱말의 발음 — 『국어』 110쪽","hi":["얇게","여덟","짧고","넓지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#6','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C52',2,'match','auto','『국어』 110쪽 파란색 낱말과 바른 발음을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u2-C52","difficulty":2,"kind":"match","stem":"『국어』 110쪽 파란색 낱말과 바른 발음을 이으세요.","pairs":[{"l":"짧고","r":"[짤꼬]"},{"l":"넓지","r":"[널찌]"},{"l":"얇게","r":"[얄께]"}],"mis":"K4-2-u2-X48","explanation":["‘얇게, 여덟, 짧고, 넓지’의 ㄼ은 [ㄹ]로 소리 나요.","[짭꼬], [넙찌], [얍께]는 바르지 않은 발음이에요.","바른 발음을 여러 번 소리 내어 익숙해지게 해요."],"asset":{"type":"passage","lines":["㉮ “컵을 만들려면 찰흙을 좀 더 얇게 펴는 게 좋아.” — [얍께]?","㉮ “선생님께서 여덟 가지 색깔을 사용하라고 하셨지?” — [여덥]?","㉯ “누나, 그거 내 새 가방인데 가방끈이 짧고 가벼워서 아주 편하더라.” — [짭꼬]?","㉯ “공간이 넓지 않으니까 가방을 책상 옆에 잘 두자.” — [넙찌]?"],"title":"파란색 낱말의 발음 — 『국어』 110쪽","hi":["얇게","여덟","짧고","넓지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#7','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C50',2,'mc','auto','『국어』 107쪽 우리 동네 간판 조사 계획에서 조사 동기로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X50']::text[],false,'{"seq":7,"concept":"K4-2-u2-C50","difficulty":2,"kind":"mc","stem":"『국어』 107쪽 우리 동네 간판 조사 계획에서 조사 동기로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 동네 간판에 우리말로 바꿀 수 있는 외국어가 얼마나 쓰였는지 알고 싶어서","correct":true},{"t":"우리 동네에서 가장 맛있는 가게를 찾고 싶어서","mis":"K4-2-u2-X50"},{"t":"간판 색깔이 가장 예쁜 가게를 고르고 싶어서","mis":"K4-2-u2-X50"}],"explanation":["이 조사는 우리말 사용을 알아보는 조사예요.","조사 동기는 우리말 사용과 이어져야 해요.","맛이나 색깔은 우리말 사용과 상관없어요."],"asset":{"type":"passage","lines":["① 우리 동네 간판을 조사할 계획 세우기 — 조사 대상 · 조사 기간 · 조사 동기 · 조사 방법","② 우리 동네 간판을 조사한 내용 정리하기","우리말로 바꿀 수 있는데도 외국어를 쓴 간판과 우리말을 쓴 간판을 조사한다.","직접 다니며 사진을 찍거나 기록하고, 인터넷 지도를 활용할 수도 있다."],"title":"우리 동네 간판 조사하기 — 『국어』 107쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#8','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C51',2,'mc','auto','우리 동네 간판을 조사한 내용을 정리할 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u2-X46']::text[],false,'{"seq":8,"concept":"K4-2-u2-C51","difficulty":2,"kind":"mc","stem":"우리 동네 간판을 조사한 내용을 정리할 때 알맞은 방법은 무엇인가요?","options":[{"t":"간판 이름을 우리말을 쓴 것과 우리말로 바꿀 수 있는데 외국어를 쓴 것으로 나눈다","correct":true},{"t":"외국어 간판을 단 가게는 나쁜 가게라고 적는다","mis":"K4-2-u2-X46"},{"t":"간판 글씨의 크기대로 줄을 세운다","mis":"K4-2-u2-X46"}],"explanation":["살펴보는 것은 가게가 아니라 간판에 쓰인 말이에요.","조사한 그대로 우리말 간판과 외국어 간판으로 나누어요.","외국어 이름이라고 나쁜 가게인 것은 아니에요."],"asset":{"type":"passage","lines":["① 우리 동네 간판을 조사할 계획 세우기 — 조사 대상 · 조사 기간 · 조사 동기 · 조사 방법","② 우리 동네 간판을 조사한 내용 정리하기","우리말로 바꿀 수 있는데도 외국어를 쓴 간판과 우리말을 쓴 간판을 조사한다.","직접 다니며 사진을 찍거나 기록하고, 인터넷 지도를 활용할 수도 있다."],"title":"우리 동네 간판 조사하기 — 『국어』 107쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#9','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C30',2,'mc','auto','우리말로 동아리 이름 짓기 예시에서 JUMP 동아리원의 말에 대한 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X25','K4-2-u2-X22']::text[],false,'{"seq":9,"concept":"K4-2-u2-C30","difficulty":2,"kind":"mc","stem":"우리말로 동아리 이름 짓기 예시에서 JUMP 동아리원의 말에 대한 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이름만 보고 무엇을 하는 동아리인지 알기 어려우니 특성이 드러나는 우리말 이름이 좋겠다","correct":true},{"t":"외국어 이름일수록 멋지니 다른 동아리도 모두 외국어로 바꾸면 좋겠다","mis":"K4-2-u2-X25"},{"t":"외국어 이름을 쓴 동아리는 없애야 한다","mis":"K4-2-u2-X22"}],"explanation":["‘JUMP(점프)’가 농구 동아리라는 것은 이름만 보고 알기 어려워요.","동아리 이름은 동아리의 특성을 알기 쉽게 나타내는 방법이에요.","순우리말로 특성이 잘 드러나는 이름을 지어 볼 수 있어요."],"asset":{"type":"passage","lines":["○○초등학교의 동아리 이름 ‘JUMP(점프)’, ‘그린 라이프’, ‘리듬 킹’은","각각 농구 동아리, 환경 동아리, 춤 동아리를 가리킨다.","이름만 보면 무엇을 하는 동아리인지 알기 어려운 경우가 많다.","JUMP 동아리원: “한글 이름보다는 이 이름이 더 멋있어서 지었어요.”","동아리의 이름은 동아리의 특성을 알기 쉽게 나타내는 방법이다."],"title":"우리말로 동아리 이름 짓기 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_basic#10','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C16',3,'mc','auto','한글 사랑 말판 놀이에서 친구가 「한글은 소리와 글자가 규칙적으로 연결돼요. (○, ×)」 칸에 멈춰 ×라고 답했어요. 놀이 규칙대로라면 어떻게 되나요?',ARRAY['K4-2-u2-X14','K4-2-u2-X18']::text[],false,'{"seq":10,"concept":"K4-2-u2-C16","difficulty":3,"kind":"mc","stem":"한글 사랑 말판 놀이에서 친구가 「한글은 소리와 글자가 규칙적으로 연결돼요. (○, ×)」 칸에 멈춰 ×라고 답했어요. 놀이 규칙대로라면 어떻게 되나요?","options":[{"t":"답이 틀렸으니 이전 자리로 되돌아간다","correct":true},{"t":"답을 맞혔으니 그 자리에 머문다","mis":"K4-2-u2-X14"},{"t":"문제 칸이라 앞으로 3칸 간다","mis":"K4-2-u2-X18"}],"explanation":["한글은 하나의 글자로 하나의 소리를 나타내고, 비슷한 소리는 비슷한 모양이에요.","그래서 정답은 ○예요.","규칙 ③에 따라 틀리면 이전 자리로 돌아가요."],"asset":{"type":"passage","lines":["① 지우개나 작은 물건으로 자신의 말을 정한다.","② 주사위 숫자가 나온 만큼 자신의 말을 옮긴다.","③ 문제를 해결하면 그 자리에 머물고, 틀리거나 답을 못 하면 이전 자리로 돌아간다.","④ 한 바퀴를 돌아 ‘도착’까지 먼저 오면 이긴다.","[칸 예] ‘ㅣ’는 무슨 모양을 본떠 만들었나요? / 한글의 옛 이름은 무엇인가요?","[칸 예] 헐버트는 왜 한글로 『사민필지』를 썼나요?"],"title":"한글 사랑 말판 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#1','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C49',2,'mc','auto','주제어 「한글날」로 3행시를 쓰려고 해요. 각 행을 시작하는 글자의 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X58']::text[],false,'{"seq":1,"concept":"K4-2-u2-C49","difficulty":2,"kind":"mc","stem":"주제어 「한글날」로 3행시를 쓰려고 해요. 각 행을 시작하는 글자의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"한 — 글 — 날","correct":true},{"t":"날 — 글 — 한","mis":"K4-2-u2-X58"},{"t":"한 — 날 — 글","mis":"K4-2-u2-X58"}],"explanation":["몇 행시는 주제어의 글자를 차례대로 각 행의 첫 글자로 써요.","「한글날」이면 한, 글, 날 차례예요.","예: 한 — 한결같이 / 글 — 글자를 아끼는 / 날 — 날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#2','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C55',2,'sa','auto','『국어』 110쪽이에요. 「줄넘기를 잘하기 위한 팁을 말해 줄게.」에서 ‘팁’을 순우리말로 바꾼 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u2-C55","difficulty":2,"kind":"sa","stem":"『국어』 110쪽이에요. 「줄넘기를 잘하기 위한 팁을 말해 줄게.」에서 ‘팁’을 순우리말로 바꾼 말을 쓰세요.","answer":["도움말"],"explanation":["‘팁’은 도움이 되는 말을 뜻하는 외국어예요.","순우리말로 ‘도움말’이라고 바꿀 수 있어요.","‘본보기’는 본을 보이는 것이라 뜻이 달라요."],"asset":{"type":"passage","lines":["이 옷의 컬러가 내 마음에 쏙 들어.  (색깔 / 모양)","줄넘기를 잘하기 위한 팁을 말해 줄게.  (본보기 / 도움말)"],"title":"밑줄 그은 낱말을 순우리말로 — 『국어』 110쪽","hi":["컬러","팁"]},"mis":"K4-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#3','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C52',3,'blank','auto','「‘얇게, 여덟, 짧고, 넓지’의 ‘ㄼ’은 (     )로 소리 나요.」 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X48']::text[],false,'{"seq":3,"concept":"K4-2-u2-C52","difficulty":3,"kind":"blank","stem":"「‘얇게, 여덟, 짧고, 넓지’의 ‘ㄼ’은 (     )로 소리 나요.」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"[ㄹ]","correct":true},{"t":"[ㅂ]","mis":"K4-2-u2-X48"},{"t":"[ㄹ]과 [ㅂ] 둘 다","mis":"K4-2-u2-X48"}],"explanation":["네 낱말 모두 ㄼ 받침이에요.","ㄼ은 [ㄹ]로 소리 나요.","[얄께], [여덜], [짤꼬], [널찌]로 발음해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#4','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C52',3,'error','auto','『국어』 110쪽 대화를 소리 내어 읽었어요. 잘못 발음한 것은 무엇인가요?',ARRAY['K4-2-u2-X48']::text[],false,'{"seq":4,"concept":"K4-2-u2-C52","difficulty":3,"kind":"error","stem":"『국어』 110쪽 대화를 소리 내어 읽었어요. 잘못 발음한 것은 무엇인가요?","options":[{"t":"「공간이 [넙찌] 않으니까 가방을 책상 옆에 잘 두자.」","correct":true,"mis_target":"K4-2-u2-X48"},{"t":"「찰흙을 좀 더 [얄께] 펴는 게 좋아.」","mis":"K4-2-u2-X48"},{"t":"「가방끈이 [짤꼬] 가벼워서 아주 편하더라.」","mis":"K4-2-u2-X48"}],"explanation":["‘넓지’의 ㄼ은 [ㄹ]로 소리 나요.","그래서 [넙찌]가 아니라 [널찌]예요.","[얄께]와 [짤꼬]는 바른 발음이에요."],"asset":{"type":"passage","lines":["㉮ “컵을 만들려면 찰흙을 좀 더 얇게 펴는 게 좋아.” — [얍께]?","㉮ “선생님께서 여덟 가지 색깔을 사용하라고 하셨지?” — [여덥]?","㉯ “누나, 그거 내 새 가방인데 가방끈이 짧고 가벼워서 아주 편하더라.” — [짭꼬]?","㉯ “공간이 넓지 않으니까 가방을 책상 옆에 잘 두자.” — [넙찌]?"],"title":"파란색 낱말의 발음 — 『국어』 110쪽","hi":["얇게","여덟","짧고","넓지"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#5','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C54',3,'mc','auto','「짧고」는 [짤꼬]로 소리 나는데 「짤꼬」라고 적지 않아요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X14','K4-2-u2-X15']::text[],false,'{"seq":5,"concept":"K4-2-u2-C54","difficulty":3,"kind":"mc","stem":"「짧고」는 [짤꼬]로 소리 나는데 「짤꼬」라고 적지 않아요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"뜻을 알아보기 쉽게 글자는 원래 모양대로 적기 때문이다","correct":true},{"t":"소리가 바뀌니 한글은 규칙이 없는 글자이기 때문이다","mis":"K4-2-u2-X14"},{"t":"원래는 소리 나는 대로 적어야 하는데 틀린 것이기 때문이다","mis":"K4-2-u2-X15"}],"explanation":["짧다, 짧아, 짧고처럼 ‘짧-’을 그대로 적으면 같은 낱말인 줄 알아보기 쉬워요.","소리만 바뀌어 날 뿐 글자의 짜임은 그대로예요.","그래서 바른 발음과 바른 글자를 함께 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#6','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C56',3,'mc','auto','『국어』 111쪽 글씨 쓰기 낱말 가운데 받침을 바르게 쓴 것끼리 묶은 것은 무엇인가요?',ARRAY['K4-2-u2-X49']::text[],false,'{"seq":6,"concept":"K4-2-u2-C56","difficulty":3,"kind":"mc","stem":"『국어』 111쪽 글씨 쓰기 낱말 가운데 받침을 바르게 쓴 것끼리 묶은 것은 무엇인가요?","options":[{"t":"뱃삯 · 몫 · 얹다 · 책값","correct":true},{"t":"뱃삭 · 목 · 언다 · 책갑","mis":"K4-2-u2-X49"},{"t":"뱃삯 · 몪 · 얺다 · 책갓","mis":"K4-2-u2-X49"}],"explanation":["뱃삯(ㄳ), 몫(ㄳ), 얹다(ㄵ), 책값(ㅄ)이에요.","겹받침을 받침 하나로 쓰거나 다른 받침으로 쓰지 않아요.","많이(ㄶ), 끊다(ㄶ), 없다(ㅄ)도 함께 연습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#7','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C31',3,'mc','auto','교실 물건 이름을 우리말로 바꾸어 말하는 활동을 해요. 「텔레비전」은 어떻게 하는 것이 알맞을까요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":7,"concept":"K4-2-u2-C31","difficulty":3,"kind":"mc","stem":"교실 물건 이름을 우리말로 바꾸어 말하는 활동을 해요. 「텔레비전」은 어떻게 하는 것이 알맞을까요?","options":[{"t":"알맞은 우리말이 없으니 억지로 새말을 만들지 않고 그대로 쓴다","correct":true},{"t":"외국에서 온 말이니 반드시 새 우리말을 지어 바꾼다","mis":"K4-2-u2-X24"},{"t":"외국어가 멋지니 다른 물건 이름도 외국어로 바꾼다","mis":"K4-2-u2-X25"}],"explanation":["알맞은 우리말이 없는 말은 무리하게 새말로 만들지 않아요.","우리말로 바꿀 수 있는데도 외국어를 자주 쓰는 것이 문제예요.","‘컬러’는 ‘색깔’, ‘팁’은 ‘도움말’처럼 바꿀 수 있는 말에 힘써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#8','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C49',4,'essay','teacher','『국어』 106쪽 주제(한글, 훈민정음, 우리글, 한글날, 세종 대왕, 주시경, 헐버트) 가운데 하나를 골라 한글을 사랑하는 마음이 담긴 몇 행시를 쓰고, 그 시에 담은 마음을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C49","difficulty":4,"kind":"essay","stem":"『국어』 106쪽 주제(한글, 훈민정음, 우리글, 한글날, 세종 대왕, 주시경, 헐버트) 가운데 하나를 골라 한글을 사랑하는 마음이 담긴 몇 행시를 쓰고, 그 시에 담은 마음을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 주제 — 우리글. 우: 우리가 날마다 쓰는 / 리: 리듬처럼 고운 소리 / 글: 글자마다 담긴 조상의 마음. — 날마다 쓰는 한글이 고맙고 자랑스럽다는 마음을 담았다.","scoring_points":["주제어의 글자로 각 행을 차례대로 시작했는가","한글을 사랑하는 마음이 드러나는가","시에 담은 마음을 한 문장으로 썼는가"]},"explanation":["주제어를 먼저 고르고 글자를 세로로 적어요.","행의 길이나 어려운 낱말보다 마음이 또렷한 것이 중요해요.","다 쓴 시는 교실에 전시하고 소감을 나누어요."],"asset":{"type":"passage","lines":["주제 — 한글 · 훈민정음 · 우리글 · 한글날 · 세종 대왕 · 주시경 · 헐버트","한: 한없이 아름다운 우리말","글: 글자로 빛나는 조상의 지혜","「주시경」 — 우리글을 사랑한 주시경! / 한글 꽃을 가꾼 분 /","우리 글자 예쁘게 피었어요."],"title":"한글 사랑 시 쓰기 — 『국어』 106쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#9','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C50',4,'essay','teacher','『국어』 107쪽처럼 우리 동네 간판을 조사할 계획을 세우세요. 조사 대상, 조사 기간, 조사 동기, 조사 방법을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u2-C50","difficulty":4,"kind":"essay","stem":"『국어』 107쪽처럼 우리 동네 간판을 조사할 계획을 세우세요. 조사 대상, 조사 기간, 조사 동기, 조사 방법을 쓰세요.","answer_guide":{"answer":"예: 조사 대상 — 학교 앞 큰길에 있는 가게 간판 30개. 조사 기간 — 20○○년 ○○월 ○○일~○○일. 조사 동기 — 우리말로 쓸 수 있는데도 외국어를 쓴 간판이 많아 보여서 얼마나 되는지 알고 싶었다. 조사 방법 — 직접 걸어 다니며 간판 이름을 기록하고 사진을 찍는다(방문 조사), 인터넷 지도로 빠진 간판을 확인한다.","scoring_points":["조사 대상과 기간을 구체적으로 썼는가","조사 동기가 우리말 사용과 이어지는가","실제로 할 수 있는 조사 방법을 썼는가"]},"explanation":["조사 대상은 직접 살펴볼 수 있는 범위로 정해요.","동기는 우리말 사용과 이어지게 써요.","직접 찾아다니거나 인터넷 지도를 활용할 수 있어요."],"asset":{"type":"passage","lines":["① 우리 동네 간판을 조사할 계획 세우기 — 조사 대상 · 조사 기간 · 조사 동기 · 조사 방법","② 우리 동네 간판을 조사한 내용 정리하기","우리말로 바꿀 수 있는데도 외국어를 쓴 간판과 우리말을 쓴 간판을 조사한다.","직접 다니며 사진을 찍거나 기록하고, 인터넷 지도를 활용할 수도 있다."],"title":"우리 동네 간판 조사하기 — 『국어』 107쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_L12_challenge#10','kor',4,2,'u2','L12','tb_g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C30',4,'essay','teacher','‘JUMP(점프)’, ‘그린 라이프’, ‘리듬 킹’ 가운데 한 동아리를 골라 특성이 잘 드러나는 우리말 이름을 짓고, 그렇게 지은 까닭과 바꾸고 난 뒤의 소감을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C30","difficulty":4,"kind":"essay","stem":"‘JUMP(점프)’, ‘그린 라이프’, ‘리듬 킹’ 가운데 한 동아리를 골라 특성이 잘 드러나는 우리말 이름을 짓고, 그렇게 지은 까닭과 바꾸고 난 뒤의 소감을 쓰세요.","answer_guide":{"answer":"예: ‘그린 라이프’(환경 동아리)를 ‘푸른 지구 지킴이’로 바꾸겠다. 환경을 지키는 동아리라는 특성이 이름만 보고도 잘 드러나기 때문이다. 우리말로 바꾸니 누구나 무엇을 하는 동아리인지 알 수 있어 뿌듯했다.","scoring_points":["한 동아리를 골라 우리말 이름을 지었는가","동아리의 특성이 드러나는 까닭을 썼는가","바꾸고 난 뒤의 소감을 썼는가"]},"explanation":["JUMP는 농구, 그린 라이프는 환경, 리듬 킹은 춤 동아리예요.","동아리가 하는 일이 드러나는 순우리말을 찾아요.","국어사전이나 국립국어원 누리집을 참고해도 좋아요."],"asset":{"type":"passage","lines":["○○초등학교의 동아리 이름 ‘JUMP(점프)’, ‘그린 라이프’, ‘리듬 킹’은","각각 농구 동아리, 환경 동아리, 춤 동아리를 가리킨다.","이름만 보면 무엇을 하는 동아리인지 알기 어려운 경우가 많다.","JUMP 동아리원: “한글 이름보다는 이 이름이 더 멋있어서 지었어요.”","동아리의 이름은 동아리의 특성을 알기 쉽게 나타내는 방법이다."],"title":"우리말로 동아리 이름 짓기 (예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#1','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C7',1,'mc','auto','「문자 이야기」에서 문자가 만들어지기 전에 사람들이 문자 대신 사용한 것은 무엇인가요?',ARRAY['K4-2-u2-X05']::text[],false,'{"seq":1,"concept":"K4-2-u2-C7","difficulty":1,"kind":"mc","stem":"「문자 이야기」에서 문자가 만들어지기 전에 사람들이 문자 대신 사용한 것은 무엇인가요?","options":[{"t":"그림이나 물건","correct":true},{"t":"휴대 전화","mis":"K4-2-u2-X05"},{"t":"인쇄한 책","mis":"K4-2-u2-X05"},{"t":"컴퓨터 글자","mis":"K4-2-u2-X05"}],"explanation":["『국어』 84쪽 2번 (1)의 물음이에요.","문자가 없을 때에는 그림을 그리거나 물건을 이용했어요.","휴대 전화와 책은 문자가 생긴 뒤의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#2','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C2',1,'mc','auto','‘한국어’와 ‘한글’을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u2-X01']::text[],false,'{"seq":2,"concept":"K4-2-u2-C2","difficulty":1,"kind":"mc","stem":"‘한국어’와 ‘한글’을 바르게 말한 것은 무엇인가요?","options":[{"t":"한국어는 우리말이고, 한글은 우리말을 적는 우리글이다","correct":true},{"t":"한국어와 한글은 똑같은 말이다","mis":"K4-2-u2-X01"},{"t":"한글은 우리가 하는 말이고, 한국어는 그 말을 적는 글자이다","mis":"K4-2-u2-X01"}],"explanation":["‘한국어’는 ‘우리말’을 가리켜요.","‘한글’은 ‘우리말을 적은 우리글’이에요.","그래서 「한국어와 한글은 같은 표현이다」는 거짓이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#3','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C12',1,'mc','auto','자음자의 기본 글자 ‘ㅁ’이 본뜬 것은 무엇인가요?',ARRAY['K4-2-u2-X09']::text[],false,'{"seq":3,"concept":"K4-2-u2-C12","difficulty":1,"kind":"mc","stem":"자음자의 기본 글자 ‘ㅁ’이 본뜬 것은 무엇인가요?","options":[{"t":"입의 모양","correct":true},{"t":"이의 모양","mis":"K4-2-u2-X09"},{"t":"목구멍의 모양","mis":"K4-2-u2-X09"},{"t":"혀가 윗잇몸에 닿는 모양","mis":"K4-2-u2-X09"}],"explanation":["ㅁ을 소리 낼 때 입술이 닫혀요.","ㅁ은 입의 모양을 본떴어요.","ㅅ은 이, ㅇ은 목구멍, ㄴ은 혀가 윗잇몸에 닿는 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#4','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C15',1,'blank','auto','「ㅡ의 아래에 ㆍ를 합치면 (     )가 됩니다.」 빈칸에 알맞은 글자는 무엇인가요?',ARRAY['K4-2-u2-X11']::text[],false,'{"seq":4,"concept":"K4-2-u2-C15","difficulty":1,"kind":"blank","stem":"「ㅡ의 아래에 ㆍ를 합치면 (     )가 됩니다.」 빈칸에 알맞은 글자는 무엇인가요?","options":[{"t":"ㅜ","correct":true},{"t":"ㅗ","mis":"K4-2-u2-X11"},{"t":"ㅏ","mis":"K4-2-u2-X11"},{"t":"ㅓ","mis":"K4-2-u2-X11"}],"explanation":["ㅡ 아래에 ㆍ가 붙으면 ㅜ예요.","ㅡ 위에 붙으면 ㅗ가 돼요.","모음자는 기본 글자를 합쳐 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#5','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C23',1,'mc','auto','헐버트가 세계의 지리와 문화를 소개하려고 한글로 쓴 책은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":5,"concept":"K4-2-u2-C23","difficulty":1,"kind":"mc","stem":"헐버트가 세계의 지리와 문화를 소개하려고 한글로 쓴 책은 무엇인가요?","options":[{"t":"『사민필지』","correct":true},{"t":"『훈민정음』","mis":"K4-2-u2-X18"},{"t":"『국어사전』","mis":"K4-2-u2-X18"}],"explanation":["헐버트는 세계 여러 나라를 소개하는 책을 썼어요.","그 책의 이름은 『사민필지』예요.","한문이 아닌 한글(언문)로 써서 누구나 읽을 수 있게 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#6','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C34',1,'mc','auto','국립국어원의 ‘다듬은 말’에서 ‘드론’을 쉬운 우리말로 바꾼 말은 무엇인가요?',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":6,"concept":"K4-2-u2-C34","difficulty":1,"kind":"mc","stem":"국립국어원의 ‘다듬은 말’에서 ‘드론’을 쉬운 우리말로 바꾼 말은 무엇인가요?","options":[{"t":"무인기","correct":true},{"t":"장바구니","mis":"K4-2-u2-X19"},{"t":"붙임쪽지","mis":"K4-2-u2-X19"},{"t":"안방 구매","mis":"K4-2-u2-X19"}],"explanation":["드론은 사람이 타지 않고 나는 기계예요.","그래서 ‘무인기’로 다듬었어요.","쇼핑백은 장바구니, 포스트잇은 붙임쪽지, 홈 쇼핑은 안방 구매예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#7','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C36',1,'mc','auto','보고하는 글에 들어가는 내용이 아닌 것은 무엇인가요?',ARRAY['K4-2-u2-X30']::text[],false,'{"seq":7,"concept":"K4-2-u2-C36","difficulty":1,"kind":"mc","stem":"보고하는 글에 들어가는 내용이 아닌 것은 무엇인가요?","options":[{"t":"조사하지 않고 상상한 이야기","correct":true},{"t":"조사 동기","mis":"K4-2-u2-X30"},{"t":"조사 방법","mis":"K4-2-u2-X30"},{"t":"조사 소감","mis":"K4-2-u2-X30"}],"explanation":["보고하는 글에는 조사 대상·기간·동기·방법이 들어가요.","조사한 내용, 조사 소감, 참고 자료와 그 출처도 들어가요.","보고하는 글은 사실에 근거해 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#8','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C52',1,'mc','auto','「가방끈이 짧고 가벼워서」에서 ‘짧고’의 바른 발음은 무엇인가요?',ARRAY['K4-2-u2-X48','K4-2-u2-X13']::text[],false,'{"seq":8,"concept":"K4-2-u2-C52","difficulty":1,"kind":"mc","stem":"「가방끈이 짧고 가벼워서」에서 ‘짧고’의 바른 발음은 무엇인가요?","options":[{"t":"[짤꼬]","correct":true},{"t":"[짭꼬]","mis":"K4-2-u2-X48"},{"t":"[짧고]","mis":"K4-2-u2-X13"}],"explanation":["‘짧고’의 ㄼ은 [ㄹ]로 소리 나요.","뒤의 ㄱ은 [ㄲ]으로 소리 나요.","그래서 [짤꼬]로 발음해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#9','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C9',2,'mc','auto','문자가 사람들에게 끼친 영향으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03']::text[],false,'{"seq":9,"concept":"K4-2-u2-C9","difficulty":2,"kind":"mc","stem":"문자가 사람들에게 끼친 영향으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"앞사람이 적어 둔 지식을 이어받아 더 많은 것을 알아낼 수 있게 했다","correct":true},{"t":"한 사람이 안 것은 그 사람만 알게 했다","mis":"K4-2-u2-X05"},{"t":"말을 할 수 없는 사람만 지식을 쌓게 했다","mis":"K4-2-u2-X03"}],"explanation":["문자로 적으면 시간과 거리를 넘어 지식이 전해져요.","다음 사람이 그 지식을 이어받아 더 알아낼 수 있어요.","그래서 문자는 사람들이 문화를 쌓아 가는 데 도움을 주었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#10','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C11',2,'mc','auto','「한글이 과학적인 문자인 까닭」에서 한자가 배우기 어려웠던 까닭은 무엇인가요?',ARRAY['K4-2-u2-X12']::text[],false,'{"seq":10,"concept":"K4-2-u2-C11","difficulty":2,"kind":"mc","stem":"「한글이 과학적인 문자인 까닭」에서 한자가 배우기 어려웠던 까닭은 무엇인가요?","options":[{"t":"뜻글자라서 그 수가 많아 배우는 데 많은 시간과 노력이 필요해서","correct":true},{"t":"소리글자라서 글자가 몇 개 안 되어서","mis":"K4-2-u2-X12"},{"t":"글자 모양이 모두 둥글어서","mis":"K4-2-u2-X12"}],"explanation":["한자는 하나하나의 글자가 뜻을 나타내는 뜻글자예요.","그래서 글자 수가 매우 많아요.","대부분의 백성은 글자를 읽거나 쓸 수 없었어요."],"asset":{"type":"passage","lines":["옛날 우리 조상은 중국의 문자인 한자를 빌려 우리말을 썼습니다.","뜻글자인 한자는 그 수가 많아 배우는 데 많은 시간과 노력이 필요했습니다.","(간추림) 대부분의 백성은 글자를 읽거나 쓸 수 없어 억울한 일을 당하기도 했다.","(간추림) 세종 대왕은 백성이 자신의 뜻을 글로 나타내지 못함을 안타까워했다.","(간추림) 세종 대왕은 적은 수의 문자로 누구나 우리말을 읽고 쓰는 훈민정음을 만들었다.","훈민정음은 백성을 가르치는 바른 소리라는 뜻으로,","(간추림) 오늘날 우리가 쓰는 한글의 바탕이 되었다."],"title":"「한글이 과학적인 문자인 까닭」 1·2문단 — 『국어』 86쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#11','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C19',2,'mc','auto','「한글이 과학적인 문자인 까닭」 첫째 문단의 중심 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X55','K4-2-u2-X18']::text[],false,'{"seq":11,"concept":"K4-2-u2-C19","difficulty":2,"kind":"mc","stem":"「한글이 과학적인 문자인 까닭」 첫째 문단의 중심 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"세종 대왕이 한글을 만들게 된 까닭","correct":true},{"t":"한자는 중국의 문자이다","mis":"K4-2-u2-X55"},{"t":"한글은 과학적인 문자로 평가받는다","mis":"K4-2-u2-X18"}],"explanation":["첫째 문단은 한자가 배우기 어려워 글을 모르는 백성이 많았다는 내용이에요.","세종 대왕은 그것을 안타까워했어요.","그래서 한글을 만들게 된 까닭을 소개하는 문단이에요."],"asset":{"type":"passage","lines":["옛날 우리 조상은 중국의 문자인 한자를 빌려 우리말을 썼습니다.","뜻글자인 한자는 그 수가 많아 배우는 데 많은 시간과 노력이 필요했습니다.","(간추림) 대부분의 백성은 글자를 읽거나 쓸 수 없어 억울한 일을 당하기도 했다.","(간추림) 세종 대왕은 백성이 자신의 뜻을 글로 나타내지 못함을 안타까워했다.","(간추림) 세종 대왕은 적은 수의 문자로 누구나 우리말을 읽고 쓰는 훈민정음을 만들었다.","훈민정음은 백성을 가르치는 바른 소리라는 뜻으로,","(간추림) 오늘날 우리가 쓰는 한글의 바탕이 되었다."],"title":"「한글이 과학적인 문자인 까닭」 1·2문단 — 『국어』 86쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#12','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C20',2,'mc','auto','공병우가 한 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":12,"concept":"K4-2-u2-C20","difficulty":2,"kind":"mc","stem":"공병우가 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"한글을 빠르고 정확하게 입력하려고 한글 타자기를 개발했다","correct":true},{"t":"우리나라 고유의 문자인 훈민정음을 만들었다","mis":"K4-2-u2-X18"},{"t":"『사민필지』를 한글로 썼다","mis":"K4-2-u2-X18"}],"explanation":["공병우는 원래 안과 의사였어요.","한글을 빠르게 입력할 필요를 느껴 세벌식 타자기를 만들었어요.","한글 정보화에 앞장선 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#13','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C29',2,'mc','auto','「상대와도 좋은 관계를 맺을 수 있기 때문이야.」라는 까닭과 가장 잘 이어지는 자료는 무엇인가요?',ARRAY['K4-2-u2-X29']::text[],false,'{"seq":13,"concept":"K4-2-u2-C29","difficulty":2,"kind":"mc","stem":"「상대와도 좋은 관계를 맺을 수 있기 때문이야.」라는 까닭과 가장 잘 이어지는 자료는 무엇인가요?","options":[{"t":"자료 ㉰ — 부딪친 친구에게 한 거친 말","correct":true},{"t":"자료 ㉮ — 「Happy 버거」 간판","mis":"K4-2-u2-X29"},{"t":"자료 ㉯ — # 열공","mis":"K4-2-u2-X29"}],"explanation":["자료 ㉰의 친구들은 거친 말을 주고받아 서로 화가 났어요.","상대의 기분을 상하게 하는 비속어를 쓰지 않으면 사이가 좋아져요.","바른 말은 좋은 관계를 맺게 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#14','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C40',2,'mc','auto','지후의 그래프에서 줄임말을 가장 많이 사용하는 상황은 무엇인가요?',ARRAY['K4-2-u2-X40']::text[],false,'{"seq":14,"concept":"K4-2-u2-C40","difficulty":2,"kind":"mc","stem":"지후의 그래프에서 줄임말을 가장 많이 사용하는 상황은 무엇인가요?","options":[{"t":"메신저","correct":true},{"t":"인터넷","mis":"K4-2-u2-X40"},{"t":"일상 대화","mis":"K4-2-u2-X40"},{"t":"게임","mis":"K4-2-u2-X40"}],"explanation":["그래프에서 막대가 가장 긴 것을 찾아요.","메신저 8명, 인터넷 5명, 일상 대화 3명, 게임 2명이에요.","그래프로 나타내면 가장 많은 것을 한눈에 알 수 있어요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#15','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C41',2,'mc','auto','설문 조사 결과 열여덟 명인데 「스무 명 모두」라고 쓰면 어떤 문제가 있나요?',ARRAY['K4-2-u2-X35']::text[],false,'{"seq":15,"concept":"K4-2-u2-C41","difficulty":2,"kind":"mc","stem":"설문 조사 결과 열여덟 명인데 「스무 명 모두」라고 쓰면 어떤 문제가 있나요?","options":[{"t":"조사 결과를 부풀려 왜곡한 것이다","correct":true},{"t":"문제를 알리려는 것이니 괜찮다","mis":"K4-2-u2-X35"},{"t":"수는 대충 비슷하게 써도 된다","mis":"K4-2-u2-X35"}],"explanation":["보고하는 글은 조사한 결과를 있는 그대로 써요.","수를 바꾸면 읽는 사람이 잘못 알게 돼요.","결과를 과장, 축소, 변형, 왜곡하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#16','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C49',2,'mc','auto','한글 사랑 시를 전시했어요. 좋은 한글 사랑 시로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X45']::text[],false,'{"seq":16,"concept":"K4-2-u2-C49","difficulty":2,"kind":"mc","stem":"한글 사랑 시를 전시했어요. 좋은 한글 사랑 시로 가장 알맞은 것은 무엇인가요?","options":[{"t":"한글에 대한 내 마음이 또렷하게 담긴 시","correct":true},{"t":"행이 가장 많은 시","mis":"K4-2-u2-X45"},{"t":"어려운 낱말이 가장 많이 들어간 시","mis":"K4-2-u2-X45"}],"explanation":["시는 길이보다 담긴 마음이 중요해요.","어려운 낱말보다 내 마음을 잘 나타내는 낱말을 골라요.","친구의 시를 읽고 소감을 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#17','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C19',3,'mc','auto','『국어활동』 22쪽 2번이에요. 한글에 대한 설명으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u2-X17']::text[],false,'{"seq":17,"concept":"K4-2-u2-C19","difficulty":3,"kind":"mc","stem":"『국어활동』 22쪽 2번이에요. 한글에 대한 설명으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"한글이 만들어지기 전 우리 조상은 문자를 사용하지 않았다","correct":true},{"t":"한글은 우리나라의 문자이다","mis":"K4-2-u2-X17"},{"t":"한글은 글자를 만든 원리와 방법이 알려져 있다","mis":"K4-2-u2-X17"},{"t":"한글의 옛 이름은 훈민정음이다","mis":"K4-2-u2-X17"}],"explanation":["한글이 만들어지기 전에는 한자를 빌려 썼어요.","그러니 문자를 사용하지 않았다는 말은 알맞지 않아요.","나머지 셋은 모두 한글에 대한 알맞은 설명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#18','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C24',3,'mc','auto','헐버트가 미국 신문에 한글을 소개하고 한글과 영어 자모를 비교하는 글을 쓴 행동에서 알 수 있는 마음은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X20']::text[],false,'{"seq":18,"concept":"K4-2-u2-C24","difficulty":3,"kind":"mc","stem":"헐버트가 미국 신문에 한글을 소개하고 한글과 영어 자모를 비교하는 글을 쓴 행동에서 알 수 있는 마음은 무엇인가요?","options":[{"t":"한글의 우수함을 세계에 널리 알리고 싶은 마음","correct":true},{"t":"영어를 깎아내리고 싶은 마음","mis":"K4-2-u2-X16"},{"t":"자기 이름으로 돈을 벌고 싶은 마음","mis":"K4-2-u2-X20"}],"explanation":["헐버트는 한글의 과학성을 처음으로 세계에 알렸어요.","가르치는 일을 그만둔 뒤에도 노력을 멈추지 않았어요.","이런 행동에서 한글을 아끼는 마음을 알 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 헐버트는 신분이나 남녀를 가리지 않고 누구나 세계를 알아야 한다고 생각했다.","(간추림) 『사민필지』는 전국의 학교에서 세계 지리를 배우는 교재로 쓰였다.","(간추림) 미국 신문에 한글을 소개해 한글의 과학성을 처음으로 세계에 알렸다.","(간추림) 한글과 영어 자모를 비교하는 글을 쓰고 영문자 신문 만들기에도 참여했다.","푸른 눈의 헐버트는 외국인이면서도 누구보다 한글을 사랑한 벗이었습니다."],"title":"「한글을 사랑한 외국인, 헐버트」 뒷부분 — 『국어』 92~93쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#19','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C32',3,'mc','auto','줄임말을 써도 뜻이 잘 통하는 상황은 어느 것인가요?',ARRAY['K4-2-u2-X26','K4-2-u2-X27']::text[],false,'{"seq":19,"concept":"K4-2-u2-C32","difficulty":3,"kind":"mc","stem":"줄임말을 써도 뜻이 잘 통하는 상황은 어느 것인가요?","options":[{"t":"줄임말의 뜻을 잘 아는 짝과 쪽지를 주고받을 때","correct":true},{"t":"줄임말을 모르시는 할머니께 문자를 보낼 때","mis":"K4-2-u2-X26"},{"t":"학교 행사 안내문을 쓸 때","mis":"K4-2-u2-X26"},{"t":"어떤 상황이든 줄임말은 쓰면 안 된다","mis":"K4-2-u2-X27"}],"explanation":["줄임말은 뜻을 아는 사람끼리만 통해요.","할머니나 여러 사람이 읽는 안내문에는 풀어 써요.","상황과 듣는 사람을 살피면 지나치지 않게 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#20','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C42',3,'mc','auto','뉴스 기사를 참고한 출처를 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u2-X57','K4-2-u2-X37']::text[],false,'{"seq":20,"concept":"K4-2-u2-C42","difficulty":3,"kind":"mc","stem":"뉴스 기사를 참고한 출처를 바르게 쓴 것은 무엇인가요?","options":[{"t":"○○○ 기자, 「줄임말로 대화하는 초등학생」, 『○○일보』, 20○○. ○○. ○○.","correct":true},{"t":"「줄임말로 대화하는 초등학생」","mis":"K4-2-u2-X57"},{"t":"인터넷","mis":"K4-2-u2-X37"}],"explanation":["기사의 출처에는 기자 이름, 기사 제목, 발행한 곳, 발행 일자를 써요.","제목만 쓰거나 「인터넷」이라고만 쓰면 부족해요.","출처가 분명해야 읽는 사람이 자료를 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#21','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C38',3,'mc','auto','「우리 반 친구들이 비속어를 쓰게 된 까닭」을 알아보려고 해요. 가장 알맞은 조사 방법은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":21,"concept":"K4-2-u2-C38","difficulty":3,"kind":"mc","stem":"「우리 반 친구들이 비속어를 쓰게 된 까닭」을 알아보려고 해요. 가장 알맞은 조사 방법은 무엇인가요?","options":[{"t":"면담 조사","correct":true},{"t":"설문 조사","mis":"K4-2-u2-X33"},{"t":"방문 조사","mis":"K4-2-u2-X33"}],"explanation":["까닭은 친구를 직접 만나 이야기를 들어야 자세히 알 수 있어요.","지후도 까닭은 면담 조사로 알아보았어요.","면담할 때에는 질문지를 준비하고 끼어들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#22','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C47',3,'mc','auto','보고하는 글의 「조사 동기」로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":22,"concept":"K4-2-u2-C47","difficulty":3,"kind":"mc","stem":"보고하는 글의 「조사 동기」로 알맞은 것은 무엇인가요?","options":[{"t":"초등학생이 줄임말을 지나치게 쓴다는 기사를 보고 우리 반 친구들은 어떤지 알고 싶었다","correct":true},{"t":"열여덟 명이 줄임말을 자주 사용했다","mis":"K4-2-u2-X44"},{"t":"바른 언어생활을 하도록 노력하겠다","mis":"K4-2-u2-X44"}],"explanation":["조사 동기는 조사를 하게 된 까닭이에요.","열여덟 명은 조사한 내용이에요.","노력하겠다는 다짐은 조사 소감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#23','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C19',4,'essay','teacher','평가 자료 「나만의 한글책」이에요. 「문자가 필요한 까닭은 무엇일까요?」와 「한글이 과학적인 문자인 까닭은 무엇일까요?」에 대한 답을 각각 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u2-C19","difficulty":4,"kind":"essay","stem":"평가 자료 「나만의 한글책」이에요. 「문자가 필요한 까닭은 무엇일까요?」와 「한글이 과학적인 문자인 까닭은 무엇일까요?」에 대한 답을 각각 쓰세요.","answer_guide":{"answer":"예: 문자가 필요한 까닭 — 시간이 흐르거나 장소가 바뀌어도 생각을 정확하게 남기고 전할 수 있기 때문이다. 한글이 과학적인 문자인 까닭 — 발음 기관과 하늘, 땅, 사람의 모양을 본떠 기본 글자를 만들었고, 기본 글자를 확장해 다른 글자를 만들었으며, 소리와 글자가 규칙적으로 연결되기 때문이다.","scoring_points":["문자가 필요한 까닭을 남기기·전하기와 이어 썼는가","한글이 과학적인 까닭 세 가지를 썼는가","배운 내용을 자신의 말로 정리했는가"]},"explanation":["2차시와 3~4차시에 배운 내용을 떠올려요.","「한글이 과학적인 문자인 까닭」 셋째~다섯째 문단을 다시 보아요.","정답을 외우기보다 이해한 것을 내 말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#24','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C47',4,'essay','teacher','평가 자료 「우리말 사용에 대하여 보고하는 글 쓰기」의 틀이에요. 지후의 글에서 제목, 조사 대상, 조사 방법, 참고 자료와 그 출처를 찾아 옮겨 쓰고, 「조사 대상」과 「참고 자료와 그 출처」 칸이 꼭 있어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C47","difficulty":4,"kind":"essay","stem":"평가 자료 「우리말 사용에 대하여 보고하는 글 쓰기」의 틀이에요. 지후의 글에서 제목, 조사 대상, 조사 방법, 참고 자료와 그 출처를 찾아 옮겨 쓰고, 「조사 대상」과 「참고 자료와 그 출처」 칸이 꼭 있어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 제목 — 우리 반 친구들의 줄임말 사용. 조사 대상 — 4학년 ○반 학생 20명. 조사 방법 — 설문 조사, 면담 조사, 인터넷 조사. 참고 자료와 그 출처 — ○○○ 기자, 「줄임말로 대화하는 초등학생」, 『○○일보』, 20○○. ○○. ○○. 조사 대상을 밝혀야 누구를 조사한 내용인지 알 수 있고, 출처를 밝혀야 읽는 사람이 자료를 확인할 수 있고 다른 사람의 글을 내 것처럼 쓰지 않게 된다.","scoring_points":["지후의 글에서 네 칸을 바르게 찾아 옮겼는가","조사 대상이 있어야 하는 까닭을 썼는가","출처가 있어야 하는 까닭을 썼는가"]},"explanation":["『국어』 104쪽 보고하는 글 틀을 따라요.","조사 대상은 사람 수까지 밝혀요.","기사의 출처는 기자 이름, 기사 제목, 발행한 곳, 발행 일자를 써요."],"asset":{"type":"passage","lines":["제목 — 우리 반 친구들의 줄임말 사용","조사 대상 — 4학년 ○반 학생 20명","조사 기간 — 20○○년 ○○월 ○○일~○○월 ○○일","조사 동기 — 초등학생이 줄임말을 지나치게 사용한다는 기사를 보고","우리 반 친구들의 줄임말 사용에 대하여 조사해 보고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 인터넷 조사"],"title":"지후가 쓴 보고하는 글 ① — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_a#25','kor',4,2,'u2','','tb_g4_2_kor_u2_review_a','unit_review','K4-2-u2-C6',4,'essay','teacher','『국어활동』 22쪽 동생처럼 「문자 없는 세상에서 살고 싶어!」라고 말하는 친구에게 문자가 필요한 까닭과 한글의 좋은 점을 함께 들어 설득하는 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u2-C6","difficulty":4,"kind":"essay","stem":"『국어활동』 22쪽 동생처럼 「문자 없는 세상에서 살고 싶어!」라고 말하는 친구에게 문자가 필요한 까닭과 한글의 좋은 점을 함께 들어 설득하는 말을 쓰세요.","answer_guide":{"answer":"예: 문자가 없으면 내일 준비물도, 할머니께 보낼 편지도, 옛날에 있었던 일도 남길 수 없어. 시간이 흐르거나 멀리 있어도 생각을 정확하게 전하려면 문자가 꼭 필요해. 게다가 한글은 기본 글자 몇 개만 익히면 소리와 글자가 규칙적으로 이어져서 누구나 쉽게 배울 수 있어. 헐버트도 나흘 만에 익혔대.","scoring_points":["문자가 필요한 까닭을 생활 예와 함께 썼는가","한글의 좋은 점(특성)을 썼는가","친구를 설득하는 말투로 썼는가"]},"explanation":["문자가 한 역할(기억·전달·기록)을 떠올려요.","한글의 과학적인 특성을 함께 들어요.","친구가 알아듣기 쉬운 예를 들어요."],"asset":{"type":"speech","turns":[{"who":"동생","text":"형! 나 문자 없는 세상에서 살고 싶어!"},{"who":"형","text":"뭐라고? 그게 무슨 말이야?"},{"who":"동생","text":"날마다 알림장 쓰기도 귀찮고, 영어 시간에 알파벳 쓰는 것도 어렵단 말이야!"},{"who":"형","text":"그랬구나. 그래도 우리 생활에 문자는 꼭 필요해. 왜냐하면 ……"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#1','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C7',1,'ox','auto','암각화는 바위나 동굴의 벽면에 칠하거나 새기거나 쪼아 그린 그림이에요.',ARRAY['K4-2-u2-X04']::text[],false,'{"seq":1,"concept":"K4-2-u2-C7","difficulty":1,"kind":"ox","stem":"암각화는 바위나 동굴의 벽면에 칠하거나 새기거나 쪼아 그린 그림이에요.","answer":"O","reason_options":[{"t":"문자가 없던 때 사람들이 생각을 남긴 방법이에요.","correct":true},{"t":"암각화는 글자로 쓴 옛 책이에요.","mis":"K4-2-u2-X04"}],"mis":"K4-2-u2-X04","explanation":["반구대 암각화, 리오 핀투라스 암각화가 『국어』 84쪽에 나와요.","바위에 그림을 새겨 생각을 기록했어요.","그림은 보는 사람마다 뜻을 다르게 짐작할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#2','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C2',1,'blank','auto','「로마자가 영어를 적는 문자이듯이 한글은 (     )를 적는 문자입니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X01']::text[],false,'{"seq":2,"concept":"K4-2-u2-C2","difficulty":1,"kind":"blank","stem":"「로마자가 영어를 적는 문자이듯이 한글은 (     )를 적는 문자입니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"한국어","correct":true},{"t":"한자","mis":"K4-2-u2-X01"},{"t":"영어","mis":"K4-2-u2-X01"},{"t":"중국어","mis":"K4-2-u2-X01"}],"explanation":["언어와 문자는 서로 달라요.","영어라는 말을 로마자로 적듯이 한국어라는 말을 한글로 적어요.","한자는 중국의 문자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#3','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C12',1,'match','auto','『국어활동』 23쪽 3번 (2)예요. 모음자의 기본 글자와 본뜬 것을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u2-C12","difficulty":1,"kind":"match","stem":"『국어활동』 23쪽 3번 (2)예요. 모음자의 기본 글자와 본뜬 것을 이으세요.","pairs":[{"l":"ㆍ","r":"하늘"},{"l":"ㅡ","r":"땅"},{"l":"ㅣ","r":"사람"}],"mis":"K4-2-u2-X09","explanation":["모음자 기본 글자는 우리 민족이 중요하게 생각한 세 가지를 본떴어요.","ㆍ는 둥근 하늘, ㅡ는 평평한 땅이에요.","ㅣ는 하늘과 땅을 연결하는 사람의 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#4','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C13',1,'ox','auto','자음자는 소리가 강하게 날수록 기본 글자에 획을 더해 만들었어요.',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":4,"concept":"K4-2-u2-C13","difficulty":1,"kind":"ox","stem":"자음자는 소리가 강하게 날수록 기본 글자에 획을 더해 만들었어요.","answer":"O","reason_options":[{"t":"ㄱ에 획을 더하면 소리가 더 센 ㅋ이 돼요.","correct":true},{"t":"획이 늘수록 소리가 약해져요.","mis":"K4-2-u2-X10"}],"mis":"K4-2-u2-X10","explanation":["넷째 문단에 나온 내용이에요.","획을 하나씩 더할수록 소리가 더 강해져요.","모음자는 획을 더하지 않고 합쳐서 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#5','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C23',1,'sa','auto','「한글을 사랑한 외국인, 헐버트」에서 헐버트는 어느 나라에서 왔나요?','{}'::text[],false,'{"seq":5,"concept":"K4-2-u2-C23","difficulty":1,"kind":"sa","stem":"「한글을 사랑한 외국인, 헐버트」에서 헐버트는 어느 나라에서 왔나요?","answer":["미국","미국인","미국 사람"],"explanation":["1886년 인천 항구에 배가 도착했어요.","푸른 눈의 미국인 호머 헐버트가 내렸어요.","한 달도 넘게 배를 타고 조선에 왔어요."],"mis":"K4-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#6','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C34',1,'sa','auto','‘다듬은 말’에서 ‘쇼핑백’을 쉬운 우리말로 바꾼 말을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u2-C34","difficulty":1,"kind":"sa","stem":"‘다듬은 말’에서 ‘쇼핑백’을 쉬운 우리말로 바꾼 말을 쓰세요.","answer":["장바구니"],"explanation":["쇼핑백은 산 물건을 담는 가방이에요.","쉬운 우리말로 ‘장바구니’라고 해요.","우리말로 쓸 수 있는 말은 우리말로 써요."],"mis":"K4-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#7','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C37',1,'blank','auto','「(     ) 조사 — 조사 대상자와 직접 대화를 해 조사 주제와 관련한 자료를 모으는 방법」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":7,"concept":"K4-2-u2-C37","difficulty":1,"kind":"blank","stem":"「(     ) 조사 — 조사 대상자와 직접 대화를 해 조사 주제와 관련한 자료를 모으는 방법」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"면담","correct":true},{"t":"설문","mis":"K4-2-u2-X33"},{"t":"인터넷","mis":"K4-2-u2-X33"},{"t":"문헌","mis":"K4-2-u2-X33"}],"explanation":["직접 만나 묻고 듣는 조사는 면담 조사예요.","설문은 질문지에 답하게 하는 방법이에요.","문헌 조사는 책이나 통계 자료에서 찾는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#8','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C56',1,'mc','auto','「책을 사는 데 드는 돈」을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u2-X49']::text[],false,'{"seq":8,"concept":"K4-2-u2-C56","difficulty":1,"kind":"mc","stem":"「책을 사는 데 드는 돈」을 바르게 쓴 것은 무엇인가요?","options":[{"t":"책값","correct":true},{"t":"책갑","mis":"K4-2-u2-X49"},{"t":"책갚","mis":"K4-2-u2-X49"}],"explanation":["‘값’은 ㅄ 받침이에요.","두 받침을 함께 바르게 써요.","‘책값’, ‘없다’처럼 ㅄ 받침 낱말을 연습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#9','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C6',2,'ox','auto','말을 할 수 있으니 문자가 없어도 생활에 아무 불편이 없어요.',ARRAY['K4-2-u2-X03']::text[],false,'{"seq":9,"concept":"K4-2-u2-C6","difficulty":2,"kind":"ox","stem":"말을 할 수 있으니 문자가 없어도 생활에 아무 불편이 없어요.","answer":"X","reason_options":[{"t":"시간이 흐르거나 멀리 떨어지면 말로는 생각을 정확하게 전하기 어려워요.","correct":true},{"t":"말로 하면 무엇이든 오래 정확하게 남아요.","mis":"K4-2-u2-X03"}],"mis":"K4-2-u2-X03","explanation":["말은 하고 나면 사라지고, 기억은 흐려져요.","알림장이 없으면 준비물을 잊기 쉬워요.","그래서 생각을 남기고 전하려면 문자가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#10','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C16',2,'ox','auto','한글의 ‘ㅏ’는 어떤 낱말에 쓰여도 같은 소리를 내요.',ARRAY['K4-2-u2-X14']::text[],false,'{"seq":10,"concept":"K4-2-u2-C16","difficulty":2,"kind":"ox","stem":"한글의 ‘ㅏ’는 어떤 낱말에 쓰여도 같은 소리를 내요.","answer":"O","reason_options":[{"t":"한글은 하나의 글자로 하나의 우리말 소리를 나타내요.","correct":true},{"t":"한글도 영어의 A처럼 낱말마다 소리가 제멋대로 달라져요.","mis":"K4-2-u2-X14"}],"mis":"K4-2-u2-X14","explanation":["다섯째 문단의 내용이에요.","영어의 A는 낱말에 따라 소리가 여러 가지예요.","한글은 소리와 글자가 규칙적으로 연결돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#11','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C19',2,'mc','auto','「‘확장하다’는 무슨 뜻일까?」는 어떤 방법으로 만든 질문인가요?',ARRAY['K4-2-u2-X54']::text[],false,'{"seq":11,"concept":"K4-2-u2-C19","difficulty":2,"kind":"mc","stem":"「‘확장하다’는 무슨 뜻일까?」는 어떤 방법으로 만든 질문인가요?","options":[{"t":"낱말의 뜻을 짐작하는 질문","correct":true},{"t":"자신의 경험과 관련지어 만든 질문","mis":"K4-2-u2-X54"},{"t":"글의 내용과 관련해 더 궁금한 점을 묻는 질문","mis":"K4-2-u2-X54"}],"explanation":["‘확장하다’라는 낱말 하나의 뜻을 묻고 있어요.","글의 앞뒤를 읽으며 뜻을 짐작할 수 있어요.","‘확장하다’는 무언가를 늘리고 넓힌다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#12','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C20',2,'mc','auto','한글을 꽃피운 사람 가운데 최정호가 한 일은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":12,"concept":"K4-2-u2-C20","difficulty":2,"kind":"mc","stem":"한글을 꽃피운 사람 가운데 최정호가 한 일은 무엇인가요?","options":[{"t":"명조체, 고딕체 같은 한글 글꼴의 원형을 만들었다","correct":true},{"t":"시각 장애인을 위한 한글 점자를 만들었다","mis":"K4-2-u2-X18"},{"t":"한글 타자기를 발명했다","mis":"K4-2-u2-X18"}],"explanation":["최정호는 한글 글꼴 디자이너예요.","오늘날 쓰는 한글 글꼴 30여 종의 원형을 만들었어요.","점자는 박두성, 타자기는 공병우가 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#13','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C33',2,'ox','auto','거친 말은 상대의 마음을 다치게 하고 사이를 멀어지게 해요.',ARRAY['K4-2-u2-X28']::text[],false,'{"seq":13,"concept":"K4-2-u2-C33","difficulty":2,"kind":"ox","stem":"거친 말은 상대의 마음을 다치게 하고 사이를 멀어지게 해요.","answer":"O","reason_options":[{"t":"상대의 기분을 상하게 하는 비속어는 쓰지 않아요.","correct":true},{"t":"친한 사이라면 거친 말도 괜찮아요.","mis":"K4-2-u2-X28"}],"mis":"K4-2-u2-X28","explanation":["자료 ㉰의 말을 들으면 불쾌하고 화가 나요.","친한 사이라도 거친 말은 마음을 다치게 해요.","바르고 고운 말을 써야 좋은 관계를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#14','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C40',2,'sa','auto','지후의 그래프에서 게임을 할 때 줄임말을 사용한다고 한 친구는 몇 명인가요? 수로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"K4-2-u2-C40","difficulty":2,"kind":"sa","stem":"지후의 그래프에서 게임을 할 때 줄임말을 사용한다고 한 친구는 몇 명인가요? 수로 쓰세요.","answer":["2","2명","두 명"],"explanation":["그래프의 게임 막대를 보아요.","게임은 2명이에요.","네 상황을 모두 더하면 열여덟 명이에요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"},"mis":"K4-2-u2-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#15','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C46',2,'ox','auto','조사 결과가 많으면 글이 길어지니 몇 가지는 빼고 써도 돼요.',ARRAY['K4-2-u2-X56']::text[],false,'{"seq":15,"concept":"K4-2-u2-C46","difficulty":2,"kind":"ox","stem":"조사 결과가 많으면 글이 길어지니 몇 가지는 빼고 써도 돼요.","answer":"X","reason_options":[{"t":"조사한 결과를 마음대로 줄이면 결과가 바뀌어요.","correct":true},{"t":"줄여 쓰는 것은 결과를 바꾸는 것이 아니에요.","mis":"K4-2-u2-X56"}],"mis":"K4-2-u2-X56","explanation":["지후의 메모 ㉢도 까닭 세 가지를 두 가지로 줄이려다 고쳤어요.","줄이는 것도 결과를 바꾸는 일이에요.","조사한 그대로 모두 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#16','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C50',2,'mc','auto','『국어』 107쪽 우리 동네 간판 조사 계획에 들어갈 내용이 아닌 것은 무엇인가요?',ARRAY['K4-2-u2-X50']::text[],false,'{"seq":16,"concept":"K4-2-u2-C50","difficulty":2,"kind":"mc","stem":"『국어』 107쪽 우리 동네 간판 조사 계획에 들어갈 내용이 아닌 것은 무엇인가요?","options":[{"t":"조사 소감","correct":true},{"t":"조사 대상","mis":"K4-2-u2-X50"},{"t":"조사 기간","mis":"K4-2-u2-X50"},{"t":"조사 방법","mis":"K4-2-u2-X50"}],"explanation":["계획에는 조사 대상, 기간, 동기, 방법을 써요.","조사 소감은 조사를 마친 뒤에 써요.","계획을 구체적으로 세워야 조사를 잘할 수 있어요."],"asset":{"type":"passage","lines":["① 우리 동네 간판을 조사할 계획 세우기 — 조사 대상 · 조사 기간 · 조사 동기 · 조사 방법","② 우리 동네 간판을 조사한 내용 정리하기","우리말로 바꿀 수 있는데도 외국어를 쓴 간판과 우리말을 쓴 간판을 조사한다.","직접 다니며 사진을 찍거나 기록하고, 인터넷 지도를 활용할 수도 있다."],"title":"우리 동네 간판 조사하기 — 『국어』 107쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#17','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C19',3,'ox','auto','한글은 누가 만들었는지 밝혀진 세계에서 유일한 문자예요.',ARRAY['K4-2-u2-X23']::text[],false,'{"seq":17,"concept":"K4-2-u2-C19","difficulty":3,"kind":"ox","stem":"한글은 누가 만들었는지 밝혀진 세계에서 유일한 문자예요.","answer":"X","reason_options":[{"t":"만든 사람이 알려진 문자는 많고, 한글은 만든 사람·때·목적·원리가 모두 밝혀진 문자예요.","correct":true},{"t":"만든 사람이 알려진 문자는 한글 하나뿐이에요.","mis":"K4-2-u2-X23"}],"mis":"K4-2-u2-X23","explanation":["키릴 문자처럼 만든 사람이 알려진 문자는 한글 말고도 있어요.","한글은 만든 사람뿐 아니라 만든 때, 목적, 원리까지 모두 밝혀져 있어요.","한글의 특성을 말할 때 사실보다 부풀리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#18','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C28',3,'mc','auto','한글 사랑을 실천한 인물에게 쓴 편지로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X51']::text[],false,'{"seq":18,"concept":"K4-2-u2-C28","difficulty":3,"kind":"mc","stem":"한글 사랑을 실천한 인물에게 쓴 편지로 가장 알맞은 것은 무엇인가요?","options":[{"t":"알게 된 일, 그때 든 생각, 앞으로 할 일을 차례로 쓴 편지","correct":true},{"t":"「훌륭하세요!」 한마디만 쓴 편지","mis":"K4-2-u2-X51"},{"t":"인물이 한 일만 글에서 그대로 옮겨 적은 편지","mis":"K4-2-u2-X51"}],"explanation":["편지에는 인물이 한 일을 알고 든 생각을 써요.","앞으로 내가 실천할 일도 써요.","그래야 한글을 사랑하는 내 마음이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#19','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C31',3,'mc','auto','다음 가운데 우리말로 바꾸어 쓰는 것이 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X24']::text[],false,'{"seq":19,"concept":"K4-2-u2-C31","difficulty":3,"kind":"mc","stem":"다음 가운데 우리말로 바꾸어 쓰는 것이 알맞은 말은 무엇인가요?","options":[{"t":"홈 쇼핑","correct":true},{"t":"피아노","mis":"K4-2-u2-X24"},{"t":"버스","mis":"K4-2-u2-X24"}],"explanation":["홈 쇼핑은 ‘안방 구매’라는 다듬은 말이 있어요.","피아노와 버스는 알맞은 우리말이 없이 굳은 말이에요.","바꿀 우리말이 있는 말부터 우리말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#20','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C42',3,'mc','auto','『국어활동』 25쪽이에요. 보고하는 글을 쓸 때 자료의 출처를 밝혀야 하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X41','K4-2-u2-X37']::text[],false,'{"seq":20,"concept":"K4-2-u2-C42","difficulty":3,"kind":"mc","stem":"『국어활동』 25쪽이에요. 보고하는 글을 쓸 때 자료의 출처를 밝혀야 하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다른 사람이 힘들게 만든 결과물을 내 것처럼 쓰면 훔치는 것과 같기 때문","correct":true},{"t":"출처를 쓰면 글이 길어 보이기 때문","mis":"K4-2-u2-X41"},{"t":"출처는 선생님만 알면 되기 때문","mis":"K4-2-u2-X37"}],"explanation":["다른 사람의 글은 그 사람이 노력해서 창작한 결과물이에요.","허락 없이 그대로 가져다 쓰면 물건을 훔치는 것과 같아요.","꼭 필요한 자료는 참고하고 반드시 출처를 밝혀요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어? 인터넷에 초등학생이 쓰는 외국어에 대한 보고서가 있어! 이름만 바꿔서 내자."},{"who":"친구 2","text":"안 돼. ……"},{"who":"친구 3","text":"맞아. 꼭 필요한 자료면 참고하고, 반드시 자료의 출처를 밝혀야 해."},{"who":"친구 1","text":"하하, 미안해. 편하게 하려는 생각에 나도 모르게 그만……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#21','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C45',3,'mc','auto','설문 질문 「외국어와 줄임말을 자주 쓰고 좋아하나요?」를 고치려고 해요. 가장 알맞게 고친 것은 무엇인가요?',ARRAY['K4-2-u2-X42']::text[],false,'{"seq":21,"concept":"K4-2-u2-C45","difficulty":3,"kind":"mc","stem":"설문 질문 「외국어와 줄임말을 자주 쓰고 좋아하나요?」를 고치려고 해요. 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"「외국어를 하루에 몇 번쯤 쓰나요?」와 「줄임말을 하루에 몇 번쯤 쓰나요?」로 나누어 묻는다","correct":true},{"t":"질문을 그대로 둔다","mis":"K4-2-u2-X42"},{"t":"「외국어는 나쁘니 쓰지 않는 게 좋겠지요?」로 바꾼다","mis":"K4-2-u2-X42"}],"explanation":["처음 질문은 외국어와 줄임말, 쓰는 것과 좋아하는 것을 한꺼번에 물어요.","하나의 질문에 하나의 답만 나오게 나누어요.","답을 한쪽으로 몰아가는 질문은 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#22','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C48',3,'error','auto','보고하는 글을 바꾸어 읽고 고쳐 쓸 점을 말했어요. 알맞지 않은 의견은 무엇인가요?',ARRAY['K4-2-u2-X41','K4-2-u2-X59']::text[],false,'{"seq":22,"concept":"K4-2-u2-C48","difficulty":3,"kind":"error","stem":"보고하는 글을 바꾸어 읽고 고쳐 쓸 점을 말했어요. 알맞지 않은 의견은 무엇인가요?","options":[{"t":"「글이 짧으니 조사하지 않은 내용도 더 넣자.」","correct":true,"mis_target":"K4-2-u2-X41"},{"t":"「필요하지 않은 내용은 삭제하자.」","mis":"K4-2-u2-X59"},{"t":"「조사 방법을 정확하게 밝히자.」","mis":"K4-2-u2-X41"}],"explanation":["조사하지 않은 내용을 넣으면 사실이 아닌 글이 돼요.","좋은 보고하는 글은 긴 글이 아니라 믿을 수 있는 글이에요.","필요 없는 내용은 빼고, 조사 방법은 정확히 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#23','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C27',4,'essay','teacher','평가 자료 「나만의 한글책」이에요. 「세종 대왕은 왜 한글을 만드셨나요?」에 답하고, 「나는 한글 사랑을 위해 무엇을 실천할 수 있을까요?」도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u2-C27","difficulty":4,"kind":"essay","stem":"평가 자료 「나만의 한글책」이에요. 「세종 대왕은 왜 한글을 만드셨나요?」에 답하고, 「나는 한글 사랑을 위해 무엇을 실천할 수 있을까요?」도 쓰세요.","answer_guide":{"answer":"예: 한자는 수가 많아 배우기 어려워서 대부분의 백성이 자신의 뜻을 글로 나타내지 못했다. 세종 대왕은 그것을 안타까워해 누구나 쉽게 읽고 쓰는 훈민정음을 만들었다. 나는 모르는 낱말이 나오면 국어사전을 찾아보고, 친구에게 보내는 글에서 받침까지 바르게 쓰겠다.","scoring_points":["세종 대왕이 한글을 만든 까닭을 바르게 썼는가","자신이 실천할 한글 사랑을 구체적으로 썼는가","한글을 소중히 여기는 마음이 드러나는가"]},"explanation":["「한글이 과학적인 문자인 까닭」 첫째 문단을 떠올려요.","한글 사랑은 내 생활에서 작은 것부터 시작해요.","쓴 내용은 한글책에 모아 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#24','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C44',4,'essay','teacher','『국어』 102쪽처럼 우리말 사용과 관련해 자신이 조사하고 싶은 주제를 정하고, 조사가 필요한 까닭과 조사 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C44","difficulty":4,"kind":"essay","stem":"『국어』 102쪽처럼 우리말 사용과 관련해 자신이 조사하고 싶은 주제를 정하고, 조사가 필요한 까닭과 조사 방법을 쓰세요.","answer_guide":{"answer":"예: 주제 — 우리 학교 학생들이 쓰는 비속어. 조사가 필요한 까닭 — 쉬는 시간에 비속어를 듣고 기분이 상한 적이 있어서 얼마나 쓰는지, 왜 쓰는지 알아보고 싶다. 조사 방법 — 우리 반 친구들에게 설문 조사를 하고, 친구 세 명을 면담하며, 비속어의 문제점은 인터넷 기사에서 찾는다.","scoring_points":["우리말 사용과 관련 있고 직접 조사할 수 있는 주제를 정했는가","조사가 필요한 까닭을 썼는가","주제에 알맞은 조사 방법을 골랐는가"]},"explanation":["지나친 외국어, 비속어, 줄임말 사용 가운데 관심 있는 것을 골라요.","내가 겪은 일에서 조사할 까닭을 찾아요.","설문, 면담, 인터넷, 방문 조사 가운데 알맞은 것을 골라요."],"asset":{"type":"passage","lines":["[그림] 부먹(부어 먹기) · 찍먹(찍어 먹기)","주제 예 — 지나친 외국어 사용 · 비속어 사용 · 줄임말 사용","“우리말 사용과 관련한 다양한 주제를 생각해 봐요.”","“주제를 정할 때에는 자신이 관심 있는 내용을 생각해 봐요.”","보기(조사 방법) — 설문 조사 · 면담 조사 · 인터넷 조사 · 방문 조사"],"title":"조사 주제와 조사 방법 정하기 — 『국어』 102쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_b#25','kor',4,2,'u2','','tb_g4_2_kor_u2_review_b','unit_review','K4-2-u2-C30',4,'essay','teacher','『국어』 81쪽 생각 열기의 꽃집 주인은 가게 이름에 외국어를 넣으면 더 멋져 보일지 고민해요. 꽃집 주인에게 해 줄 말을 우리말을 바르게 써야 하는 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u2-C30","difficulty":4,"kind":"essay","stem":"『국어』 81쪽 생각 열기의 꽃집 주인은 가게 이름에 외국어를 넣으면 더 멋져 보일지 고민해요. 꽃집 주인에게 해 줄 말을 우리말을 바르게 써야 하는 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 사장님, 「우리 꽃집」처럼 누구나 알아보기 쉬운 우리말 이름이 더 좋아요. 우리말로 쓸 수 있는데 외국어를 넣으면 할머니, 할아버지처럼 뜻을 모르는 분들은 무슨 가게인지 알기 어려워요. 우리말을 바르게 쓰면 뜻이 정확하게 전해지고, 우리 민족의 문화유산인 우리말을 아끼는 일도 돼요.","scoring_points":["외국어를 넣는 것보다 우리말 이름을 권했는가","우리말을 바르게 써야 하는 까닭을 썼는가","꽃집 주인에게 하는 말로 알맞게 썼는가"]},"explanation":["외국어 자체보다 바꿀 수 있는데 남용하는 것이 문제예요.","의사소통, 문화유산, 나라 사랑 가운데 까닭을 골라요.","듣는 사람을 생각해 공손하게 써요."],"asset":{"type":"passage","lines":["[그림] 「우리 꽃집」 간판 앞에서 꽃집 주인이 고민하고 있다.","꽃집 주인: “가게 이름에 외국어를 넣으면 더 멋져 보일까?”","[그림] 「달콤 cafe」 앞 의자에 여자아이와 할아버지가 앉아 있다.","여자아이: “그 영상을 보고 정말 심쿵했다니까요.”","할아버지: “심쿵? 무슨 말이지?”","우리말과 우리글을 올바르게 쓰려면 어떤 노력을 해야 할까요?"],"title":"생각 열기 — 『국어』 81쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#1','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C8',1,'sa','auto','『국어』 85쪽 마무리 말이에요. 「사람들은 생각을 기록하거나 전달하려고 문자를 사용해요. 우리나라의 문자는 (     )이에요.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C8","difficulty":1,"kind":"sa","stem":"『국어』 85쪽 마무리 말이에요. 「사람들은 생각을 기록하거나 전달하려고 문자를 사용해요. 우리나라의 문자는 (     )이에요.」 빈칸에 알맞은 말을 쓰세요.","answer":["한글"],"explanation":["세계에는 여러 문자가 있어요.","우리나라에서 쓰는 문자는 한글이에요.","다음 차시에서 한글의 특성을 알아봐요."],"mis":"K4-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#2','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C11',1,'ox','auto','『국어활동』 22쪽이에요. 한글이 만들어지기 전 우리 조상은 문자를 전혀 사용하지 않았어요.',ARRAY['K4-2-u2-X08']::text[],false,'{"seq":2,"concept":"K4-2-u2-C11","difficulty":1,"kind":"ox","stem":"『국어활동』 22쪽이에요. 한글이 만들어지기 전 우리 조상은 문자를 전혀 사용하지 않았어요.","answer":"X","reason_options":[{"t":"한글이 만들어지기 전에는 중국의 문자인 한자를 빌려 우리말을 적었어요.","correct":true},{"t":"글자가 하나도 없어서 그림만 그렸어요.","mis":"K4-2-u2-X08"}],"mis":"K4-2-u2-X08","explanation":["「한글이 과학적인 문자인 까닭」 첫 문장을 떠올려요.","우리 조상은 한자를 빌려 우리말을 썼어요.","한자는 배우기 어려워 글을 모르는 백성이 많았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#3','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C12',1,'sa','auto','자음자의 기본 글자 ‘ㅅ’은 무엇의 모양을 본떴나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u2-C12","difficulty":1,"kind":"sa","stem":"자음자의 기본 글자 ‘ㅅ’은 무엇의 모양을 본떴나요? 한 낱말로 쓰세요.","answer":["이","이의 모양"],"explanation":["ㅅ을 소리 낼 때 이 사이로 바람이 나와요.","ㅅ은 이의 모양을 본떴어요.","발음 기관의 모양을 본떠 기본 글자를 만들었어요."],"mis":"K4-2-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#4','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C15',1,'mc','auto','ㅏ에 ㆍ를 한 번 더 합친 글자는 무엇인가요?',ARRAY['K4-2-u2-X11']::text[],false,'{"seq":4,"concept":"K4-2-u2-C15","difficulty":1,"kind":"mc","stem":"ㅏ에 ㆍ를 한 번 더 합친 글자는 무엇인가요?","options":[{"t":"ㅑ","correct":true},{"t":"ㅕ","mis":"K4-2-u2-X11"},{"t":"ㅛ","mis":"K4-2-u2-X11"},{"t":"ㅠ","mis":"K4-2-u2-X11"}],"explanation":["기본 글자를 한 번씩 합치면 ㅗ, ㅏ, ㅜ, ㅓ가 돼요.","여기에 ㆍ를 한 번 더 합치면 ㅛ, ㅑ, ㅠ, ㅕ가 돼요.","ㅏ에 한 번 더 합치면 ㅑ예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#5','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C23',1,'ox','auto','헐버트는 육영공원에서 가르치는 일을 그만둔 뒤에는 한글을 알리는 일도 멈추었어요.',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":5,"concept":"K4-2-u2-C23","difficulty":1,"kind":"ox","stem":"헐버트는 육영공원에서 가르치는 일을 그만둔 뒤에는 한글을 알리는 일도 멈추었어요.","answer":"X","reason_options":[{"t":"그 뒤에도 한글을 소개하는 글을 쓰고 영문자 신문 만들기에 참여했어요.","correct":true},{"t":"교사를 그만두면서 한글과의 관계도 끝났어요.","mis":"K4-2-u2-X18"}],"mis":"K4-2-u2-X18","explanation":["「한글을 널리 알리려는 헐버트의 노력은 멈추지 않았습니다.」라고 했어요.","한글과 영어 자모를 비교하는 글도 썼어요.","그래서 ‘한글을 사랑한 벗’이라고 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#6','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C32',1,'mc','auto','『국어』 96쪽 자료 ㉯의 ‘심쿵’, ‘열공’은 어떤 말인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X28']::text[],false,'{"seq":6,"concept":"K4-2-u2-C32","difficulty":1,"kind":"mc","stem":"『국어』 96쪽 자료 ㉯의 ‘심쿵’, ‘열공’은 어떤 말인가요?","options":[{"t":"말을 줄여 쓴 줄임말","correct":true},{"t":"바꿔 쓸 우리말이 없는 외국어","mis":"K4-2-u2-X24"},{"t":"상대를 탓하는 거친 말","mis":"K4-2-u2-X28"}],"explanation":["‘열공’은 ‘열심히 공부함’을 줄인 말이에요.","줄임말은 뜻을 모르는 사람과 대화하기 어렵게 해요.","듣는 사람과 상황을 살펴 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#7','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C37',1,'mc','auto','책, 통계 자료, 연구물 같은 문헌에서 조사 주제와 관련한 자료를 모으는 조사 방법은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":7,"concept":"K4-2-u2-C37","difficulty":1,"kind":"mc","stem":"책, 통계 자료, 연구물 같은 문헌에서 조사 주제와 관련한 자료를 모으는 조사 방법은 무엇인가요?","options":[{"t":"문헌 조사","correct":true},{"t":"방문 조사","mis":"K4-2-u2-X33"},{"t":"면담 조사","mis":"K4-2-u2-X33"}],"explanation":["문헌은 책이나 자료 같은 글을 말해요.","문헌에서 자료를 찾는 것이 문헌 조사예요.","방문 조사는 관련 있는 곳에 직접 가는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#8','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C55',1,'ox','auto','「줄넘기를 잘하기 위한 팁」에서 ‘팁’은 ‘도움말’로 바꾸어 쓸 수 있어요.',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":8,"concept":"K4-2-u2-C55","difficulty":1,"kind":"ox","stem":"「줄넘기를 잘하기 위한 팁」에서 ‘팁’은 ‘도움말’로 바꾸어 쓸 수 있어요.","answer":"O","reason_options":[{"t":"‘팁’은 우리말 ‘도움말’로 바꾸어 쓸 수 있는 외국어예요.","correct":true},{"t":"‘팁’은 바꿔 쓸 우리말이 없어요.","mis":"K4-2-u2-X19"}],"mis":"K4-2-u2-X19","explanation":["『국어』 110쪽 2번의 내용이에요.","‘팁’은 ‘도움말’, ‘컬러’는 ‘색깔’로 바꿀 수 있어요.","우리말이 있으면 우리말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#9','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C6',2,'mc','auto','문자가 없으면 불편한 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u2-X05']::text[],false,'{"seq":9,"concept":"K4-2-u2-C6","difficulty":2,"kind":"mc","stem":"문자가 없으면 불편한 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"마주 앉은 친구와 이야기를 나눌 수 없다","correct":true},{"t":"지난 일을 정확하게 알기 어렵다","mis":"K4-2-u2-X05"},{"t":"멀리 있는 사람에게 생각을 전하기 어렵다","mis":"K4-2-u2-X05"},{"t":"해야 할 일을 잊기 쉽다","mis":"K4-2-u2-X05"}],"explanation":["마주 보고 하는 이야기는 말로 할 수 있어요.","지난 일, 먼 곳, 기억해야 할 일은 문자가 있어야 편해요.","문자는 시간, 거리, 기억의 한계를 넘게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#10','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C16',2,'mc','auto','ㄱ, ㅋ, ㄲ을 보고 알 수 있는 한글의 특성은 무엇인가요?',ARRAY['K4-2-u2-X12','K4-2-u2-X09']::text[],false,'{"seq":10,"concept":"K4-2-u2-C16","difficulty":2,"kind":"mc","stem":"ㄱ, ㅋ, ㄲ을 보고 알 수 있는 한글의 특성은 무엇인가요?","options":[{"t":"비슷한 소리를 내는 글자는 모양도 비슷하다","correct":true},{"t":"소리가 비슷해도 모양은 아주 다르다","mis":"K4-2-u2-X12"},{"t":"세 글자는 모두 모음자이다","mis":"K4-2-u2-X09"}],"explanation":["ㄱ, ㅋ, ㄲ은 소리가 비슷해요.","모양도 서로 닮았어요.","영어의 K와 G는 소리가 비슷해도 모양이 아주 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#11','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C19',2,'ox','auto','문단의 중심 내용을 간추릴 때에는 그 문단에 나온 예를 하나 골라 쓰면 돼요.',ARRAY['K4-2-u2-X55']::text[],false,'{"seq":11,"concept":"K4-2-u2-C19","difficulty":2,"kind":"ox","stem":"문단의 중심 내용을 간추릴 때에는 그 문단에 나온 예를 하나 골라 쓰면 돼요.","answer":"X","reason_options":[{"t":"문단의 문장들을 모두 묶는 내용을 중심 내용으로 써야 해요.","correct":true},{"t":"예를 하나만 써도 문단 전체를 나타낼 수 있어요.","mis":"K4-2-u2-X55"}],"mis":"K4-2-u2-X55","explanation":["예는 중심 내용을 뒷받침하는 문장이에요.","「ㅁ은 입의 모양」은 셋째 문단의 예 하나예요.","「기본 글자를 어떻게 만들었는지」처럼 묶는 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#12','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C27',2,'ox','auto','한글 사랑은 한글학자나 임금처럼 대단한 사람만 할 수 있어요.',ARRAY['K4-2-u2-X21']::text[],false,'{"seq":12,"concept":"K4-2-u2-C27","difficulty":2,"kind":"ox","stem":"한글 사랑은 한글학자나 임금처럼 대단한 사람만 할 수 있어요.","answer":"X","reason_options":[{"t":"모르는 낱말 사전 찾기처럼 내 생활에서도 한글 사랑을 할 수 있어요.","correct":true},{"t":"나 같은 학생은 한글 사랑과 상관없어요.","mis":"K4-2-u2-X21"}],"mis":"K4-2-u2-X21","explanation":["한글을 사랑하고 지켜 나가는 것은 지금의 우리에게도 주어진 몫이에요.","받침까지 바르게 쓰는 것도 한글 사랑이에요.","작은 실천이 모여 한글을 가꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#13','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C29',2,'mc','auto','우리말은 우리 민족의 얼이 담긴 무엇이라서 소중하게 여겨야 하나요?',ARRAY['K4-2-u2-X29','K4-2-u2-X25']::text[],false,'{"seq":13,"concept":"K4-2-u2-C29","difficulty":2,"kind":"mc","stem":"우리말은 우리 민족의 얼이 담긴 무엇이라서 소중하게 여겨야 하나요?","options":[{"t":"문화유산","correct":true},{"t":"외국 문화","mis":"K4-2-u2-X29"},{"t":"유행어","mis":"K4-2-u2-X25"}],"explanation":["우리말은 조상에게서 이어받은 것이에요.","우리 민족의 얼이 담긴 문화유산이에요.","아끼고 바르게 써서 다음 사람에게 물려주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#14','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C43',2,'mc','auto','지후의 보고하는 글에서 「조사 소감」에 쓴 내용은 무엇인가요?',ARRAY['K4-2-u2-X39']::text[],false,'{"seq":14,"concept":"K4-2-u2-C43","difficulty":2,"kind":"mc","stem":"지후의 보고하는 글에서 「조사 소감」에 쓴 내용은 무엇인가요?","options":[{"t":"많은 친구가 줄임말을 사용하고 있어서 놀라웠다","correct":true},{"t":"열여덟 명이 줄임말을 자주 사용했다","mis":"K4-2-u2-X39"},{"t":"줄임말은 학년이 올라갈수록 더 많이 사용한다","mis":"K4-2-u2-X39"}],"explanation":["조사 소감에는 조사하고 나서 든 생각을 써요.","열여덟 명은 설문 조사 결과라 조사한 내용에 들어가요.","학년 이야기는 인터넷 조사 결과예요."],"asset":{"type":"passage","lines":["인터넷 뉴스 기사에서 조사해 보니 줄임말은 학년이 올라갈수록,","하루에 한 시간 이상 컴퓨터나 휴대 전화를 쓸수록 더 많이 사용했다.","또 줄임말을 자주 쓰면 맞춤법과 어휘 실력이 낮아질 수 있다는 점도 알았다.","조사 소감 — 많은 친구가 줄임말을 사용하고 있어서 놀라웠다.","바른 언어생활을 하도록 노력해야겠다고 생각했다.","참고 자료와 그 출처 — ○○○ 기자, 「줄임말로 대화하는 초등학생」,","『○○일보』, 20○○. ○○. ○○."],"title":"지후가 쓴 보고하는 글 ③ — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#15','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C46',2,'mc','auto','지후의 그래프는 메신저 8명, 인터넷 5명, 일상 대화 3명, 게임 2명이에요. 「일상 대화에서 줄임말을 쓰는 친구가 가장 많았다.」라고 쓰면 어떤 잘못인가요?',ARRAY['K4-2-u2-X40','K4-2-u2-X56']::text[],false,'{"seq":15,"concept":"K4-2-u2-C46","difficulty":2,"kind":"mc","stem":"지후의 그래프는 메신저 8명, 인터넷 5명, 일상 대화 3명, 게임 2명이에요. 「일상 대화에서 줄임말을 쓰는 친구가 가장 많았다.」라고 쓰면 어떤 잘못인가요?","options":[{"t":"조사 결과를 거꾸로 옮긴 것","correct":true},{"t":"조사한 그대로 옮긴 것","mis":"K4-2-u2-X40"},{"t":"조사 결과를 줄여 쓴 것","mis":"K4-2-u2-X56"}],"explanation":["그래프에서 가장 많은 것은 메신저 8명이에요.","일상 대화는 3명이라 가장 많지 않아요.","조사 결과는 그래프와 견주어 그대로 옮겨요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#16','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C51',2,'ox','auto','우리 동네 간판을 조사한 뒤, 외국어 간판을 단 가게는 나쁜 가게라고 결과에 써요.',ARRAY['K4-2-u2-X46']::text[],false,'{"seq":16,"concept":"K4-2-u2-C51","difficulty":2,"kind":"ox","stem":"우리 동네 간판을 조사한 뒤, 외국어 간판을 단 가게는 나쁜 가게라고 결과에 써요.","answer":"X","reason_options":[{"t":"살펴보는 것은 가게가 아니라 간판에 쓰인 말이에요.","correct":true},{"t":"외국어 간판을 단 가게는 물건도 나빠요.","mis":"K4-2-u2-X46"}],"mis":"K4-2-u2-X46","explanation":["간판 조사는 우리말 사용을 알아보는 조사예요.","우리말 간판과 외국어 간판으로 조사한 그대로 나누어요.","가게가 좋고 나쁨은 조사한 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#17','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C18',3,'error','auto','친구들이 한글에 대해 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X17']::text[],false,'{"seq":17,"concept":"K4-2-u2-C18","difficulty":3,"kind":"error","stem":"친구들이 한글에 대해 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태오: 한글이 최고라서 영어 알파벳은 배울 가치가 없어.","correct":true,"mis_target":"K4-2-u2-X16"},{"t":"지민: 한글은 적은 수의 글자로 누구나 우리말을 읽고 쓸 수 있어.","mis":"K4-2-u2-X17"},{"t":"서아: 한글은 비슷한 소리를 비슷한 모양으로 나타내.","mis":"K4-2-u2-X17"}],"explanation":["한글의 좋은 점은 한글 자체의 짜임새에 있어요.","다른 나라 글자도 저마다 자기 말을 적어 왔어요.","다른 글자를 깎아내리지 않고 한글을 자랑스러워해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#18','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C24',3,'ox','auto','헐버트가 『사민필지』를 언문으로 쓴 것은 누구나 세계 여러 나라에 대해 알아야 한다고 생각했기 때문이에요.',ARRAY['K4-2-u2-X20']::text[],false,'{"seq":18,"concept":"K4-2-u2-C24","difficulty":3,"kind":"ox","stem":"헐버트가 『사민필지』를 언문으로 쓴 것은 누구나 세계 여러 나라에 대해 알아야 한다고 생각했기 때문이에요.","answer":"O","reason_options":[{"t":"신분이나 남녀를 가리지 않고 많은 사람이 읽게 하려고 언문으로 썼어요.","correct":true},{"t":"한문을 쓸 줄 몰라 어쩔 수 없이 언문으로 썼어요.","mis":"K4-2-u2-X20"}],"mis":"K4-2-u2-X20","explanation":["헐버트는 한문으로 쓰면 많은 사람이 읽을 수 없다고 했어요.","언문은 누구든 가리지 않고 읽을 수 있어요.","누구나 세계를 알아야 한다는 생각이 담긴 행동이에요."],"asset":{"type":"passage","lines":["(간추림) 그때는 한글보다 한자를 주로 써서 공식 문서와 책은 대부분 한자였다.","(간추림) 헐버트는 사람들이 한글의 소중함을 잘 모른다는 생각에 답답했다.","(간추림) 그래서 세계의 지리와 문화를 소개하는 『사민필지』를 한글로 썼다.","“다른 나라에 대해 알 수 있는 정말 유익한 책이오.","그런데 이렇게 좋은 책을 왜 한문이 아닌 언문으로 썼소?”","“한문으로 쓰면 한문을 모르는 많은 사람이 이 책을 읽을 수가 없습니다.","(간추림) 언문은 이 나라 고유의 글자로 신분과 남녀를 가리지 않고 누구나 읽지요.”","※ 언문: 예전에 ‘한글’을 이르던 말."],"title":"「한글을 사랑한 외국인, 헐버트」 가운데 — 『국어』 91~92쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#19','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C30',3,'error','auto','친구들이 간판에 쓰인 외국어에 대해 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":19,"concept":"K4-2-u2-C30","difficulty":3,"kind":"error","stem":"친구들이 간판에 쓰인 외국어에 대해 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도하: 외국에서 온 말이 들어간 이름은 모두 잘못이니 버스 정류장까지 이름을 바꿔야 해.","correct":true,"mis_target":"K4-2-u2-X24"},{"t":"유나: 우리말로 쓸 수 있는 간판 이름은 우리말로 쓰면 좋겠어.","mis":"K4-2-u2-X25"},{"t":"건우: 알맞은 우리말이 없는 말은 억지로 바꾸지 않아도 돼.","mis":"K4-2-u2-X25"}],"explanation":["문제는 우리말로 대체할 수 있는데 외국어를 남용하는 것이에요.","버스처럼 굳은 말까지 바꿀 필요는 없어요.","무리하게 새말을 만들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#20','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C42',3,'ox','auto','인터넷에서 찾은 자료는 누구나 볼 수 있으니 출처를 밝히지 않아도 돼요.',ARRAY['K4-2-u2-X37']::text[],false,'{"seq":20,"concept":"K4-2-u2-C42","difficulty":3,"kind":"ox","stem":"인터넷에서 찾은 자료는 누구나 볼 수 있으니 출처를 밝히지 않아도 돼요.","answer":"X","reason_options":[{"t":"인터넷 자료도 누가 만든 어떤 자료인지 출처를 밝혀야 해요.","correct":true},{"t":"인터넷 자료는 모두의 것이라 그냥 써도 돼요.","mis":"K4-2-u2-X37"}],"mis":"K4-2-u2-X37","explanation":["인터넷 조사를 할 때에는 출처가 분명한 자료인지 확인해요.","옮겨 쓸 때에는 출처를 밝히고 올바르게 인용해요.","누리집 이름과 찾아본 날을 적어 두면 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#21','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C38',3,'mc','auto','방문 조사로 알아보기에 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":21,"concept":"K4-2-u2-C38","difficulty":3,"kind":"mc","stem":"방문 조사로 알아보기에 가장 알맞은 것은 무엇인가요?","options":[{"t":"학교 앞 상가 간판에 쓰인 말","correct":true},{"t":"친구들이 줄임말을 쓰는 까닭","mis":"K4-2-u2-X33"},{"t":"줄임말이 맞춤법 실력에 끼치는 영향","mis":"K4-2-u2-X33"}],"explanation":["방문 조사는 조사 주제와 관련 있는 곳에 직접 가는 방법이에요.","간판은 직접 가서 보고 사진을 찍을 수 있어요.","까닭은 면담, 영향은 인터넷이나 문헌 조사가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#22','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C47',3,'mc','auto','지후의 보고하는 글을 처음·가운데·끝으로 나누었어요. 「가운데」에 들어가는 것은 무엇인가요?',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":22,"concept":"K4-2-u2-C47","difficulty":3,"kind":"mc","stem":"지후의 보고하는 글을 처음·가운데·끝으로 나누었어요. 「가운데」에 들어가는 것은 무엇인가요?","options":[{"t":"설문·면담·인터넷 조사로 알아낸 내용과 줄임말을 쓰는 상황 그래프","correct":true},{"t":"초등학생이 줄임말을 지나치게 사용한다는 기사를 보고 조사하게 된 까닭","mis":"K4-2-u2-X44"},{"t":"바른 언어생활을 하도록 노력해야겠다는 생각","mis":"K4-2-u2-X44"}],"explanation":["처음에는 제목, 조사 대상, 기간, 동기, 방법을 써요.","가운데에는 조사한 내용과 그래프 같은 매체 자료를 써요.","조사하고 든 생각은 끝의 조사 소감에 써요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#23','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C26',4,'essay','teacher','평가 자료 「나만의 한글책」이에요. 「한글 사랑을 실천한 사람들이 한 일을 정리해 봐요」 쪽에 두 사람이 한 일을 쓰고, 두 사람의 공통점을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u2-C26","difficulty":4,"kind":"essay","stem":"평가 자료 「나만의 한글책」이에요. 「한글 사랑을 실천한 사람들이 한 일을 정리해 봐요」 쪽에 두 사람이 한 일을 쓰고, 두 사람의 공통점을 쓰세요.","answer_guide":{"answer":"예: 헐버트 — 『사민필지』를 한글로 써서 누구나 세계를 알 수 있게 했고, 한글의 과학성을 세계에 알렸다. 주시경 — 우리말과 한글을 연구하고 제자들과 함께 최초의 국어사전 원고를 썼다. 공통점 — 방법은 달랐지만 한글을 아끼고 지키려고 자신이 할 수 있는 일을 했다.","scoring_points":["두 인물이 한 일을 바르게 썼는가","공통점을 한 일의 겉모습이 아닌 마음에서 찾았는가","문장으로 정리해 썼는가"]},"explanation":["5~6차시에 배운 헐버트와 주시경을 떠올려요.","세종 대왕, 공병우, 박두성, 최정호를 써도 좋아요.","방법은 달라도 같은 마음을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#24','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C46',4,'essay','teacher','『국어』 103쪽 (1)·(2)처럼 지후가 조사한 내용(설문·면담·인터넷)을 간추리고, 보고하는 글에 활용할 매체 자료와 참고 자료와 그 출처를 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C46","difficulty":4,"kind":"essay","stem":"『국어』 103쪽 (1)·(2)처럼 지후가 조사한 내용(설문·면담·인터넷)을 간추리고, 보고하는 글에 활용할 매체 자료와 참고 자료와 그 출처를 정리하세요.","answer_guide":{"answer":"예: 간추린 내용 — 설문 조사: 20명 가운데 열여덟 명이 줄임말을 자주 사용하며, 메신저(8명)에서 가장 많이 쓴다. 면담 조사: 짧아서 쓰기 편하고, 습관이 되었고, 다른 친구들이 많이 사용해서 쓴다. 인터넷 조사: 학년이 올라갈수록, 컴퓨터나 휴대 전화를 오래 쓸수록 더 많이 쓰고, 맞춤법과 어휘 실력이 낮아질 수 있다. 매체 자료 — 줄임말을 쓰는 상황별 사람 수 막대그래프. 출처 — ○○○ 기자, 「줄임말로 대화하는 초등학생」, 『○○일보』, 발행 일자.","scoring_points":["조사 방법마다 알아낸 것을 부풀리거나 줄이지 않고 간추렸는가","조사한 내용에 알맞은 매체 자료를 정했는가","참고 자료와 그 출처를 기자 이름·제목·발행한 곳·날짜까지 정리했는가"]},"explanation":["중요한 내용 위주로 조사한 사실이 잘 드러나게 간추려요.","면담에서 들은 까닭 세 가지를 모두 옮겨요.","표, 그림, 사진, 그래프 가운데 알맞은 것을 골라요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 열여덟 명이 줄임말을 자주 사용했다.","주로 ‘생파(생일 파티)’, ‘엄빠(엄마, 아빠)’, ‘깜놀(깜짝 놀라다)’을","메신저와 인터넷에서 많이 사용했다.","[그래프] 줄임말을 쓰는 상황(명) — 메신저 8, 인터넷 5, 일상 대화 3, 게임 2","친구들을 면담한 결과, 짧아서 쓰기 편하고 습관이 되었으며","다른 친구들이 많이 사용하기 때문에 줄임말을 사용한다고 말했다."],"title":"지후가 쓴 보고하는 글 ② — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_c#25','kor',4,2,'u2','','tb_g4_2_kor_u2_review_c','unit_review','K4-2-u2-C1',4,'mc','auto','이 단원의 소단원 1(한글을 사랑하는 마음 지니기)과 소단원 2(우리말 사용에 대하여 보고하는 글 쓰기)의 관계를 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u2-X53','K4-2-u2-X22','K4-2-u2-X41']::text[],false,'{"seq":25,"concept":"K4-2-u2-C1","difficulty":4,"kind":"mc","stem":"이 단원의 소단원 1(한글을 사랑하는 마음 지니기)과 소단원 2(우리말 사용에 대하여 보고하는 글 쓰기)의 관계를 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"한글의 소중함을 알고 나서, 생활 속 우리말 사용을 조사해 바르게 쓰려는 태도로 이어진다","correct":true},{"t":"두 소단원은 서로 관계가 없다","mis":"K4-2-u2-X53"},{"t":"한글 사랑은 외국어를 모두 금지하는 것이라 보고하는 글로 외국어를 쓴 사람을 찾아낸다","mis":"K4-2-u2-X22"},{"t":"보고하는 글은 한글 사랑과 상관없이 길게만 쓰면 되는 글이다","mis":"K4-2-u2-X41"}],"explanation":["소단원 1에서 문자와 한글의 가치를 알고 한글을 사랑하는 마음을 지녀요.","소단원 2에서 우리말 사용을 조사해 보고하는 글을 써요.","배운 내용이 내 언어생활을 돌아보고 바꾸는 데로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#1','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C8',1,'mc','auto','『국어』 85쪽 그림 ㉰처럼 휴대 전화로 글을 써서 보낼 때 문자가 하는 역할은 무엇인가요?',ARRAY['K4-2-u2-X05']::text[],false,'{"seq":1,"concept":"K4-2-u2-C8","difficulty":1,"kind":"mc","stem":"『국어』 85쪽 그림 ㉰처럼 휴대 전화로 글을 써서 보낼 때 문자가 하는 역할은 무엇인가요?","options":[{"t":"멀리 떨어진 사람에게 생각을 전한다","correct":true},{"t":"과거에 어떤 일이 있었는지 알 수 있게 한다","mis":"K4-2-u2-X05"},{"t":"내용을 정확하게 기억하도록 돕는다","mis":"K4-2-u2-X05"}],"explanation":["글을 보내면 멀리 있는 사람도 내 생각을 알 수 있어요.","㉮는 지난 일 알기, ㉯는 기억 돕기예요.","문자는 거리와 시간을 넘어 생각을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#2','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C11',1,'mc','auto','한글 사랑 말판 놀이 문제예요. 한글의 옛 이름은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":2,"concept":"K4-2-u2-C11","difficulty":1,"kind":"mc","stem":"한글 사랑 말판 놀이 문제예요. 한글의 옛 이름은 무엇인가요?","options":[{"t":"훈민정음","correct":true},{"t":"사민필지","mis":"K4-2-u2-X18"},{"t":"훈맹정음","mis":"K4-2-u2-X18"}],"explanation":["세종 대왕이 만든 글자의 이름은 훈민정음이에요.","「백성을 가르치는 바른 소리」라는 뜻이에요.","『사민필지』는 헐버트가 쓴 책, 훈맹정음은 한글 점자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#3','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C12',1,'mc','auto','한글 자음자의 기본 글자를 알맞게 묶은 것은 무엇인가요?',ARRAY['K4-2-u2-X10','K4-2-u2-X09']::text[],false,'{"seq":3,"concept":"K4-2-u2-C12","difficulty":1,"kind":"mc","stem":"한글 자음자의 기본 글자를 알맞게 묶은 것은 무엇인가요?","options":[{"t":"ㄱ, ㄴ, ㅁ, ㅅ, ㅇ","correct":true},{"t":"ㄱ, ㄷ, ㅂ, ㅈ, ㅎ","mis":"K4-2-u2-X10"},{"t":"ㆍ, ㅡ, ㅣ","mis":"K4-2-u2-X09"}],"explanation":["자음자의 기본 글자는 ㄱ, ㄴ, ㅁ, ㅅ, ㅇ이에요.","나머지 자음자는 여기에 획을 더해 만들었어요.","ㆍ, ㅡ, ㅣ는 모음자의 기본 글자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#4','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C13',1,'mc','auto','기본 글자에 획을 더해 만든 자음자를 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":4,"concept":"K4-2-u2-C13","difficulty":1,"kind":"mc","stem":"기본 글자에 획을 더해 만든 자음자를 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"ㅁ → ㅂ → ㅍ","correct":true},{"t":"ㄷ → ㄹ → ㅁ","mis":"K4-2-u2-X10"},{"t":"ㅂ → ㅁ → ㅇ","mis":"K4-2-u2-X10"}],"explanation":["ㅁ에 획을 더하면 ㅂ, 또 더하면 ㅍ이 돼요.","획이 늘수록 소리가 더 강해져요.","ㄹ은 ㄷ에 획을 더한 글자가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#5','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C23',1,'mc','auto','헐버트가 쓴 『사민필지』에는 어떤 내용이 담겨 있었나요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":5,"concept":"K4-2-u2-C23","difficulty":1,"kind":"mc","stem":"헐버트가 쓴 『사민필지』에는 어떤 내용이 담겨 있었나요?","options":[{"t":"세계 지도와 각 나라의 땅 모양, 특징, 제도, 문화","correct":true},{"t":"한글 자음자와 모음자를 만드는 방법","mis":"K4-2-u2-X18"},{"t":"조선의 옛이야기와 동시","mis":"K4-2-u2-X18"}],"explanation":["『사민필지』는 세계의 지리와 문화를 소개한 책이에요.","우리나라를 기준으로 다른 나라를 쉽게 설명했어요.","그 뒤 전국의 학교에서 세계 지리 교재로 쓰였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#6','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C30',1,'ox','auto','「Hello 마트」처럼 우리말로 쓸 수 있는데도 외국어를 쓴 간판은 우리말 사용과 관련한 문제점이에요.',ARRAY['K4-2-u2-X25']::text[],false,'{"seq":6,"concept":"K4-2-u2-C30","difficulty":1,"kind":"ox","stem":"「Hello 마트」처럼 우리말로 쓸 수 있는데도 외국어를 쓴 간판은 우리말 사용과 관련한 문제점이에요.","answer":"O","reason_options":[{"t":"우리말로 대체할 수 있는데 외국어를 남용한 것이 문제예요.","correct":true},{"t":"외국어를 쓰면 더 멋지니 문제가 아니에요.","mis":"K4-2-u2-X25"}],"mis":"K4-2-u2-X25","explanation":["『국어』 97쪽 1번 (1)의 내용이에요.","외국어를 쓰는 것 자체보다 지나치게 쓰는 것이 문제예요.","우리말로 쓸 수 있으면 우리말을 먼저 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#7','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C36',1,'sa','auto','지후가 조사한 대상은 4학년 ○반 학생 몇 명인가요? 수로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u2-C36","difficulty":1,"kind":"sa","stem":"지후가 조사한 대상은 4학년 ○반 학생 몇 명인가요? 수로 쓰세요.","answer":["20","20명","스무 명"],"explanation":["조사 대상 칸을 보아요.","「4학년 ○반 학생 20명」이라고 했어요.","보고하는 글에는 조사 대상을 분명하게 밝혀요."],"asset":{"type":"passage","lines":["제목 — 우리 반 친구들의 줄임말 사용","조사 대상 — 4학년 ○반 학생 20명","조사 기간 — 20○○년 ○○월 ○○일~○○월 ○○일","조사 동기 — 초등학생이 줄임말을 지나치게 사용한다는 기사를 보고","우리 반 친구들의 줄임말 사용에 대하여 조사해 보고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 인터넷 조사"],"title":"지후가 쓴 보고하는 글 ① — 『국어』 98쪽"},"mis":"K4-2-u2-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#8','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C52',1,'sa','auto','「공간이 넓지 않으니까」에서 ‘넓지’는 어떻게 발음하나요? 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C52","difficulty":1,"kind":"sa","stem":"「공간이 넓지 않으니까」에서 ‘넓지’는 어떻게 발음하나요? 소리 나는 대로 쓰세요.","answer":["널찌","[널찌]"],"explanation":["‘넓지’의 ㄼ은 [ㄹ]로 소리 나요.","뒤의 ㅈ은 [ㅉ]으로 소리 나요.","그래서 [넙찌]가 아니라 [널찌]예요."],"mis":"K4-2-u2-X48"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#9','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C9',2,'mc','auto','「문자 이야기」에서 인쇄 기술의 발전이 사람들에게 끼친 영향은 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X04']::text[],false,'{"seq":9,"concept":"K4-2-u2-C9","difficulty":2,"kind":"mc","stem":"「문자 이야기」에서 인쇄 기술의 발전이 사람들에게 끼친 영향은 무엇인가요?","options":[{"t":"문자로 쓰인 책을 대량으로 빨리 만들어 누구든 책을 읽고 지식을 쌓게 되었다","correct":true},{"t":"책을 손으로 한 권씩만 베껴 쓰게 되었다","mis":"K4-2-u2-X05"},{"t":"문자 대신 그림으로만 기록하게 되었다","mis":"K4-2-u2-X04"}],"explanation":["『국어』 84쪽 2번 (2)의 물음이에요.","인쇄 기술로 책을 많이, 빨리 만들 수 있게 되었어요.","더 많은 사람이 책을 읽고 지식을 쌓을 수 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#10','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C16',2,'match','auto','한글이 과학적인 문자인 까닭과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C16","difficulty":2,"kind":"match","stem":"한글이 과학적인 문자인 까닭과 그 예를 알맞게 이으세요.","pairs":[{"l":"본뜬 대상이 정확하게 알려져 있다.","r":"ㅁ은 입의 모양을 본떴다."},{"l":"기본 글자를 확장해 다른 글자를 만들었다.","r":"ㅣ와 ㆍ를 합쳐 ㅏ를 만들었다."},{"l":"소리와 글자가 규칙적으로 연결된다.","r":"ㄱ, ㅋ, ㄲ은 소리도 모양도 비슷하다."}],"mis":"K4-2-u2-X12","explanation":["셋째 문단은 본뜬 대상을 설명해요.","넷째 문단은 획을 더하고 합쳐 만든 글자를 설명해요.","다섯째 문단은 소리와 글자의 규칙을 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#11','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C19',2,'mc','auto','「한글이 과학적인 문자인 까닭」 여섯째 문단의 중심 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X55']::text[],false,'{"seq":11,"concept":"K4-2-u2-C19","difficulty":2,"kind":"mc","stem":"「한글이 과학적인 문자인 까닭」 여섯째 문단의 중심 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"한글은 과학적인 문자이기 때문에 사람들이 쉽게 배우고 편하게 쓸 수 있다","correct":true},{"t":"영어의 K와 G는 모양이 아주 다르다","mis":"K4-2-u2-X55"},{"t":"‘ㆍ’는 오늘날 거의 쓰이지 않는다","mis":"K4-2-u2-X55"}],"explanation":["여섯째 문단은 글을 마무리하는 문단이에요.","앞의 내용을 요약하고 한글의 과학성 덕분에 쉽게 배우고 편하게 쓴다고 했어요.","K와 G, ㆍ 이야기는 다른 문단의 자잘한 내용이에요."],"asset":{"type":"passage","lines":["(간추림) 이처럼 한글은 한국어의 말소리를 잘 나타내도록 체계적으로 만든 문자이다.","한글의 과학성 덕분에 사람들은 한글을 쉽게 배우고 편하게 쓸 수 있습니다."],"title":"「한글이 과학적인 문자인 까닭」 6문단 — 『국어』 87쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#12','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C27',2,'mc','auto','한글 사랑을 실천하는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u2-X22']::text[],false,'{"seq":12,"concept":"K4-2-u2-C27","difficulty":2,"kind":"mc","stem":"한글 사랑을 실천하는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"외국어를 한마디라도 쓰는 친구를 놀린다","correct":true},{"t":"받침까지 바르게 쓴다","mis":"K4-2-u2-X22"},{"t":"우리말로 바꿀 수 있는 말은 우리말로 쓴다","mis":"K4-2-u2-X22"},{"t":"한글의 특성을 알리는 만화를 그린다","mis":"K4-2-u2-X22"}],"explanation":["한글 사랑은 남을 꾸짖거나 놀리는 일이 아니에요.","내가 우리말을 바르게 쓰고 아끼는 데서 시작해요.","『국어』 109쪽 생활 속으로의 실천도 좋은 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#13','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C29',2,'sa','auto','『국어』 97쪽 친구의 말이에요. 「우리말을 바르게 써야 우리나라를 사랑하는 (     )도 기를 수 있기 때문이야.」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"K4-2-u2-C29","difficulty":2,"kind":"sa","stem":"『국어』 97쪽 친구의 말이에요. 「우리말을 바르게 써야 우리나라를 사랑하는 (     )도 기를 수 있기 때문이야.」 빈칸에 알맞은 낱말을 쓰세요.","answer":["마음"],"explanation":["우리말을 바르게 쓰는 것은 나라 사랑과 이어져요.","빈칸에는 「마음」이 들어가요.","정확한 의사소통, 문화유산, 좋은 관계도 까닭이에요."],"mis":"K4-2-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#14','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C37',2,'ox','auto','지후는 보고하는 글을 쓰려고 설문 조사, 면담 조사, 인터넷 조사를 모두 했어요.',ARRAY['K4-2-u2-X32']::text[],false,'{"seq":14,"concept":"K4-2-u2-C37","difficulty":2,"kind":"ox","stem":"지후는 보고하는 글을 쓰려고 설문 조사, 면담 조사, 인터넷 조사를 모두 했어요.","answer":"O","reason_options":[{"t":"조사할 내용마다 알맞은 방법을 골라 세 가지를 썼어요.","correct":true},{"t":"보고하는 글에는 조사 방법을 한 가지만 써야 해요.","mis":"K4-2-u2-X32"}],"mis":"K4-2-u2-X32","explanation":["조사 방법 칸에 세 가지가 적혀 있어요.","상황은 설문, 까닭은 면담, 특징과 문제점은 인터넷으로 알아보았어요.","알맞으면 여러 방법을 함께 쓸 수 있어요."],"asset":{"type":"passage","lines":["제목 — 우리 반 친구들의 줄임말 사용","조사 대상 — 4학년 ○반 학생 20명","조사 기간 — 20○○년 ○○월 ○○일~○○월 ○○일","조사 동기 — 초등학생이 줄임말을 지나치게 사용한다는 기사를 보고","우리 반 친구들의 줄임말 사용에 대하여 조사해 보고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 인터넷 조사"],"title":"지후가 쓴 보고하는 글 ① — 『국어』 98쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#15','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C41',2,'blank','auto','보고서 평가 기준이에요. 「관찰, 조사, 실험한 결과를 과장, (     ), 변형, 왜곡하지 않고 제시했는가?」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X56','K4-2-u2-X37','K4-2-u2-X43']::text[],false,'{"seq":15,"concept":"K4-2-u2-C41","difficulty":2,"kind":"blank","stem":"보고서 평가 기준이에요. 「관찰, 조사, 실험한 결과를 과장, (     ), 변형, 왜곡하지 않고 제시했는가?」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"축소","correct":true},{"t":"요약","mis":"K4-2-u2-X56"},{"t":"출처","mis":"K4-2-u2-X37"},{"t":"그래프","mis":"K4-2-u2-X43"}],"explanation":["보고하는 글은 쓰기 윤리를 지켜야 해요.","결과를 부풀리는 과장도, 줄이는 축소도 하지 않아요.","지후의 메모 ㉠은 과장, ㉢은 축소에 해당해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#16','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C49',2,'mc','auto','주제어 「세종 대왕」으로 4행시를 쓰려고 해요. 각 행을 시작하는 글자의 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X58']::text[],false,'{"seq":16,"concept":"K4-2-u2-C49","difficulty":2,"kind":"mc","stem":"주제어 「세종 대왕」으로 4행시를 쓰려고 해요. 각 행을 시작하는 글자의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"세 — 종 — 대 — 왕","correct":true},{"t":"세 — 대 — 종 — 왕","mis":"K4-2-u2-X58"},{"t":"왕 — 대 — 종 — 세","mis":"K4-2-u2-X58"}],"explanation":["주제어의 글자를 차례대로 각 행의 첫 글자로 써요.","「세종 대왕」은 세, 종, 대, 왕 네 글자예요.","그래서 4행시가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#17','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C18',3,'mc','auto','친구들에게 한글의 특성을 설명하려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X17']::text[],false,'{"seq":17,"concept":"K4-2-u2-C18","difficulty":3,"kind":"mc","stem":"친구들에게 한글의 특성을 설명하려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"다른 문자를 깎아내리기보다 한글 자체가 만들어진 원리를 설명한다","correct":true},{"t":"다른 나라 글자의 나쁜 점을 많이 찾아 견준다","mis":"K4-2-u2-X16"},{"t":"글자는 다 같으니 한글의 특성은 설명하지 않는다","mis":"K4-2-u2-X17"}],"explanation":["한글은 본뜬 대상, 확장한 방법, 소리와 글자의 규칙이 분명해요.","이것은 한글 자체가 가진 독창성이에요.","다른 문자와 견주어 낮추는 말은 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#18','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C24',3,'mc','auto','‘사민필지’라는 제목은 ‘선비와 백성이 반드시 알아야 하는 것’이라는 뜻이에요. 이 제목에서 알 수 있는 헐버트의 생각은 무엇인가요?',ARRAY['K4-2-u2-X20']::text[],false,'{"seq":18,"concept":"K4-2-u2-C24","difficulty":3,"kind":"mc","stem":"‘사민필지’라는 제목은 ‘선비와 백성이 반드시 알아야 하는 것’이라는 뜻이에요. 이 제목에서 알 수 있는 헐버트의 생각은 무엇인가요?","options":[{"t":"신분과 상관없이 모든 사람이 세계에 대해 알아야 한다","correct":true},{"t":"선비만 세계에 대해 알면 된다","mis":"K4-2-u2-X20"},{"t":"백성은 책을 읽지 않아도 된다","mis":"K4-2-u2-X20"}],"explanation":["제목에 선비와 백성이 함께 들어 있어요.","신분을 가리지 않고 누구나 알아야 한다는 뜻이에요.","그래서 누구나 읽을 수 있는 한글로 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#19','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C32',3,'ox','auto','줄임말은 친구끼리도 절대 쓰면 안 되는 나쁜 말이에요.',ARRAY['K4-2-u2-X27']::text[],false,'{"seq":19,"concept":"K4-2-u2-C32","difficulty":3,"kind":"ox","stem":"줄임말은 친구끼리도 절대 쓰면 안 되는 나쁜 말이에요.","answer":"X","reason_options":[{"t":"듣는 사람이 뜻을 알고 상황에 맞으면 쓸 수 있지만 지나치게 쓰지 않아요.","correct":true},{"t":"줄임말은 어떤 상황에서든 금지예요.","mis":"K4-2-u2-X27"}],"mis":"K4-2-u2-X27","explanation":["줄임말 자체가 나쁜 말은 아니에요.","뜻을 모르는 사람과 쓰면 의사소통을 방해해요.","듣는 사람과 상황을 살펴 알맞게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#20','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C42',3,'error','auto','보고하는 글의 출처를 쓰는 방법을 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u2-X37','K4-2-u2-X57']::text[],false,'{"seq":20,"concept":"K4-2-u2-C42","difficulty":3,"kind":"error","stem":"보고하는 글의 출처를 쓰는 방법을 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수민: 누리집에서 찾았으니 출처에 「인터넷」이라고만 쓸게.","correct":true,"mis_target":"K4-2-u2-X37"},{"t":"재하: 기사를 참고했으니 기자 이름과 발행 일자도 쓸게.","mis":"K4-2-u2-X57"},{"t":"라온: 찾아본 누리집 이름과 날짜를 적어 둘게.","mis":"K4-2-u2-X37"}],"explanation":["「인터넷」은 어디인지 알 수 없는 말이에요.","어느 누리집의 어떤 자료인지 밝혀야 해요.","그래야 읽는 사람이 그 자료를 다시 찾아볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#21','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C38',3,'ox','auto','보고하는 글을 쓸 때 조사 방법은 꼭 한 가지만 골라 써야 해요.',ARRAY['K4-2-u2-X32']::text[],false,'{"seq":21,"concept":"K4-2-u2-C38","difficulty":3,"kind":"ox","stem":"보고하는 글을 쓸 때 조사 방법은 꼭 한 가지만 골라 써야 해요.","answer":"X","reason_options":[{"t":"조사할 내용에 알맞으면 여러 방법을 함께 쓸 수 있어요.","correct":true},{"t":"방법이 여러 개면 글이 엉망이 돼요.","mis":"K4-2-u2-X32"}],"mis":"K4-2-u2-X32","explanation":["지후는 설문, 면담, 인터넷 조사를 함께 썼어요.","조사할 내용마다 알맞은 방법을 골랐어요.","개수보다 알맞은 방법인지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#22','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C47',3,'match','auto','보고하는 글의 처음·가운데·끝과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"K4-2-u2-C47","difficulty":3,"kind":"match","stem":"보고하는 글의 처음·가운데·끝과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"제목, 조사 대상, 기간, 동기, 방법"},{"l":"가운데","r":"조사한 내용과 그래프 같은 매체 자료"},{"l":"끝","r":"조사 소감, 참고 자료와 그 출처"}],"mis":"K4-2-u2-X44","explanation":["처음에는 조사의 과정을 알려요.","가운데에는 조사한 사실을 매체 자료와 함께 써요.","끝에는 생각과 출처를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#23','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C27',4,'essay','teacher','『국어』 82쪽에서 단원을 시작할 때 점검한 우리말과 우리글에 대한 태도를 떠올려 보세요. 단원을 공부한 뒤 자신의 생각이 어떻게 바뀌었는지 『국어』 109쪽 「스스로 확인하기」처럼 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u2-C27","difficulty":4,"kind":"essay","stem":"『국어』 82쪽에서 단원을 시작할 때 점검한 우리말과 우리글에 대한 태도를 떠올려 보세요. 단원을 공부한 뒤 자신의 생각이 어떻게 바뀌었는지 『국어』 109쪽 「스스로 확인하기」처럼 쓰세요.","answer_guide":{"answer":"예: 처음에는 한글을 당연하게 여기고 줄임말을 아무에게나 썼다. 이 단원에서 한글이 과학적으로 만들어진 문자이고, 헐버트처럼 한글을 아낀 사람들이 있었다는 것을 알았다. 지금은 한글이 자랑스럽고, 할머니께 문자를 보낼 때 줄임말 대신 풀어 쓰려고 노력한다.","scoring_points":["단원을 시작할 때의 생각이나 태도를 썼는가","공부하며 알게 된 내용을 썼는가","바뀐 생각과 앞으로의 실천을 썼는가"]},"explanation":["『국어』 82쪽 세 물음을 다시 보아요.","처음과 지금을 견주어 써요.","정답이 없으니 솔직한 내 생각을 써요."],"asset":{"type":"passage","lines":["자신이 사용하는 말에 관심을 가지려고 노력하나요?  ○○○","한글을 소중하게 생각하는 마음을 지니고 있나요?  ○○○","우리말과 우리글을 올바르게 사용하려고 노력하나요?  ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"우리말과 우리글에 대한 자신의 태도 — 『국어』 82쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#24','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C48',4,'essay','teacher','『국어』 105쪽 스스로 확인하기의 네 물음으로 지후가 쓴 보고하는 글을 점검하고, 잘한 점 한 가지와 더 좋게 고칠 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C48","difficulty":4,"kind":"essay","stem":"『국어』 105쪽 스스로 확인하기의 네 물음으로 지후가 쓴 보고하는 글을 점검하고, 잘한 점 한 가지와 더 좋게 고칠 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 지후의 글은 주제에 맞게 썼고, 조사한 수를 열여덟 명이라고 사실대로 썼으며, 그래프를 활용하고 기사의 출처도 밝혔다. 잘한 점 — 줄임말을 쓰는 상황을 그래프로 나타내 한눈에 알기 쉽다. 고칠 점 — 면담한 친구가 몇 명인지 밝혀 쓰면 더 정확하겠다.","scoring_points":["네 물음(주제·사실·매체 자료·출처)으로 점검했는가","잘한 점을 근거를 들어 썼는가","고칠 점을 구체적으로 썼는가"]},"explanation":["주제, 사실, 매체 자료, 출처를 차례로 살펴요.","잘한 점은 글에서 찾아 근거를 대요.","고칠 점은 어떻게 고치면 좋을지까지 써요."],"asset":{"type":"passage","lines":["보고하는 글의 주제에 맞게 썼나요?  ○○○","조사한 내용을 사실에 근거해 썼나요?  ○○○","표, 그림, 사진, 그래프와 같은 매체 자료를 효과적으로 활용했나요?  ○○○","참고 자료와 그 출처를 밝혔나요?  ○○○"],"title":"스스로 확인하기 — 『국어』 105쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u2_review_d#25','kor',4,2,'u2','','tb_g4_2_kor_u2_review_d','unit_review','K4-2-u2-C27',4,'essay','teacher','『국어』 109쪽 「생활 속으로」의 활동(한글이 만들어진 과정 더 알아보기, 우리 반 친구들이 많이 쓰는 줄임말을 조사해 글로 쓰기 등) 가운데 하나를 골라 실천 계획을 세우세요. 무엇을, 어떻게, 왜 할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u2-C27","difficulty":4,"kind":"essay","stem":"『국어』 109쪽 「생활 속으로」의 활동(한글이 만들어진 과정 더 알아보기, 우리 반 친구들이 많이 쓰는 줄임말을 조사해 글로 쓰기 등) 가운데 하나를 골라 실천 계획을 세우세요. 무엇을, 어떻게, 왜 할지 쓰세요.","answer_guide":{"answer":"예: 우리 반 친구들이 많이 쓰는 줄임말을 조사해 글로 쓰겠다. 다음 주 월요일부터 금요일까지 우리 반 친구들에게 설문 조사를 하고, 결과를 그래프로 나타내 보고하는 글을 써서 학급 게시판에 붙이겠다. 친구들이 자기가 쓰는 말을 돌아보고 바른 언어생활을 하면 좋겠기 때문이다.","scoring_points":["실천할 활동을 하나 골랐는가","무엇을 어떻게 할지 구체적으로 썼는가","실천하려는 까닭이 단원에서 배운 내용과 이어지는가"]},"explanation":["한글 사랑과 보고하는 글 쓰기를 생활에서 활용할 방법을 떠올려요.","언제, 어떻게 할지 구체적으로 써요.","친구들과 결과를 나누면 더 뜻깊어요."],"asset":{"type":"passage","lines":["스스로 확인하기 — 우리말과 우리글에 대한 자신의 생각이 어떻게 바뀌었는지 쓰기","생활 속으로 — 한글이 만들어진 과정에 대하여 궁금한 내용을 더 알아보기","생활 속으로 — 우리 반 친구들이 많이 쓰는 줄임말을 조사해 글로 쓰기","생활 속으로 — (예) 한글의 특성을 알리는 만화 그리기"],"title":"마무리하기 — 『국어』 109쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
